{
  "name": "Sistema de Gestão de Estoque Marsil-Boraceia",
  "description": "Uma plataforma web para consulta de estoque e solicitações de transferência entre unidades, com suporte a upload de planilhas e controle administrativo."
}

export interface Product {
  id: string;
  fornecedor: string;
  codigo: string;
  situacao: string;
  comprador: string;
  produto: string;
  sabor: string;
  embalagem: string;
  estoqueMarsil: number;
  estoqueBoraceia: number;
}

export type RequestType = 'Teste' | 'Venda Garantida';

export interface StockRequest {
  id: string;
  productId: string;
  productName: string;
  productCode: string;
  quantidade: number;
  tipo: RequestType;
  solicitante: string;
  dataSolicitacao: string; // ISO format
  status: 'Pendente' | 'Aprovado' | 'Recusado';
}

export interface AppState {
  products: Product[];
  requests: StockRequest[];
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export const calculateDiffPercent = (marsil: number, boraceia: number): number => {
  if (marsil === 0 && boraceia === 0) return 0;
  // Let's compare Marsil vs Boraceia. If Marsil is 100 and Boraceia is 20, Marsil has 400% more.
  if (boraceia === 0) return 100;
  const diff = ((marsil - boraceia) / boraceia) * 100;
  return parseFloat(diff.toFixed(2));
};

export const formatCurrency = (value: number) => {
  return new Intl.NumberFormat('pt-BR').format(value);
};

export const isWithinLast7Days = (dateStr: string): boolean => {
  const date = new Date(dateStr);
  const now = new Date();
  const diffTime = Math.abs(now.getTime() - date.getTime());
  const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  return diffDays <= 7;
};

import React from 'react';

