);

import React, { useState, useMemo } from 'react';
import { Search, Send, AlertCircle, CheckCircle2, UserCircle, Package, Truck } from 'lucide-react';
import { Product, StockRequest, RequestType } from '../types';
import { calculateDiffPercent, isWithinLast7Days, formatCurrency } from '../utils';

interface UserPortalProps {
  products: Product[];
  requests: StockRequest[];
  onSubmitRequest: (req: Omit<StockRequest, 'id' | 'dataSolicitacao' | 'status'>) => void;
}

export const UserPortal: React.FC<UserPortalProps> = ({ products, requests, onSubmitRequest }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [formData, setFormData] = useState({
    quantidade: 0,
    tipo: 'Teste' as RequestType,
    solicitante: ''
  });
  const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  const filteredProducts = useMemo(() => {
    if (searchTerm.length < 3) return [];
    const term = searchTerm.toLowerCase();
    return products.filter(p => 
      p.codigo.toLowerCase().includes(term) ||
      p.produto.toLowerCase().includes(term) ||
      p.fornecedor.toLowerCase().includes(term)
    ).slice(0, 10); // Limit results for performance
  }, [products, searchTerm]);

  const recentRequest = useMemo(() => {
    if (!selectedProduct) return null;
    return requests.find(r => r.productId === selectedProduct.id && isWithinLast7Days(r.dataSolicitacao));
  }, [selectedProduct, requests]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedProduct || !formData.solicitante || formData.quantidade <= 0) {
      setMessage({ type: 'error', text: 'Preencha todos os campos corretamente.' });
      return;
    }

    onSubmitRequest({
      productId: selectedProduct.id,
      productName: selectedProduct.produto,
      productCode: selectedProduct.codigo,
      quantidade: formData.quantidade,
      tipo: formData.tipo,
      solicitante: formData.solicitante
    });

    setMessage({ type: 'success', text: 'Solicitação enviada com sucesso!' });
    setFormData({ quantidade: 0, tipo: 'Teste', solicitante: '' });
    setSelectedProduct(null);
    setSearchTerm('');

    setTimeout(() => setMessage(null), 3000);
  };

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
        <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
          <Search className="w-5 h-5 text-blue-600" />
          Consultar Estoque
        </h2>

        <div className="relative">
          <input
            type="text"
            placeholder="Digite código, descrição ou fornecedor (mín. 3 letras)..."
            className="w-full pl-12 pr-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
        </div>

        {searchTerm.length > 0 && searchTerm.length < 3 && (
          <p className="mt-2 text-sm text-gray-500 italic">Continue digitando para pesquisar...</p>
        )}

        {filteredProducts.length > 0 && !selectedProduct && (
          <div className="mt-4 border rounded-xl overflow-hidden divide-y divide-gray-100">
            {filteredProducts.map(p => (
              <button
                key={p.id}
                onClick={() => setSelectedProduct(p)}
                className="w-full text-left p-4 hover:bg-blue-50 transition-colors flex justify-between items-center group"
              >
                <div>
                  <p className="font-semibold text-gray-800">{p.produto}</p>
                  <p className="text-xs text-gray-500">{p.codigo} • {p.fornecedor} • {p.sabor}</p>
                </div>
                <div className="text-right">
                  <p className="text-xs font-medium text-gray-400 uppercase">Estoque Marsil</p>
                  <p className="font-bold text-blue-600">{formatCurrency(p.estoqueMarsil)}</p>
                </div>
              </button>
            ))}
          </div>
        )}
      </div>

      {selectedProduct && (
        <div className="bg-white rounded-2xl shadow-lg border border-blue-100 overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-300">
          <div className="bg-blue-600 p-4 text-white flex justify-between items-center">
            <div>
              <h3 className="text-lg font-bold">{selectedProduct.produto}</h3>
              <p className="text-sm opacity-90">{selectedProduct.codigo} | {selectedProduct.fornecedor}</p>
            </div>
            <button onClick={() => setSelectedProduct(null)} className="text-white hover:bg-blue-700 p-1 rounded">
              ✕
            </button>
          </div>

          <div className="p-6 grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-gray-50 p-4 rounded-xl border border-gray-200">
              <p className="text-sm text-gray-500 font-medium mb-1">Estoque Marsil</p>
              <p className="text-2xl font-bold text-gray-900">{formatCurrency(selectedProduct.estoqueMarsil)}</p>
            </div>
            <div className="bg-gray-50 p-4 rounded-xl border border-gray-200">
              <p className="text-sm text-gray-500 font-medium mb-1">Estoque Boracéia</p>
              <p className="text-2xl font-bold text-gray-900">{formatCurrency(selectedProduct.estoqueBoraceia)}</p>
            </div>
            <div className="bg-blue-50 p-4 rounded-xl border border-blue-200 flex flex-col justify-center">
              <p className="text-sm text-blue-600 font-medium mb-1">Diferença Percentual</p>
              <p className={`text-2xl font-bold ${calculateDiffPercent(selectedProduct.estoqueMarsil, selectedProduct.estoqueBoraceia) > 0 ? 'text-green-600' : 'text-red-600'}`}>
                {calculateDiffPercent(selectedProduct.estoqueMarsil, selectedProduct.estoqueBoraceia)}%
              </p>
              <p className="text-xs text-blue-400">Marsil vs Boracéia</p>
            </div>
          </div>

          {recentRequest && (
            <div className="mx-6 mb-6 p-4 bg-amber-50 border border-amber-200 rounded-xl flex items-start gap-3">
              <AlertCircle className="w-5 h-5 text-amber-600 mt-0.5" />
              <div>
                <p className="text-amber-800 font-semibold">Já solicitado recentemente!</p>
                <p className="text-sm text-amber-700">
                  {recentRequest.solicitante} solicitou {recentRequest.quantidade} un em {new Date(recentRequest.dataSolicitacao).toLocaleDateString()}.
                </p>
              </div>
            </div>
          )}

          <form onSubmit={handleSubmit} className="p-6 pt-0 border-t border-gray-100 space-y-4 mt-4">
            <h4 className="font-bold text-gray-700 mb-2 flex items-center gap-2">
              <Truck className="w-5 h-5" /> Enviar para Boracéia
            </h4>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-600 mb-1">Solicitante</label>
                <div className="relative">
                  <UserCircle className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                  <input
                    type="text"
                    required
                    className="w-full pl-9 pr-4 py-2 rounded-lg border border-gray-200 focus:ring-2 focus:ring-blue-500 outline-none"
                    placeholder="Seu nome"
                    value={formData.solicitante}
                    onChange={(e) => setFormData({...formData, solicitante: e.target.value})}
                  />
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-600 mb-1">Quantidade</label>
                <div className="relative">
                  <Package className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                  <input
                    type="number"
                    required
                    min="1"
                    className="w-full pl-9 pr-4 py-2 rounded-lg border border-gray-200 focus:ring-2 focus:ring-blue-500 outline-none"
                    placeholder="0"
                    value={formData.quantidade || ''}
                    onChange={(e) => setFormData({...formData, quantidade: parseInt(e.target.value) || 0})}
                  />
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-600 mb-1">Tipo de Solicitação</label>
                <select
                  className="w-full px-4 py-2 rounded-lg border border-gray-200 focus:ring-2 focus:ring-blue-500 outline-none appearance-none bg-white"
                  value={formData.tipo}
                  onChange={(e) => setFormData({...formData, tipo: e.target.value as RequestType})}
                >
                  <option value="Teste">Teste</option>
                  <option value="Venda Garantida">Venda Garantida</option>
                </select>
              </div>
            </div>

            <button
              type="submit"
              className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 rounded-xl transition-all transform active:scale-95 flex items-center justify-center gap-2 shadow-lg shadow-blue-200"
            >
              <Send className="w-5 h-5" />
              Enviar Solicitação de Transferência
            </button>
          </form>
        </div>
      )}

      {message && (
        <div className={`fixed bottom-8 left-1/2 -translate-x-1/2 px-6 py-3 rounded-full shadow-2xl flex items-center gap-3 animate-in fade-in slide-in-from-bottom-10 ${
          message.type === 'success' ? 'bg-green-600 text-white' : 'bg-red-600 text-white'
        }`}>
          {message.type === 'success' ? <CheckCircle2 className="w-5 h-5" /> : <AlertCircle className="w-5 h-5" />}
          <span className="font-medium">{message.text}</span>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Upload, ListChecks, Database, FileText, CheckCircle, XCircle, Trash2, Users } from 'lucide-react';
import { Product, StockRequest, AppState } from '../types';
import { StatsCard } from './StatsCard';

interface AdminPortalProps {
  appState: AppState;
  onUploadData: (newProducts: Product[]) => void;
  onUpdateRequestStatus: (requestId: string, status: StockRequest['status']) => void;
  onClearRequests: () => void;
}

export const AdminPortal: React.FC<AdminPortalProps> = ({ 
  appState, 
  onUploadData, 
  onUpdateRequestStatus,
  onClearRequests
}) => {
  const [dragActive, setDragActive] = useState(false);
  const [uploadStatus, setUploadStatus] = useState<string | null>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement> | React.DragEvent) => {
    let file: File | null = null;
    if ('files' in e.target && e.target.files) {
      file = e.target.files[0];
    } else if ('dataTransfer' in e && e.dataTransfer.files) {
      file = e.dataTransfer.files[0];
    }

    if (!file) return;

    setUploadStatus('Lendo arquivo...');
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target?.result as string;
        // Mock parsing for CSV format as per the image
        // Headers: FORNECEDOR, NOVO CODIGO, CODIGO, SITUACAO, COMPRADOR, PRODUTO, SABOR, EMBALAGEM, ESTOQUE_MARSIL, ESTOQUE_BORACEIA
        const rows = text.split('\n').filter(r => r.trim() !== '');
        const dataRows = rows.slice(1); // Remove header

        const parsedProducts: Product[] = dataRows.map((row, index) => {
          const cols = row.split(/,|;/); // Basic split
          return {
            id: `p-${index}`,
            fornecedor: cols[0]?.trim() || 'N/A',
            codigo: cols[2]?.trim() || '0',
            situacao: cols[3]?.trim() || '',
            comprador: cols[4]?.trim() || '',
            produto: cols[5]?.trim() || '',
            sabor: cols[6]?.trim() || '',
            embalagem: cols[7]?.trim() || '',
            estoqueMarsil: parseInt(cols[8]) || 0,
            estoqueBoraceia: parseInt(cols[9]) || 0,
          };
        });

        onUploadData(parsedProducts);
        setUploadStatus(`Sucesso! ${parsedProducts.length} itens carregados.`);
        setTimeout(() => setUploadStatus(null), 3000);
      } catch (err) {
        setUploadStatus('Erro ao processar arquivo. Verifique o formato.');
      }
    };
    reader.readAsText(file);
  };

  const totalMarsil = appState.products.reduce((acc, p) => acc + p.estoqueMarsil, 0);
  const totalRequests = appState.requests.length;
  const pendingRequests = appState.requests.filter(r => r.status === 'Pendente').length;

  return (
    <div className="space-y-8 max-w-6xl mx-auto">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <StatsCard label="Produtos na Base" value={appState.products.length} icon={<Database />} color="bg-blue-600" />
        <StatsCard label="Total Solicitações" value={totalRequests} icon={<FileText />} color="bg-purple-600" />
        <StatsCard label="Pendentes" value={pendingRequests} icon={<ListChecks />} color="bg-amber-600" />
        <StatsCard label="Usuários Ativos" value={new Set(appState.requests.map(r => r.solicitante)).size} icon={<Users />} color="bg-emerald-600" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Upload Section */}
        <div className="lg:col-span-1 space-y-6">
          <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
            <h3 className="text-lg font-bold mb-4 flex items-center gap-2">
              <Upload className="w-5 h-5 text-blue-600" />
              Atualizar Base de Dados
            </h3>
            <p className="text-sm text-gray-500 mb-6">
              Faça o upload da planilha diária (CSV) para atualizar os níveis de estoque globais.
            </p>

            <label 
              className={`border-2 border-dashed rounded-xl p-8 flex flex-col items-center justify-center transition-all cursor-pointer ${
                dragActive ? 'border-blue-500 bg-blue-50' : 'border-gray-200 hover:border-blue-400'
              }`}
              onDragOver={(e) => { e.preventDefault(); setDragActive(true); }}
              onDragLeave={() => setDragActive(false)}
              onDrop={(e) => { e.preventDefault(); setDragActive(false); handleFileUpload(e); }}
            >
              <Upload className="w-10 h-10 text-gray-300 mb-3" />
              <p className="text-sm font-medium text-gray-600">Arraste a planilha ou clique aqui</p>
              <p className="text-xs text-gray-400 mt-1">Formato suportado: CSV</p>
              <input type="file" className="hidden" accept=".csv" onChange={handleFileUpload} />
            </label>

            {uploadStatus && (
              <div className={`mt-4 p-3 rounded-lg text-sm text-center font-medium ${
                uploadStatus.includes('Erro') ? 'bg-red-50 text-red-600' : 'bg-green-50 text-green-600'
              }`}>
                {uploadStatus}
              </div>
            )}
          </div>

          <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
            <h3 className="text-lg font-bold mb-4 flex items-center gap-2 text-red-600">
              <Trash2 className="w-5 h-5" />
              Limpeza de Dados
            </h3>
            <button 
              onClick={onClearRequests}
              className="w-full py-2 border border-red-200 text-red-600 rounded-lg hover:bg-red-50 transition-colors text-sm font-semibold"
            >
              Zerar Histórico de Solicitações
            </button>
          </div>
        </div>

        {/* Requests List */}
        <div className="lg:col-span-2">
          <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
            <div className="p-6 border-b border-gray-50 flex justify-between items-center">
              <h3 className="text-lg font-bold flex items-center gap-2">
                <ListChecks className="w-5 h-5 text-blue-600" />
                Solicitações Recentes
              </h3>
              <span className="text-xs font-medium bg-blue-50 text-blue-600 px-2.5 py-1 rounded-full uppercase">
                {appState.requests.length} total
              </span>
            </div>

            <div className="overflow-x-auto">
              {appState.requests.length === 0 ? (
                <div className="p-12 text-center text-gray-400">
                  <FileText className="w-12 h-12 mx-auto mb-3 opacity-20" />
                  <p>Nenhuma solicitação pendente.</p>
                </div>
              ) : (
                <table className="w-full">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-6 py-4 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Solicitante</th>
                      <th className="px-6 py-4 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Produto</th>
                      <th className="px-6 py-4 text-left text-xs font-bold text-gray-500 uppercase tracking-wider text-center">Quant.</th>
                      <th className="px-6 py-4 text-left text-xs font-bold text-gray-500 uppercase tracking-wider text-center">Tipo</th>
                      <th className="px-6 py-4 text-right text-xs font-bold text-gray-500 uppercase tracking-wider">Ações</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100">
                    {appState.requests.map(req => (
                      <tr key={req.id} className="hover:bg-gray-50 transition-colors">
                        <td className="px-6 py-4 whitespace-nowrap">
                          <div className="flex items-center gap-3">
                            <div className="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold text-xs">
                              {req.solicitante.charAt(0).toUpperCase()}
                            </div>
                            <div>
                              <p className="text-sm font-semibold text-gray-900">{req.solicitante}</p>
                              <p className="text-xs text-gray-400">{new Date(req.dataSolicitacao).toLocaleDateString()}</p>
                            </div>
                          </div>
                        </td>
                        <td className="px-6 py-4">
                          <p className="text-sm text-gray-900 font-medium line-clamp-1">{req.productName}</p>
                          <p className="text-xs text-gray-400">{req.productCode}</p>
                        </td>
                        <td className="px-6 py-4 text-center">
                          <span className="text-sm font-bold text-gray-900">{req.quantidade}</span>
                        </td>
                        <td className="px-6 py-4 text-center">
                          <span className={`text-[10px] font-bold px-2 py-1 rounded-full uppercase ${
                            req.tipo === 'Teste' ? 'bg-purple-50 text-purple-600' : 'bg-blue-50 text-blue-600'
                          }`}>
                            {req.tipo}
                          </span>
                        </td>
                        <td className="px-6 py-4 text-right">
                          {req.status === 'Pendente' ? (
                            <div className="flex justify-end gap-2">
                              <button 
                                onClick={() => onUpdateRequestStatus(req.id, 'Aprovado')}
                                className="p-2 text-green-600 hover:bg-green-50 rounded-lg transition-colors"
                                title="Aprovar"
                              >
                                <CheckCircle className="w-5 h-5" />
                              </button>
                              <button 
                                onClick={() => onUpdateRequestStatus(req.id, 'Recusado')}
                                className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                title="Recusar"
                              >
                                <XCircle className="w-5 h-5" />
                              </button>
                            </div>
                          ) : (
                            <span className={`text-xs font-bold ${
                              req.status === 'Aprovado' ? 'text-green-600' : 'text-red-600'
                            }`}>
                              {req.status}
                            </span>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { UserPortal } from './components/UserPortal';
import { AdminPortal } from './components/AdminPortal';
import { AppState, Product, StockRequest } from './types';
import { LayoutDashboard, Users, ShieldCheck, Github } from 'lucide-react';

const STORAGE_KEY = 'marsil_boraceia_db_v1';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'user' | 'admin'>('user');
  const [appState, setAppState] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : { products: [], requests: [] };
  });

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(appState));
  }, [appState]);

  const handleUploadData = (newProducts: Product[]) => {
    setAppState(prev => ({ ...prev, products: newProducts }));
  };

  const handleSubmitRequest = (req: Omit<StockRequest, 'id' | 'dataSolicitacao' | 'status'>) => {
    const newRequest: StockRequest = {
      ...req,
      id: `req-${Date.now()}`,
      dataSolicitacao: new Date().toISOString(),
      status: 'Pendente'
    };
    setAppState(prev => ({
      ...prev,
      requests: [newRequest, ...prev.requests]
    }));
  };

  const handleUpdateRequestStatus = (requestId: string, status: StockRequest['status']) => {
    setAppState(prev => ({
      ...prev,
      requests: prev.requests.map(r => r.id === requestId ? { ...r, status } : r)
    }));
  };

  const handleClearRequests = () => {
    if (window.confirm('Deseja realmente apagar todo o histórico de solicitações?')) {
      setAppState(prev => ({ ...prev, requests: [] }));
    }
  };

  return (
    <div className="min-h-screen flex flex-col">
      {/* Header */}
