  products: Product[];
  requests: StockRequest[];
  onSubmitRequest: (req: Omit<StockRequest, 'id' | 'dataSolicitacao' | 'status'>) => void;
}

export const UserPortal: React.FC<UserPortalProps> = ({ products, requests, onSubmitRequest }) => {
  const [filterCodigo, setFilterCodigo] = useState('');
  const [filterFornecedor, setFilterFornecedor] = useState('');
  const [filterDescricao, setFilterDescricao] = useState('');

  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [formData, setFormData] = useState({
    quantidade: 0,
    tipo: 'Teste' as RequestType,
    solicitante: ''
  });
  const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  const hasSearch = useMemo(() => {
    return filterCodigo.length >= 2 || filterFornecedor.length >= 3 || filterDescricao.length >= 3;
  }, [filterCodigo, filterFornecedor, filterDescricao]);

  const filteredProducts = useMemo(() => {
    if (!hasSearch) return [];

    return products.filter(p => {
      const matchCodigo = filterCodigo === '' || p.codigo.toLowerCase().includes(filterCodigo.toLowerCase());
      const matchFornecedor = filterFornecedor === '' || p.fornecedor.toLowerCase().includes(filterFornecedor.toLowerCase());
      const matchDescricao = filterDescricao === '' || p.produto.toLowerCase().includes(filterDescricao.toLowerCase());

      return matchCodigo && matchFornecedor && matchDescricao;
    }).slice(0, 20); // Show more results now that we have better filters
  }, [products, filterCodigo, filterFornecedor, filterDescricao, hasSearch]);

  const recentRequest = useMemo(() => {
    if (!selectedProduct) return null;
    return requests.find(r => r.productId === selectedProduct.id && isWithinLast7Days(r.dataSolicitacao));
  }, [selectedProduct, requests]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedProduct || !formData.solicitante || formData.quantidade <= 0) {
      setMessage({ type: 'error', text: 'Preencha todos os campos corretamente.' });
      return;
    }

    const fullProductName = selectedProduct.sabor 
      ? `${selectedProduct.produto} - ${selectedProduct.sabor}`
      : selectedProduct.produto;

    onSubmitRequest({
      productId: selectedProduct.id,
      productName: fullProductName,
      productCode: selectedProduct.codigo,
      quantidade: formData.quantidade,
      tipo: formData.tipo,
      solicitante: formData.solicitante
    });

    setMessage({ type: 'success', text: 'Solicitação enviada com sucesso!' });
    setFormData({ quantidade: 0, tipo: 'Teste', solicitante: '' });
    setSelectedProduct(null);
    setFilterCodigo('');
    setFilterFornecedor('');
    setFilterDescricao('');

    setTimeout(() => setMessage(null), 3000);
  };

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
        <h2 className="text-xl font-bold mb-6 flex items-center gap-2">
          <Filter className="w-5 h-5 text-blue-600" />
          Filtros de Consulta
        </h2>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
          <div className="space-y-1">
            <label className="text-xs font-bold text-gray-500 uppercase ml-1">Cód. Item</label>
            <div className="relative">
              <input
                type="text"
                placeholder="Ex: 1234..."
                className="w-full pl-10 pr-4 py-2.5 rounded-xl border border-gray-200 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all text-sm"
                value={filterCodigo}
                onChange={(e) => setFilterCodigo(e.target.value)}
              />
              <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
            </div>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold text-gray-500 uppercase ml-1">Fornecedor</label>
            <div className="relative">
              <input
                type="text"
                placeholder="Buscar fornecedor..."
                className="w-full pl-10 pr-4 py-2.5 rounded-xl border border-gray-200 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all text-sm"
                value={filterFornecedor}
                onChange={(e) => setFilterFornecedor(e.target.value)}
              />
              <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
            </div>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold text-gray-500 uppercase ml-1">Descrição / Produto</label>
            <div className="relative">
              <input
                type="text"
                placeholder="Buscar produto..."
                className="w-full pl-10 pr-4 py-2.5 rounded-xl border border-gray-200 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all text-sm"
                value={filterDescricao}
                onChange={(e) => setFilterDescricao(e.target.value)}
              />
              <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
            </div>
          </div>
        </div>

        {!hasSearch && (
          <p className="mt-2 text-sm text-gray-500 italic flex items-center gap-2">
            <AlertCircle className="w-4 h-4" />
            Preencha um dos filtros para visualizar os produtos.
          </p>
        )}

        {hasSearch && filteredProducts.length === 0 && (
          <p className="mt-2 text-sm text-amber-600 font-medium">Nenhum produto encontrado com esses filtros.</p>
        )}

        {filteredProducts.length > 0 && !selectedProduct && (
          <div className="mt-6 border rounded-xl overflow-hidden divide-y divide-gray-100 shadow-sm">
            <div className="bg-gray-50 px-4 py-2 text-[10px] font-bold text-gray-400 uppercase grid grid-cols-12 gap-2">
              <div className="col-span-6 md:col-span-7">Produto / Sabor / Embalagem</div>
              <div className="col-span-3 md:col-span-2 text-center">Código</div>
              <div className="col-span-3 text-right">Estoque Marsil</div>
            </div>
            {filteredProducts.map(p => (
              <button
                key={p.id}
                onClick={() => setSelectedProduct(p)}
                className="w-full text-left p-4 hover:bg-blue-50 transition-colors grid grid-cols-12 gap-2 items-center group"
              >
                <div className="col-span-6 md:col-span-7">
                  <p className="font-semibold text-gray-800 leading-tight">
                    {p.produto}{p.sabor ? ` - ${p.sabor}` : ''}
                  </p>
                  <div className="flex flex-wrap gap-x-3 gap-y-1 mt-1">
                    <span className="text-xs text-blue-600 font-medium">{p.fornecedor}</span>
                    <span className="text-xs text-gray-400 border-l border-gray-200 pl-3">Emb: <span className="font-semibold text-gray-600">{p.embalagem}</span></span>
                  </div>
                </div>
                <div className="col-span-3 md:col-span-2 text-center">
                  <p className="text-xs font-mono font-bold text-gray-500">{p.codigo}</p>
                </div>
                <div className="col-span-3 text-right">
                  <p className="font-bold text-blue-600">{formatCurrency(p.estoqueMarsil)}</p>
                </div>
              </button>
            ))}
          </div>
        )}
      </div>

      {selectedProduct && (
        <div className="bg-white rounded-2xl shadow-lg border border-blue-100 overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-300">
          <div className="bg-blue-600 p-4 text-white flex justify-between items-center">
            <div>
              <h3 className="text-lg font-bold">
                {selectedProduct.produto}{selectedProduct.sabor ? ` - ${selectedProduct.sabor}` : ''}
              </h3>
              <p className="text-sm opacity-90 flex items-center gap-2">
                <span className="font-mono bg-blue-700 px-1.5 rounded">{selectedProduct.codigo}</span>
                <span>|</span>
                <span>{selectedProduct.fornecedor}</span>
                <span>|</span>
                <span className="bg-blue-500/30 px-2 rounded">Embalagem: {selectedProduct.embalagem}</span>
              </p>
            </div>
            <button onClick={() => setSelectedProduct(null)} className="text-white hover:bg-blue-700 p-1 rounded transition-colors">
              ✕
            </button>
          </div>

          <div className="p-6 grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-gray-50 p-4 rounded-xl border border-gray-200">
              <p className="text-sm text-gray-500 font-medium mb-1">Estoque Marsil</p>
              <p className="text-2xl font-bold text-gray-900">{formatCurrency(selectedProduct.estoqueMarsil)}</p>
            </div>
            <div className="bg-gray-50 p-4 rounded-xl border border-gray-200">
              <p className="text-sm text-gray-500 font-medium mb-1">Estoque Boracéia</p>
              <p className="text-2xl font-bold text-gray-900">{formatCurrency(selectedProduct.estoqueBoraceia)}</p>
            </div>
            <div className="bg-blue-50 p-4 rounded-xl border border-blue-200 flex flex-col justify-center">
              <p className="text-sm text-blue-600 font-medium mb-1">Diferença Percentual</p>
              <p className={`text-2xl font-bold ${calculateDiffPercent(selectedProduct.estoqueMarsil, selectedProduct.estoqueBoraceia) > 0 ? 'text-green-600' : 'text-red-600'}`}>
                {calculateDiffPercent(selectedProduct.estoqueMarsil, selectedProduct.estoqueBoraceia)}%
              </p>
              <p className="text-xs text-blue-400">Marsil vs Boracéia</p>
            </div>
          </div>

          {recentRequest && (
            <div className="mx-6 mb-6 p-4 bg-amber-50 border border-amber-200 rounded-xl flex items-start gap-3">
              <AlertCircle className="w-5 h-5 text-amber-600 mt-0.5" />
              <div>
                <p className="text-amber-800 font-semibold">Já solicitado recentemente!</p>
                <p className="text-sm text-amber-700">
                  {recentRequest.solicitante} solicitou {recentRequest.quantidade} un em {new Date(recentRequest.dataSolicitacao).toLocaleDateString()}.
                </p>
              </div>
            </div>
          )}

          <form onSubmit={handleSubmit} className="p-6 pt-0 border-t border-gray-100 space-y-4 mt-4">
            <h4 className="font-bold text-gray-700 mb-2 flex items-center gap-2">
              <Truck className="w-5 h-5" /> Enviar para Boracéia
            </h4>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-600 mb-1">Solicitante</label>
                <div className="relative">
                  <UserCircle className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                  <input
                    type="text"
                    required
                    className="w-full pl-9 pr-4 py-2 rounded-lg border border-gray-200 focus:ring-2 focus:ring-blue-500 outline-none"
                    placeholder="Seu nome"
                    value={formData.solicitante}
                    onChange={(e) => setFormData({...formData, solicitante: e.target.value})}
                  />
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-600 mb-1">Quantidade</label>
                <div className="relative">
                  <Package className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                  <input
                    type="number"
                    required
                    min="1"
                    className="w-full pl-9 pr-4 py-2 rounded-lg border border-gray-200 focus:ring-2 focus:ring-blue-500 outline-none"
                    placeholder="0"
                    value={formData.quantidade || ''}
                    onChange={(e) => setFormData({...formData, quantidade: parseInt(e.target.value) || 0})}
                  />
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-600 mb-1">Tipo de Solicitação</label>
                <select
                  className="w-full px-4 py-2 rounded-lg border border-gray-200 focus:ring-2 focus:ring-blue-500 outline-none appearance-none bg-white"
                  value={formData.tipo}
                  onChange={(e) => setFormData({...formData, tipo: e.target.value as RequestType})}
                >
                  <option value="Teste">Teste</option>
                  <option value="Venda Garantida">Venda Garantida</option>
                </select>
              </div>
            </div>

            <button
              type="submit"
              className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 rounded-xl transition-all transform active:scale-95 flex items-center justify-center gap-2 shadow-lg shadow-blue-200"
            >
              <Send className="w-5 h-5" />
              Enviar Solicitação de Transferência
            </button>
          </form>
        </div>
      )}

      {message && (
        <div className={`fixed bottom-8 left-1/2 -translate-x-1/2 px-6 py-3 rounded-full shadow-2xl flex items-center gap-3 animate-in fade-in slide-in-from-bottom-10 z-[100] ${
          message.type === 'success' ? 'bg-green-600 text-white' : 'bg-red-600 text-white'
        }`}>
          {message.type === 'success' ? <CheckCircle2 className="w-5 h-5" /> : <AlertCircle className="w-5 h-5" />}
          <span className="font-medium">{message.text}</span>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { UserPortal } from './components/UserPortal';
import { AdminPortal } from './components/AdminPortal';
import { AppState, Product, StockRequest } from './types';
import { LayoutDashboard, Users, ShieldCheck, Sun, Moon } from 'lucide-react';

const STORAGE_KEY = 'marsil_boraceia_db_v1';
const THEME_KEY = 'marsil_theme_pref';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'user' | 'admin'>('user');
  const [isDarkMode, setIsDarkMode] = useState(() => {
    const savedTheme = localStorage.getItem(THEME_KEY);
    return savedTheme === 'dark';
  });

  const [appState, setAppState] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : { products: [], requests: [] };
  });

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(appState));
  }, [appState]);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem(THEME_KEY, 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem(THEME_KEY, 'light');
    }
  }, [isDarkMode]);

  const handleUploadData = (newProducts: Product[]) => {
    setAppState(prev => ({ ...prev, products: newProducts }));
  };

  const handleSubmitRequest = (req: Omit<StockRequest, 'id' | 'dataSolicitacao' | 'status'>) => {
    const newRequest: StockRequest = {
      ...req,
      id: `req-${Date.now()}`,
      dataSolicitacao: new Date().toISOString(),
      status: 'Pendente'
    };
    setAppState(prev => ({
      ...prev,
      requests: [newRequest, ...prev.requests]
    }));
  };

  const handleUpdateRequestStatus = (requestId: string, status: StockRequest['status']) => {
    setAppState(prev => ({
      ...prev,
      requests: prev.requests.map(r => r.id === requestId ? { ...r, status } : r)
    }));
  };

  const handleClearRequests = () => {
    if (window.confirm('Deseja realmente apagar todo o histórico de solicitações?')) {
      setAppState(prev => ({ ...prev, requests: [] }));
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-slate-950 text-gray-900 dark:text-slate-100 transition-colors duration-300">
      {/* Header */}
      <header className="bg-white dark:bg-slate-900 border-b border-gray-200 dark:border-slate-800 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-3">
              <div className="bg-blue-600 p-2 rounded-lg">
                <LayoutDashboard className="w-6 h-6 text-white" />
              </div>
              <div className="hidden sm:block">
                <h1 className="text-xl font-bold bg-gradient-to-r from-blue-700 to-blue-500 bg-clip-text text-transparent">
                  Marsil & Boracéia
                </h1>
                <p className="text-[10px] text-gray-400 dark:text-slate-500 font-bold tracking-widest uppercase">
                  Gestão de Estoque
                </p>
              </div>
            </div>

            <div className="flex items-center gap-4">
              <button
                onClick={() => setIsDarkMode(!isDarkMode)}
                className="p-2 rounded-lg bg-gray-100 dark:bg-slate-800 text-gray-600 dark:text-slate-400 hover:text-blue-600 dark:hover:text-blue-400 transition-colors"
                title="Alternar Tema"
              >
                {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
              </button>

              <nav className="flex space-x-1 bg-gray-100 dark:bg-slate-800 p-1 rounded-xl">
                <button
                  onClick={() => setActiveTab('user')}
                  className={`flex items-center gap-2 px-4 py-2 text-sm font-semibold rounded-lg transition-all ${
                    activeTab === 'user' 
                      ? 'bg-white dark:bg-slate-700 text-blue-600 dark:text-blue-400 shadow-sm' 
                      : 'text-gray-500 dark:text-slate-400 hover:text-gray-700 dark:hover:text-slate-200'
                  }`}
                >
                  <Users className="w-4 h-4" />
                  Vendedor
                </button>
                <button
                  onClick={() => setActiveTab('admin')}
                  className={`flex items-center gap-2 px-4 py-2 text-sm font-semibold rounded-lg transition-all ${
                    activeTab === 'admin' 
                      ? 'bg-white dark:bg-slate-700 text-blue-600 dark:text-blue-400 shadow-sm' 
                      : 'text-gray-500 dark:text-slate-400 hover:text-gray-700 dark:hover:text-slate-200'
                  }`}
                >
                  <ShieldCheck className="w-4 h-4" />
                  Admin
                </button>
              </nav>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-grow p-4 sm:p-6 lg:p-8">
        {activeTab === 'user' ? (
          <UserPortal 
            products={appState.products} 
            requests={appState.requests}
            onSubmitRequest={handleSubmitRequest}
          />
        ) : (
          <AdminPortal 
            appState={appState}
            onUploadData={handleUploadData}
            onUpdateRequestStatus={handleUpdateRequestStatus}
            onClearRequests={handleClearRequests}
          />
        )}
      </main>

      {/* Footer */}
      <footer className="bg-white dark:bg-slate-900 border-t border-gray-100 dark:border-slate-800 py-6">
        <div className="max-w-7xl mx-auto px-4 flex flex-col md:flex-row justify-between items-center gap-4 text-gray-400 dark:text-slate-500 text-sm">
          <p>© 2024 Marsil Logística. Todos os direitos reservados.</p>
          <div className="flex items-center gap-4">
            <span className="flex items-center gap-1">
              <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
              Sistema Operacional
            </span>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

