                    </p>
                    <div className="flex flex-wrap gap-x-3 gap-y-1 mt-1">
                      <span className="text-xs text-blue-600 dark:text-blue-400 font-medium">{p.fornecedor}</span>
                      <span className="text-xs text-gray-400 dark:text-slate-500 border-l border-gray-200 dark:border-slate-700 pl-3">Emb: <span className="font-semibold text-gray-600 dark:text-slate-300">{p.embalagem}</span></span>
                    </div>
                  </div>
                  <div className="col-span-3 md:col-span-2 text-center">
                    <p className="text-xs font-mono font-bold text-gray-500 dark:text-slate-500">{p.codigo}</p>
                  </div>
                  <div className="col-span-3 text-right">
                    <p className="font-bold text-blue-600 dark:text-blue-400">{formatCurrency(p.estoqueMarsil)}</p>
                  </div>
                </button>
              ))}
            </div>

            {/* Pagination Controls */}
            {totalPages > 1 && (
              <div className="flex flex-col sm:flex-row items-center justify-between gap-4 py-2 px-1">
                <p className="text-xs text-gray-500 dark:text-slate-400">
                  Mostrando <span className="font-bold text-gray-700 dark:text-slate-200">{(currentPage - 1) * ITEMS_PER_PAGE + 1}</span> a <span className="font-bold text-gray-700 dark:text-slate-200">{Math.min(currentPage * ITEMS_PER_PAGE, filteredProducts.length)}</span> de <span className="font-bold text-gray-700 dark:text-slate-200">{filteredProducts.length}</span> produtos
                </p>
                <div className="flex items-center gap-1">
                  <button
                    onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                    disabled={currentPage === 1}
                    className="p-2 rounded-lg border border-gray-200 dark:border-slate-700 hover:bg-gray-50 dark:hover:bg-slate-800 disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
                  >
                    <ChevronLeft className="w-4 h-4 dark:text-slate-300" />
                  </button>

                  {/* Page numbers (simplified version) */}
                  <div className="flex items-center gap-1 mx-2">
                    {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                      let pageNum = i + 1;
                      if (totalPages > 5 && currentPage > 3) {
                        pageNum = currentPage - 3 + i + 1;
                        if (pageNum > totalPages) pageNum = totalPages - (4 - i);
                      }
                      if (pageNum <= 0) return null;

                      return (
                        <button
                          key={pageNum}
                          onClick={() => setCurrentPage(pageNum)}
                          className={`w-8 h-8 rounded-lg text-xs font-bold transition-all ${
                            currentPage === pageNum
                              ? 'bg-blue-600 text-white shadow-md shadow-blue-200 dark:shadow-none'
                              : 'text-gray-500 dark:text-slate-400 hover:bg-gray-100 dark:hover:bg-slate-800 border border-transparent'
                          }`}
                        >
                          {pageNum}
                        </button>
                      );
                    })}
                  </div>

                  <button
                    onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                    disabled={currentPage === totalPages}
                    className="p-2 rounded-lg border border-gray-200 dark:border-slate-700 hover:bg-gray-50 dark:hover:bg-slate-800 disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
                  >
                    <ChevronRight className="w-4 h-4 dark:text-slate-300" />
                  </button>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {selectedProduct && (
        <div className="bg-white dark:bg-slate-900 rounded-2xl shadow-lg border border-blue-100 dark:border-slate-800 overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-300">
          <div className="bg-blue-600 dark:bg-blue-700 p-4 text-white flex justify-between items-center">
            <div>
              <h3 className="text-lg font-bold">
                {selectedProduct.produto}{selectedProduct.sabor ? ` - ${selectedProduct.sabor}` : ''}
