              <p className="text-sm opacity-90 flex items-center gap-2">
                <span className="font-mono bg-blue-700 dark:bg-blue-800 px-1.5 rounded">{selectedProduct.codigo}</span>
                <span>|</span>
                <span>{selectedProduct.fornecedor}</span>
                <span>|</span>
                <span className="bg-blue-500/30 dark:bg-blue-400/20 px-2 rounded">Embalagem: {selectedProduct.embalagem}</span>
              </p>
            </div>
            <button onClick={() => setSelectedProduct(null)} className="text-white hover:bg-blue-700 dark:hover:bg-blue-800 p-1 rounded transition-colors">
              ✕
            </button>
          </div>

          <div className="p-6 grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-gray-50 dark:bg-slate-800 p-4 rounded-xl border border-gray-200 dark:border-slate-700">
              <p className="text-sm text-gray-500 dark:text-slate-400 font-medium mb-1">Estoque Marsil</p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">{formatCurrency(selectedProduct.estoqueMarsil)}</p>
            </div>
            <div className="bg-gray-50 dark:bg-slate-800 p-4 rounded-xl border border-gray-200 dark:border-slate-700">
              <p className="text-sm text-gray-500 dark:text-slate-400 font-medium mb-1">Estoque Boracéia</p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">{formatCurrency(selectedProduct.estoqueBoraceia)}</p>
