            <div className="bg-blue-50 dark:bg-blue-900/20 p-4 rounded-xl border border-blue-200 dark:border-blue-900/50 flex flex-col justify-center">
              <p className="text-sm text-blue-600 dark:text-blue-400 font-medium mb-1">Diferença Percentual</p>
