        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Upload, ListChecks, Database, FileText, CheckCircle, XCircle, Trash2, Users, Download } from 'lucide-react';
import { Product, StockRequest, AppState } from '../types';
import { StatsCard } from './StatsCard';

interface AdminPortalProps {
  appState: AppState;
  onUploadData: (newProducts: Product[]) => void;
  onUpdateRequestStatus: (requestId: string, status: StockRequest['status']) => void;
  onClearRequests: () => void;
}

export const AdminPortal: React.FC<AdminPortalProps> = ({ 
  appState, 
  onUploadData, 
  onUpdateRequestStatus,
  onClearRequests
}) => {
  const [dragActive, setDragActive] = useState(false);
  const [uploadStatus, setUploadStatus] = useState<string | null>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement> | React.DragEvent) => {
    let file: File | null = null;
    if ('files' in e.target && e.target.files) {
      file = e.target.files[0];
    } else if ('dataTransfer' in e && e.dataTransfer.files) {
      file = e.dataTransfer.files[0];
    }

    if (!file) return;

    setUploadStatus('Lendo arquivo...');
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target?.result as string;
        const rows = text.split('\n').filter(r => r.trim() !== '');
        const dataRows = rows.slice(1);

        const parsedProducts: Product[] = dataRows.map((row, index) => {
          const cols = row.split(/,|;/);
          return {
            id: `p-${index}`,
            fornecedor: cols[0]?.trim() || 'N/A',
            codigo: cols[2]?.trim() || '0',
            situacao: cols[3]?.trim() || '',
            comprador: cols[4]?.trim() || '',
            produto: cols[5]?.trim() || '',
            sabor: cols[6]?.trim() || '',
            embalagem: cols[7]?.trim() || '',
            estoqueMarsil: parseInt(cols[8]) || 0,
            estoqueBoraceia: parseInt(cols[9]) || 0,
          };
        });

        onUploadData(parsedProducts);
        setUploadStatus(`Sucesso! ${parsedProducts.length} itens carregados.`);
        setTimeout(() => setUploadStatus(null), 3000);
      } catch (err) {
        setUploadStatus('Erro ao processar arquivo. Verifique o formato.');
      }
    };
    reader.readAsText(file);
  };

  const exportToCSV = () => {
    if (appState.requests.length === 0) return;

    const headers = ['ID', 'Solicitante', 'Produto', 'Codigo', 'Quantidade', 'Unidade', 'Tipo', 'Data', 'Status'];
    const rows = appState.requests.map(req => [
      req.id,
      req.solicitante,
      req.productName,
      req.productCode,
      req.quantidade,
      req.unidade,
      req.tipo,
      new Date(req.dataSolicitacao).toLocaleString(),
      req.status
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map(row => row.map(val => `"${val}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `solicitacoes_estoque_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const totalRequests = appState.requests.length;
  const pendingRequests = appState.requests.filter(r => r.status === 'Pendente').length;

  return (
    <div className="space-y-8 max-w-6xl mx-auto">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <StatsCard label="Produtos na Base" value={appState.products.length} icon={<Database />} color="bg-blue-600" />
        <StatsCard label="Total Solicitações" value={totalRequests} icon={<FileText />} color="bg-purple-600" />
        <StatsCard label="Pendentes" value={pendingRequests} icon={<ListChecks />} color="bg-amber-600" />
        <StatsCard label="Usuários Ativos" value={new Set(appState.requests.map(r => r.solicitante)).size} icon={<Users />} color="bg-emerald-600" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1 space-y-6">
          <div className="bg-white dark:bg-slate-900 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800">
            <h3 className="text-lg font-bold mb-4 flex items-center gap-2 dark:text-white">
              <Upload className="w-5 h-5 text-blue-600 dark:text-blue-400" />
              Atualizar Base de Dados
            </h3>
            <p className="text-sm text-gray-500 dark:text-slate-400 mb-6">
              Faça o upload da planilha diária (CSV) para atualizar os níveis de estoque globais.
            </p>

            <label 
              className={`border-2 border-dashed rounded-xl p-8 flex flex-col items-center justify-center transition-all cursor-pointer ${
                dragActive ? 'border-blue-500 bg-blue-50 dark:bg-blue-900/10' : 'border-gray-200 dark:border-slate-700 hover:border-blue-400 dark:hover:border-blue-500'
              }`}
              onDragOver={(e) => { e.preventDefault(); setDragActive(true); }}
              onDragLeave={() => setDragActive(false)}
              onDrop={(e) => { e.preventDefault(); setDragActive(false); handleFileUpload(e); }}
            >
              <Upload className="w-10 h-10 text-gray-300 dark:text-slate-600 mb-3" />
              <p className="text-sm font-medium text-gray-600 dark:text-slate-300 text-center">Arraste a planilha ou clique aqui</p>
              <p className="text-xs text-gray-400 dark:text-slate-500 mt-1">Formato suportado: CSV</p>
              <input type="file" className="hidden" accept=".csv" onChange={handleFileUpload} />
            </label>

            {uploadStatus && (
              <div className={`mt-4 p-3 rounded-lg text-sm text-center font-medium ${
                uploadStatus.includes('Erro') ? 'bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400' : 'bg-green-50 dark:bg-green-900/20 text-green-600 dark:text-green-400'
              }`}>
                {uploadStatus}
              </div>
            )}
          </div>

          <div className="bg-white dark:bg-slate-900 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800">
            <h3 className="text-lg font-bold mb-4 flex items-center gap-2 text-red-600 dark:text-red-400">
              <Trash2 className="w-5 h-5" />
              Limpeza de Dados
            </h3>
            <button 
              onClick={onClearRequests}
              className="w-full py-2 border border-red-200 dark:border-red-900/50 text-red-600 dark:text-red-400 rounded-lg hover:bg-red-50 dark:hover:bg-red-900/10 transition-colors text-sm font-semibold"
            >
              Zerar Histórico de Solicitações
            </button>
          </div>
        </div>

        <div className="lg:col-span-2">
          <div className="bg-white dark:bg-slate-900 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800 overflow-hidden transition-colors">
            <div className="p-6 border-b border-gray-50 dark:border-slate-800 flex justify-between items-center">
              <h3 className="text-lg font-bold flex items-center gap-2 dark:text-white">
                <ListChecks className="w-5 h-5 text-blue-600 dark:text-blue-400" />
                Solicitações
              </h3>
              <div className="flex items-center gap-3">
                <button
                  onClick={exportToCSV}
                  disabled={appState.requests.length === 0}
                  className="flex items-center gap-2 px-3 py-1.5 text-xs font-bold bg-gray-100 dark:bg-slate-800 hover:bg-gray-200 dark:hover:bg-slate-700 text-gray-700 dark:text-slate-300 rounded-lg transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  <Download className="w-4 h-4" />
                  Exportar CSV
                </button>
                <span className="text-xs font-medium bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 px-2.5 py-1 rounded-full uppercase">
                  {appState.requests.length} total
                </span>
              </div>
            </div>

            <div className="overflow-x-auto">
              {appState.requests.length === 0 ? (
                <div className="p-12 text-center text-gray-400 dark:text-slate-600">
                  <FileText className="w-12 h-12 mx-auto mb-3 opacity-20" />
                  <p>Nenhuma solicitação encontrada.</p>
                </div>
              ) : (
                <table className="w-full">
                  <thead className="bg-gray-50 dark:bg-slate-800/50">
                    <tr>
                      <th className="px-6 py-4 text-left text-xs font-bold text-gray-500 dark:text-slate-400 uppercase tracking-wider">Solicitante</th>
                      <th className="px-6 py-4 text-left text-xs font-bold text-gray-500 dark:text-slate-400 uppercase tracking-wider">Produto</th>
                      <th className="px-6 py-4 text-left text-xs font-bold text-gray-500 dark:text-slate-400 uppercase tracking-wider text-center">Quant.</th>
                      <th className="px-6 py-4 text-left text-xs font-bold text-gray-500 dark:text-slate-400 uppercase tracking-wider text-center">Tipo</th>
                      <th className="px-6 py-4 text-right text-xs font-bold text-gray-500 dark:text-slate-400 uppercase tracking-wider">Ações</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100 dark:divide-slate-800">
                    {appState.requests.map(req => (
                      <tr key={req.id} className="hover:bg-gray-50 dark:hover:bg-slate-800/40 transition-colors">
                        <td className="px-6 py-4 whitespace-nowrap">
                          <div className="flex items-center gap-3">
                            <div className="w-8 h-8 rounded-full bg-blue-100 dark:bg-blue-900 flex items-center justify-center text-blue-600 dark:text-blue-400 font-bold text-xs">
                              {req.solicitante.charAt(0).toUpperCase()}
                            </div>
                            <div>
                              <p className="text-sm font-semibold text-gray-900 dark:text-slate-200">{req.solicitante}</p>
                              <p className="text-xs text-gray-400 dark:text-slate-500">{new Date(req.dataSolicitacao).toLocaleDateString()}</p>
                            </div>
                          </div>
                        </td>
                        <td className="px-6 py-4">
                          <p className="text-sm text-gray-900 dark:text-slate-200 font-medium line-clamp-1">{req.productName}</p>
                          <p className="text-xs text-gray-400 dark:text-slate-500">{req.productCode}</p>
                        </td>
                        <td className="px-6 py-4 text-center">
                          <div className="flex flex-col items-center">
                            <span className="text-sm font-bold text-gray-900 dark:text-slate-200">{req.quantidade}</span>
                            <span className="text-[10px] text-gray-400 dark:text-slate-500 uppercase">{req.unidade}</span>
                          </div>
                        </td>
                        <td className="px-6 py-4 text-center">
                          <span className={`text-[10px] font-bold px-2 py-1 rounded-full uppercase ${
                            req.tipo === 'Teste' ? 'bg-purple-50 dark:bg-purple-900/20 text-purple-600 dark:text-purple-400' : 'bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400'
                          }`}>
                            {req.tipo}
                          </span>
                        </td>
                        <td className="px-6 py-4 text-right">
                          {req.status === 'Pendente' ? (
                            <div className="flex justify-end gap-2">
                              <button 
                                onClick={() => onUpdateRequestStatus(req.id, 'Aprovado')}
                                className="p-2 text-green-600 dark:text-green-400 hover:bg-green-50 dark:hover:bg-green-900/20 rounded-lg transition-colors"
                                title="Aprovar"
                              >
                                <CheckCircle className="w-5 h-5" />
                              </button>
                              <button 
                                onClick={() => onUpdateRequestStatus(req.id, 'Recusado')}
                                className="p-2 text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
                                title="Recusar"
                              >
                                <XCircle className="w-5 h-5" />
                              </button>
                            </div>
                          ) : (
                            <span className={`text-xs font-bold ${
                              req.status === 'Aprovado' ? 'text-green-600 dark:text-green-400' : 'text-red-600 dark:text-red-400'
                            }`}>
                              {req.status}
                            </span>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export interface Product {
  id: string;
  fornecedor: string;
  codigo: string;
  situacao: string;
  comprador: string;
  produto: string;
  sabor: string;
  embalagem: string;
  estoqueMarsil: number;
  estoqueBoraceia: number;
}

export type RequestType = 'Teste' | 'Venda Garantida';
export type UnitType = 'Caixa' | 'Unidade';

export interface StockRequest {
  id: string;
  productId: string;
  productName: string;
  productCode: string;
  quantidade: number;
  unidade: UnitType;
  tipo: RequestType;
  solicitante: string;
  dataSolicitacao: string; // ISO format
  status: 'Pendente' | 'Aprovado' | 'Recusado';
}

export interface AppState {
  products: Product[];
  requests: StockRequest[];
  vendedores: string[];
}

import React, { useState, useEffect } from 'react';
import { UserPortal } from './components/UserPortal';
import { AdminPortal } from './components/AdminPortal';
import { AppState, Product, StockRequest } from './types';
import { LayoutDashboard, Users, ShieldCheck, Sun, Moon, Lock, KeyRound, ArrowRight } from 'lucide-react';

const STORAGE_KEY = 'marsil_boraceia_db_v1';
const THEME_KEY = 'marsil_theme_pref';
const USER_PASSWORD = '@marsil2026';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'user' | 'admin'>('user');
  const [isUserAuthenticated, setIsUserAuthenticated] = useState(false);
  const [passwordInput, setPasswordInput] = useState('');
  const [loginError, setLoginError] = useState(false);

  const [isDarkMode, setIsDarkMode] = useState(() => {
    const savedTheme = localStorage.getItem(THEME_KEY);
    return savedTheme === 'dark';
  });

  const [appState, setAppState] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    const parsed = saved ? JSON.parse(saved) : { products: [], requests: [], vendedores: [] };
    // Migration: ensure vendedores exists
    if (!parsed.vendedores) parsed.vendedores = [];
    return parsed;
  });

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(appState));
  }, [appState]);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem(THEME_KEY, 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem(THEME_KEY, 'light');
    }
  }, [isDarkMode]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordInput === USER_PASSWORD) {
      setIsUserAuthenticated(true);
      setLoginError(false);
    } else {
      setLoginError(true);
      setTimeout(() => setLoginError(false), 3000);
    }
  };

  const handleUploadData = (newProducts: Product[]) => {
    setAppState(prev => ({ ...prev, products: newProducts }));
  };

  const handleAddVendedor = (name: string) => {
    if (!appState.vendedores.includes(name)) {
      setAppState(prev => ({ ...prev, vendedores: [...prev.vendedores, name].sort() }));
    }
  };

  const handleRemoveVendedor = (name: string) => {
    setAppState(prev => ({ ...prev, vendedores: prev.vendedores.filter(v => v !== name) }));
  };

  const handleSubmitRequest = (req: Omit<StockRequest, 'id' | 'dataSolicitacao' | 'status'>) => {
    const newRequest: StockRequest = {
      ...req,
      id: `req-${Date.now()}`,
      dataSolicitacao: new Date().toISOString(),
      status: 'Pendente'
    };
    setAppState(prev => ({
      ...prev,
      requests: [newRequest, ...prev.requests]
    }));
  };

  const handleUpdateRequestStatus = (requestId: string, status: StockRequest['status']) => {
    setAppState(prev => ({
      ...prev,
      requests: prev.requests.map(r => r.id === requestId ? { ...r, status } : r)
    }));
  };

  const handleClearRequests = () => {
    if (window.confirm('Deseja realmente apagar todo o histórico de solicitações?')) {
      setAppState(prev => ({ ...prev, requests: [] }));
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-slate-950 text-gray-900 dark:text-slate-100 transition-colors duration-300">
      {/* Header */}
      <header className="bg-white dark:bg-slate-900 border-b border-gray-200 dark:border-slate-800 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-3">
              <div className="bg-blue-600 p-2 rounded-lg">
                <LayoutDashboard className="w-6 h-6 text-white" />
              </div>
              <div className="hidden sm:block">
                <h1 className="text-xl font-bold bg-gradient-to-r from-blue-700 to-blue-500 bg-clip-text text-transparent">
                  Marsil & Boracéia
                </h1>
                <p className="text-[10px] text-gray-400 dark:text-slate-500 font-bold tracking-widest uppercase">
                  Gestão de Estoque
                </p>
              </div>
            </div>

            <div className="flex items-center gap-4">
              <button
                onClick={() => setIsDarkMode(!isDarkMode)}
                className="p-2 rounded-lg bg-gray-100 dark:bg-slate-800 text-gray-600 dark:text-slate-400 hover:text-blue-600 dark:hover:text-blue-400 transition-colors"
                title="Alternar Tema"
              >
                {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
              </button>

              <nav className="flex space-x-1 bg-gray-100 dark:bg-slate-800 p-1 rounded-xl">
                <button
                  onClick={() => setActiveTab('user')}
                  className={`flex items-center gap-2 px-4 py-2 text-sm font-semibold rounded-lg transition-all ${
                    activeTab === 'user' 
                      ? 'bg-white dark:bg-slate-700 text-blue-600 dark:text-blue-400 shadow-sm' 
                      : 'text-gray-500 dark:text-slate-400 hover:text-gray-700 dark:hover:text-slate-200'
                  }`}
                >
                  <Users className="w-4 h-4" />
                  Vendedor
                </button>
                <button
                  onClick={() => setActiveTab('admin')}
                  className={`flex items-center gap-2 px-4 py-2 text-sm font-semibold rounded-lg transition-all ${
                    activeTab === 'admin' 
                      ? 'bg-white dark:bg-slate-700 text-blue-600 dark:text-blue-400 shadow-sm' 
                      : 'text-gray-500 dark:text-slate-400 hover:text-gray-700 dark:hover:text-slate-200'
                  }`}
                >
                  <ShieldCheck className="w-4 h-4" />
                  Admin
                </button>
              </nav>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-grow p-4 sm:p-6 lg:p-8 flex flex-col items-center">
        {activeTab === 'user' ? (
          !isUserAuthenticated ? (
            <div className="w-full max-w-md mt-12 animate-in fade-in slide-in-from-bottom-8 duration-500">
              <div className="bg-white dark:bg-slate-900 p-8 rounded-3xl shadow-xl border border-gray-100 dark:border-slate-800 text-center">
                <div className="w-16 h-16 bg-blue-100 dark:bg-blue-900/30 rounded-full flex items-center justify-center mx-auto mb-6">
                  <Lock className="w-8 h-8 text-blue-600 dark:text-blue-400" />
                </div>
                <h2 className="text-2xl font-bold dark:text-white mb-2">Acesso Restrito</h2>
                <p className="text-gray-500 dark:text-slate-400 mb-8 text-sm">
                  Digite a senha de acesso para entrar no Portal do Vendedor.
                </p>

                <form onSubmit={handleLogin} className="space-y-4">
                  <div className="relative">
                    <KeyRound className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                    <input
                      type="password"
                      placeholder="Senha de acesso"
                      value={passwordInput}
                      onChange={(e) => setPasswordInput(e.target.value)}
                      className={`w-full pl-12 pr-4 py-3 rounded-xl border ${
                        loginError ? 'border-red-500 ring-red-100' : 'border-gray-200 dark:border-slate-700'
                      } bg-white dark:bg-slate-800 focus:ring-4 focus:ring-blue-100 dark:focus:ring-blue-900/20 outline-none transition-all dark:text-white`}
                    />
                  </div>
                  {loginError && (
                    <p className="text-red-500 text-xs font-semibold animate-pulse">Senha incorreta. Tente novamente.</p>
                  )}
                  <button
                    type="submit"
                    className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 rounded-xl transition-all flex items-center justify-center gap-2 group shadow-lg shadow-blue-200 dark:shadow-none"
                  >
                    Entrar no Sistema
                    <ArrowRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
                  </button>
                </form>
              </div>
            </div>
          ) : (
            <UserPortal 
              products={appState.products} 
              requests={appState.requests}
              vendedores={appState.vendedores}
              onSubmitRequest={handleSubmitRequest}
            />
          )
        ) : (
          <AdminPortal 
            appState={appState}
            onUploadData={handleUploadData}
            onAddVendedor={handleAddVendedor}
            onRemoveVendedor={handleRemoveVendedor}
            onUpdateRequestStatus={handleUpdateRequestStatus}
            onClearRequests={handleClearRequests}
          />
        )}
      </main>

      {/* Footer */}
      <footer className="bg-white dark:bg-slate-900 border-t border-gray-100 dark:border-slate-800 py-6">
        <div className="max-w-7xl mx-auto px-4 flex flex-col md:flex-row justify-between items-center gap-4 text-gray-400 dark:text-slate-500 text-sm">
          <p>© 2024 Marsil Logística. Todos os direitos reservados.</p>
          <div className="flex items-center gap-4">
            <span className="flex items-center gap-1">
              <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
              Sistema Operacional
            </span>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Upload, ListChecks, Database, FileText, CheckCircle, XCircle, Trash2, Users, Download, UserPlus, X } from 'lucide-react';
import { Product, StockRequest, AppState } from '../types';
import { StatsCard } from './StatsCard';

interface AdminPortalProps {
  appState: AppState;
  onUploadData: (newProducts: Product[]) => void;
  onAddVendedor: (name: string) => void;
  onRemoveVendedor: (name: string) => void;
  onUpdateRequestStatus: (requestId: string, status: StockRequest['status']) => void;
  onClearRequests: () => void;
}

export const AdminPortal: React.FC<AdminPortalProps> = ({ 
  appState, 
  onUploadData, 
  onAddVendedor,
  onRemoveVendedor,
  onUpdateRequestStatus,
  onClearRequests
}) => {
  const [dragActive, setDragActive] = useState(false);
  const [uploadStatus, setUploadStatus] = useState<string | null>(null);
  const [newVendedor, setNewVendedor] = useState('');

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement> | React.DragEvent) => {
    let file: File | null = null;
    if ('files' in e.target && e.target.files) {
      file = e.target.files[0];
    } else if ('dataTransfer' in e && e.dataTransfer.files) {
      file = e.dataTransfer.files[0];
    }

    if (!file) return;

    setUploadStatus('Lendo arquivo...');
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target?.result as string;
        const rows = text.split('\n').filter(r => r.trim() !== '');
        const dataRows = rows.slice(1);

        const parsedProducts: Product[] = dataRows.map((row, index) => {
          const cols = row.split(/,|;/);
          return {
            id: `p-${index}`,
            fornecedor: cols[0]?.trim() || 'N/A',
            codigo: cols[2]?.trim() || '0',
            situacao: cols[3]?.trim() || '',
            comprador: cols[4]?.trim() || '',
            produto: cols[5]?.trim() || '',
            sabor: cols[6]?.trim() || '',
            embalagem: cols[7]?.trim() || '',
            estoqueMarsil: parseInt(cols[8]) || 0,
            estoqueBoraceia: parseInt(cols[9]) || 0,
          };
        });

        onUploadData(parsedProducts);
        setUploadStatus(`Sucesso! ${parsedProducts.length} itens carregados.`);
        setTimeout(() => setUploadStatus(null), 3000);
      } catch (err) {
        setUploadStatus('Erro ao processar arquivo. Verifique o formato.');
      }
    };
    reader.readAsText(file);
  };

  const handleAddVendedor = (e: React.FormEvent) => {
    e.preventDefault();
    if (newVendedor.trim()) {
      onAddVendedor(newVendedor.trim());
      setNewVendedor('');
    }
  };

  const exportToCSV = () => {
    if (appState.requests.length === 0) return;

    const headers = ['ID', 'Solicitante', 'Produto', 'Codigo', 'Quantidade', 'Unidade', 'Tipo', 'Data', 'Status'];
    const rows = appState.requests.map(req => [
      req.id,
      req.solicitante,
      req.productName,
      req.productCode,
      req.quantidade,
      req.unidade,
      req.tipo,
      new Date(req.dataSolicitacao).toLocaleString(),
      req.status
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map(row => row.map(val => `"${val}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `solicitacoes_estoque_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const totalRequests = appState.requests.length;
  const pendingRequests = appState.requests.filter(r => r.status === 'Pendente').length;

  return (
    <div className="space-y-8 max-w-6xl mx-auto">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <StatsCard label="Produtos na Base" value={appState.products.length} icon={<Database />} color="bg-blue-600" />
        <StatsCard label="Total Solicitações" value={totalRequests} icon={<FileText />} color="bg-purple-600" />
        <StatsCard label="Pendentes" value={pendingRequests} icon={<ListChecks />} color="bg-amber-600" />
        <StatsCard label="Vendedores" value={appState.vendedores.length} icon={<Users />} color="bg-emerald-600" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1 space-y-6">
          {/* Vendedores Section */}
          <div className="bg-white dark:bg-slate-900 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800">
            <h3 className="text-lg font-bold mb-4 flex items-center gap-2 dark:text-white">
              <Users className="w-5 h-5 text-emerald-600 dark:text-emerald-400" />
              Cadastro de Vendedores
            </h3>
            <form onSubmit={handleAddVendedor} className="mb-6 flex gap-2">
              <input
                type="text"
                placeholder="Nome do vendedor"
                value={newVendedor}
                onChange={(e) => setNewVendedor(e.target.value)}
                className="flex-grow px-3 py-2 rounded-lg border border-gray-200 dark:border-slate-700 bg-white dark:bg-slate-800 focus:ring-2 focus:ring-emerald-500 outline-none dark:text-white text-sm"
              />
              <button
                type="submit"
                className="p-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 transition-colors"
              >
                <UserPlus className="w-5 h-5" />
              </button>
            </form>
            <div className="space-y-2 max-h-48 overflow-y-auto pr-2 custom-scrollbar">
              {appState.vendedores.length === 0 ? (
                <p className="text-xs text-gray-400 italic">Nenhum vendedor cadastrado.</p>
              ) : (
                appState.vendedores.map(v => (
                  <div key={v} className="flex items-center justify-between p-2 rounded-lg bg-gray-50 dark:bg-slate-800/50 group">
                    <span className="text-sm dark:text-slate-200">{v}</span>
                    <button
                      onClick={() => onRemoveVendedor(v)}
                      className="text-gray-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"
                    >
                      <X className="w-4 h-4" />
                    </button>
                  </div>
                ))
              )}
            </div>
          </div>

          <div className="bg-white dark:bg-slate-900 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800">
            <h3 className="text-lg font-bold mb-4 flex items-center gap-2 dark:text-white">
              <Upload className="w-5 h-5 text-blue-600 dark:text-blue-400" />
              Atualizar Base de Dados
            </h3>
            <p className="text-sm text-gray-500 dark:text-slate-400 mb-6">
              Faça o upload da planilha diária (CSV) para atualizar os níveis de estoque globais.
            </p>

            <label 
              className={`border-2 border-dashed rounded-xl p-8 flex flex-col items-center justify-center transition-all cursor-pointer ${
                dragActive ? 'border-blue-500 bg-blue-50 dark:bg-blue-900/10' : 'border-gray-200 dark:border-slate-700 hover:border-blue-400 dark:hover:border-blue-500'
              }`}
              onDragOver={(e) => { e.preventDefault(); setDragActive(true); }}
              onDragLeave={() => setDragActive(false)}
              onDrop={(e) => { e.preventDefault(); setDragActive(false); handleFileUpload(e); }}
            >
              <Upload className="w-10 h-10 text-gray-300 dark:text-slate-600 mb-3" />
              <p className="text-sm font-medium text-gray-600 dark:text-slate-300 text-center">Arraste a planilha ou clique aqui</p>
              <p className="text-xs text-gray-400 dark:text-slate-500 mt-1">Formato suportado: CSV</p>
              <input type="file" className="hidden" accept=".csv" onChange={handleFileUpload} />
            </label>

            {uploadStatus && (
              <div className={`mt-4 p-3 rounded-lg text-sm text-center font-medium ${
                uploadStatus.includes('Erro') ? 'bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400' : 'bg-green-50 dark:bg-green-900/20 text-green-600 dark:text-green-400'
              }`}>
                {uploadStatus}
              </div>
            )}
          </div>

          <div className="bg-white dark:bg-slate-900 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800">
            <h3 className="text-lg font-bold mb-4 flex items-center gap-2 text-red-600 dark:text-red-400">
              <Trash2 className="w-5 h-5" />
              Limpeza de Dados
            </h3>
            <button 
              onClick={onClearRequests}
              className="w-full py-2 border border-red-200 dark:border-red-900/50 text-red-600 dark:text-red-400 rounded-lg hover:bg-red-50 dark:hover:bg-red-900/10 transition-colors text-sm font-semibold"
            >
              Zerar Histórico de Solicitações
            </button>
          </div>
        </div>

        <div className="lg:col-span-2">
          <div className="bg-white dark:bg-slate-900 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800 overflow-hidden transition-colors">
            <div className="p-6 border-b border-gray-50 dark:border-slate-800 flex justify-between items-center">
              <h3 className="text-lg font-bold flex items-center gap-2 dark:text-white">
                <ListChecks className="w-5 h-5 text-blue-600 dark:text-blue-400" />
                Solicitações
              </h3>
              <div className="flex items-center gap-3">
                <button
                  onClick={exportToCSV}
                  disabled={appState.requests.length === 0}
                  className="flex items-center gap-2 px-3 py-1.5 text-xs font-bold bg-gray-100 dark:bg-slate-800 hover:bg-gray-200 dark:hover:bg-slate-700 text-gray-700 dark:text-slate-300 rounded-lg transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  <Download className="w-4 h-4" />
                  Exportar CSV
                </button>
                <span className="text-xs font-medium bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 px-2.5 py-1 rounded-full uppercase">
                  {appState.requests.length} total
                </span>
              </div>
            </div>

            <div className="overflow-x-auto">
              {appState.requests.length === 0 ? (
                <div className="p-12 text-center text-gray-400 dark:text-slate-600">
                  <FileText className="w-12 h-12 mx-auto mb-3 opacity-20" />
                  <p>Nenhuma solicitação encontrada.</p>
                </div>
              ) : (
                <table className="w-full">
                  <thead className="bg-gray-50 dark:bg-slate-800/50">
                    <tr>
                      <th className="px-6 py-4 text-left text-xs font-bold text-gray-500 dark:text-slate-400 uppercase tracking-wider">Solicitante</th>
                      <th className="px-6 py-4 text-left text-xs font-bold text-gray-500 dark:text-slate-400 uppercase tracking-wider">Produto</th>
                      <th className="px-6 py-4 text-left text-xs font-bold text-gray-500 dark:text-slate-400 uppercase tracking-wider text-center">Quant.</th>
                      <th className="px-6 py-4 text-left text-xs font-bold text-gray-500 dark:text-slate-400 uppercase tracking-wider text-center">Tipo</th>
                      <th className="px-6 py-4 text-right text-xs font-bold text-gray-500 dark:text-slate-400 uppercase tracking-wider">Ações</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100 dark:divide-slate-800">
                    {appState.requests.map(req => (
                      <tr key={req.id} className="hover:bg-gray-50 dark:hover:bg-slate-800/40 transition-colors">
                        <td className="px-6 py-4 whitespace-nowrap">
                          <div className="flex items-center gap-3">
                            <div className="w-8 h-8 rounded-full bg-blue-100 dark:bg-blue-900 flex items-center justify-center text-blue-600 dark:text-blue-400 font-bold text-xs">
                              {req.solicitante.charAt(0).toUpperCase()}
                            </div>
                            <div>
                              <p className="text-sm font-semibold text-gray-900 dark:text-slate-200">{req.solicitante}</p>
                              <p className="text-xs text-gray-400 dark:text-slate-500">{new Date(req.dataSolicitacao).toLocaleDateString()}</p>
                            </div>
                          </div>
                        </td>
                        <td className="px-6 py-4">
                          <p className="text-sm text-gray-900 dark:text-slate-200 font-medium line-clamp-1">{req.productName}</p>
                          <p className="text-xs text-gray-400 dark:text-slate-500">{req.productCode}</p>
                        </td>
                        <td className="px-6 py-4 text-center">
                          <div className="flex flex-col items-center">
                            <span className="text-sm font-bold text-gray-900 dark:text-slate-200">{req.quantidade}</span>
                            <span className="text-[10px] text-gray-400 dark:text-slate-500 uppercase">{req.unidade}</span>
                          </div>
                        </td>
                        <td className="px-6 py-4 text-center">
                          <span className={`text-[10px] font-bold px-2 py-1 rounded-full uppercase ${
                            req.tipo === 'Teste' ? 'bg-purple-50 dark:bg-purple-900/20 text-purple-600 dark:text-purple-400' : 'bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400'
                          }`}>
                            {req.tipo}
                          </span>
                        </td>
                        <td className="px-6 py-4 text-right">
                          {req.status === 'Pendente' ? (
                            <div className="flex justify-end gap-2">
                              <button 
                                onClick={() => onUpdateRequestStatus(req.id, 'Aprovado')}
                                className="p-2 text-green-600 dark:text-green-400 hover:bg-green-50 dark:hover:bg-green-900/20 rounded-lg transition-colors"
                                title="Aprovar"
                              >
                                <CheckCircle className="w-5 h-5" />
                              </button>
                              <button 
                                onClick={() => onUpdateRequestStatus(req.id, 'Recusado')}
                                className="p-2 text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
                                title="Recusar"
                              >
                                <XCircle className="w-5 h-5" />
                              </button>
                            </div>
                          ) : (
                            <span className={`text-xs font-bold ${
                              req.status === 'Aprovado' ? 'text-green-600 dark:text-green-400' : 'text-red-600 dark:text-red-400'
                            }`}>
                              {req.status}
                            </span>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Search, Send, AlertCircle, CheckCircle2, UserCircle, Package, Truck, Filter, ChevronLeft, ChevronRight, Layers } from 'lucide-react';
import { Product, StockRequest, RequestType, UnitType } from '../types';
import { calculateDiffPercent, isWithinLast7Days, formatCurrency } from '../utils';

interface UserPortalProps {
  products: Product[];
  requests: StockRequest[];
  vendedores: string[];
  onSubmitRequest: (req: Omit<StockRequest, 'id' | 'dataSolicitacao' | 'status'>) => void;
}

const ITEMS_PER_PAGE = 10;

export const UserPortal: React.FC<UserPortalProps> = ({ products, requests, vendedores, onSubmitRequest }) => {
  const [filterCodigo, setFilterCodigo] = useState('');
  const [filterFornecedor, setFilterFornecedor] = useState('');
  const [filterDescricao, setFilterDescricao] = useState('');
  const [currentPage, setCurrentPage] = useState(1);

  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [formData, setFormData] = useState({
    quantidade: 0,
    unidade: 'Unidade' as UnitType,
    tipo: 'Teste' as RequestType,
    solicitante: ''
  });
  const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  const hasSearch = useMemo(() => {
    return filterCodigo.length >= 2 || filterFornecedor.length >= 3 || filterDescricao.length >= 3;
  }, [filterCodigo, filterFornecedor, filterDescricao]);

  const filteredProducts = useMemo(() => {
    if (!hasSearch) return [];

    return products.filter(p => {
      const matchCodigo = filterCodigo === '' || p.codigo.toLowerCase().includes(filterCodigo.toLowerCase());
      const matchFornecedor = filterFornecedor === '' || p.fornecedor.toLowerCase().includes(filterFornecedor.toLowerCase());
      const matchDescricao = filterDescricao === '' || p.produto.toLowerCase().includes(filterDescricao.toLowerCase());

      return matchCodigo && matchFornecedor && matchDescricao;
    });
  }, [products, filterCodigo, filterFornecedor, filterDescricao, hasSearch]);

  // Reset pagination when search changes
  useEffect(() => {
    setCurrentPage(1);
  }, [filterCodigo, filterFornecedor, filterDescricao]);

  const totalPages = Math.ceil(filteredProducts.length / ITEMS_PER_PAGE);
  const currentItems = useMemo(() => {
    const start = (currentPage - 1) * ITEMS_PER_PAGE;
    return filteredProducts.slice(start, start + ITEMS_PER_PAGE);
  }, [filteredProducts, currentPage]);

  const recentRequest = useMemo(() => {
    if (!selectedProduct) return null;
    return requests.find(r => r.productId === selectedProduct.id && isWithinLast7Days(r.dataSolicitacao));
  }, [selectedProduct, requests]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedProduct || !formData.solicitante || formData.quantidade <= 0) {
      setMessage({ type: 'error', text: 'Preencha todos os campos corretamente.' });
      return;
    }

    const fullProductName = selectedProduct.sabor 
      ? `${selectedProduct.produto} - ${selectedProduct.sabor}`
      : selectedProduct.produto;

    onSubmitRequest({
      productId: selectedProduct.id,
      productName: fullProductName,
      productCode: selectedProduct.codigo,
      quantidade: formData.quantidade,
      unidade: formData.unidade,
      tipo: formData.tipo,
      solicitante: formData.solicitante
    });

    setMessage({ type: 'success', text: 'Solicitação enviada com sucesso!' });
    setFormData({ ...formData, quantidade: 0, unidade: 'Unidade', tipo: 'Teste' });
    setSelectedProduct(null);
    setFilterCodigo('');
    setFilterFornecedor('');
    setFilterDescricao('');

    setTimeout(() => setMessage(null), 3000);
  };

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      <div className="bg-white dark:bg-slate-900 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800 transition-colors">
        <h2 className="text-xl font-bold mb-6 flex items-center gap-2 dark:text-white">
          <Filter className="w-5 h-5 text-blue-600 dark:text-blue-400" />
          Filtros de Consulta
        </h2>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
          <div className="space-y-1">
            <label className="text-xs font-bold text-gray-500 dark:text-slate-400 uppercase ml-1">Cód. Item</label>
            <div className="relative">
              <input
                type="text"
                placeholder="Ex: 1234..."
                className="w-full pl-10 pr-4 py-2.5 rounded-xl border border-gray-200 dark:border-slate-700 bg-white dark:bg-slate-800 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all text-sm dark:text-white"
                value={filterCodigo}
                onChange={(e) => setFilterCodigo(e.target.value)}
              />
              <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400 dark:text-slate-500 w-4 h-4" />
            </div>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold text-gray-500 dark:text-slate-400 uppercase ml-1">Fornecedor</label>
            <div className="relative">
              <input
                type="text"
                placeholder="Buscar fornecedor..."
                className="w-full pl-10 pr-4 py-2.5 rounded-xl border border-gray-200 dark:border-slate-700 bg-white dark:bg-slate-800 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all text-sm dark:text-white"
                value={filterFornecedor}
                onChange={(e) => setFilterFornecedor(e.target.value)}
              />
              <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400 dark:text-slate-500 w-4 h-4" />
            </div>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold text-gray-500 dark:text-slate-400 uppercase ml-1">Descrição / Produto</label>
            <div className="relative">
              <input
                type="text"
                placeholder="Buscar produto..."
                className="w-full pl-10 pr-4 py-2.5 rounded-xl border border-gray-200 dark:border-slate-700 bg-white dark:bg-slate-800 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all text-sm dark:text-white"
                value={filterDescricao}
                onChange={(e) => setFilterDescricao(e.target.value)}
              />
              <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400 dark:text-slate-500 w-4 h-4" />
            </div>
          </div>
        </div>

        {!hasSearch && (
          <p className="mt-2 text-sm text-gray-500 dark:text-slate-400 italic flex items-center gap-2">
            <AlertCircle className="w-4 h-4" />
            Preencha um dos filtros para visualizar os produtos.
          </p>
        )}

        {hasSearch && filteredProducts.length === 0 && (
          <p className="mt-2 text-sm text-amber-600 dark:text-amber-400 font-medium">Nenhum produto encontrado com esses filtros.</p>
        )}

        {hasSearch && filteredProducts.length > 0 && !selectedProduct && (
          <div className="mt-6 space-y-4">
            <div className="border border-gray-100 dark:border-slate-800 rounded-xl overflow-hidden divide-y divide-gray-100 dark:divide-slate-800 shadow-sm">
              <div className="bg-gray-50 dark:bg-slate-800/50 px-4 py-2 text-[10px] font-bold text-gray-400 dark:text-slate-500 uppercase grid grid-cols-12 gap-2">
                <div className="col-span-6 md:col-span-7">Produto / Sabor / Embalagem</div>
                <div className="col-span-3 md:col-span-2 text-center">Código</div>
                <div className="col-span-3 text-right">Estoque Marsil</div>
              </div>
              {currentItems.map(p => (
                <button
                  key={p.id}
                  onClick={() => setSelectedProduct(p)}
                  className="w-full text-left p-4 hover:bg-blue-50 dark:hover:bg-slate-800/80 transition-colors grid grid-cols-12 gap-2 items-center group"
                >
                  <div className="col-span-6 md:col-span-7">
                    <p className="font-semibold text-gray-800 dark:text-slate-200 leading-tight">
                      {p.produto}{p.sabor ? ` - ${p.sabor}` : ''}
                    </p>
                    <div className="flex flex-wrap gap-x-3 gap-y-1 mt-1">
                      <span className="text-xs text-blue-600 dark:text-blue-400 font-medium">{p.fornecedor}</span>
                      <span className="text-xs text-gray-400 dark:text-slate-500 border-l border-gray-200 dark:border-slate-700 pl-3">Emb: <span className="font-semibold text-gray-600 dark:text-slate-300">{p.embalagem}</span></span>
                    </div>
                  </div>
                  <div className="col-span-3 md:col-span-2 text-center">
                    <p className="text-xs font-mono font-bold text-gray-500 dark:text-slate-500">{p.codigo}</p>
                  </div>
                  <div className="col-span-3 text-right">
                    <p className="font-bold text-blue-600 dark:text-blue-400">{formatCurrency(p.estoqueMarsil)}</p>
                  </div>
                </button>
              ))}
            </div>

            {/* Pagination Controls */}
            {totalPages > 1 && (
              <div className="flex flex-col sm:flex-row items-center justify-between gap-4 py-2 px-1">
                <p className="text-xs text-gray-500 dark:text-slate-400">
                  Mostrando <span className="font-bold text-gray-700 dark:text-slate-200">{(currentPage - 1) * ITEMS_PER_PAGE + 1}</span> a <span className="font-bold text-gray-700 dark:text-slate-200">{Math.min(currentPage * ITEMS_PER_PAGE, filteredProducts.length)}</span> de <span className="font-bold text-gray-700 dark:text-slate-200">{filteredProducts.length}</span> produtos
                </p>
                <div className="flex items-center gap-1">
                  <button
                    onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                    disabled={currentPage === 1}
                    className="p-2 rounded-lg border border-gray-200 dark:border-slate-700 hover:bg-gray-50 dark:hover:bg-slate-800 disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
                  >
                    <ChevronLeft className="w-4 h-4 dark:text-slate-300" />
                  </button>

                  {/* Page numbers (simplified version) */}
                  <div className="flex items-center gap-1 mx-2">
                    {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                      let pageNum = i + 1;
                      if (totalPages > 5 && currentPage > 3) {
                        pageNum = currentPage - 3 + i + 1;
                        if (pageNum > totalPages) pageNum = totalPages - (4 - i);
                      }
                      if (pageNum <= 0) return null;

                      return (
                        <button
                          key={pageNum}
                          onClick={() => setCurrentPage(pageNum)}
                          className={`w-8 h-8 rounded-lg text-xs font-bold transition-all ${
                            currentPage === pageNum
                              ? 'bg-blue-600 text-white shadow-md shadow-blue-200 dark:shadow-none'
                              : 'text-gray-500 dark:text-slate-400 hover:bg-gray-100 dark:hover:bg-slate-800 border border-transparent'
                          }`}
                        >
                          {pageNum}
                        </button>
                      );
                    })}
                  </div>

                  <button
                    onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                    disabled={currentPage === totalPages}
                    className="p-2 rounded-lg border border-gray-200 dark:border-slate-700 hover:bg-gray-50 dark:hover:bg-slate-800 disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
                  >
                    <ChevronRight className="w-4 h-4 dark:text-slate-300" />
                  </button>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {selectedProduct && (
        <div className="bg-white dark:bg-slate-900 rounded-2xl shadow-lg border border-blue-100 dark:border-slate-800 overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-300">
          <div className="bg-blue-600 dark:bg-blue-700 p-4 text-white flex justify-between items-center">
            <div>
              <h3 className="text-lg font-bold">
                {selectedProduct.produto}{selectedProduct.sabor ? ` - ${selectedProduct.sabor}` : ''}
              </h3>
              <p className="text-sm opacity-90 flex items-center gap-2">
                <span className="font-mono bg-blue-700 dark:bg-blue-800 px-1.5 rounded">{selectedProduct.codigo}</span>
                <span>|</span>
                <span>{selectedProduct.fornecedor}</span>
                <span>|</span>
                <span className="bg-blue-500/30 dark:bg-blue-400/20 px-2 rounded">Embalagem: {selectedProduct.embalagem}</span>
              </p>
            </div>
