              <p className="text-sm text-gray-500 dark:text-slate-400 font-medium mb-1">Estoque Marsil</p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">{formatCurrency(selectedProduct.estoqueMarsil)}</p>
