            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-600 dark:text-slate-400 mb-1">Solicitante</label>
                <div className="relative">
                  <UserCircle className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 dark:text-slate-500 w-4 h-4" />
                  <select
                    required
                    className="w-full pl-9 pr-4 py-2 rounded-lg border border-gray-200 dark:border-slate-700 bg-white dark:bg-slate-800 focus:ring-2 focus:ring-blue-500 outline-none appearance-none dark:text-white"
                    value={formData.solicitante}
                    onChange={(e) => setFormData({...formData, solicitante: e.target.value})}
                  >
                    <option value="" disabled>Selecione seu nome</option>
                    {vendedores.map(v => (
                      <option key={v} value={v}>{v}</option>
                    ))}
                  </select>
                </div>
                {vendedores.length === 0 && (
                  <p className="text-[10px] text-amber-600 dark:text-amber-400 mt-1">Nenhum vendedor cadastrado no sistema.</p>
                )}
