            <UserPortal 
              products={appState.products} 
              requests={appState.requests}
              vendedores={appState.vendedores}
              whatsappConfig={appState.whatsappConfig}
              onSubmitRequest={handleSubmitRequest}
            />
          )
        ) : (
          <AdminPortal 
            appState={appState}
            onUploadData={handleUploadData}
            onAddVendedor={handleAddVendedor}
            onRemoveVendedor={handleRemoveVendedor}
            onUpdateWhatsApp={handleUpdateWhatsApp}
            onUpdateRequestStatus={handleUpdateRequestStatus}
            onClearRequests={handleClearRequests}
          />
        )}
      </main>

      <footer className="bg-white dark:bg-slate-900 border-t border-gray-100 dark:border-slate-800 py-6">
        <div className="max-w-7xl mx-auto px-4 flex justify-between items-center text-gray-400 text-sm">
          <p>© 2024 Marsil Logística.</p>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Upload, ListChecks, Database, FileText, CheckCircle, XCircle, Trash2, Users, Download, UserPlus, X, MessageSquare, Phone } from 'lucide-react';
import { Product, StockRequest, AppState, WhatsAppConfig } from '../types';
import { StatsCard } from './StatsCard';

interface AdminPortalProps {
  appState: AppState;
  onUploadData: (newProducts: Product[]) => void;
  onAddVendedor: (name: string) => void;
  onRemoveVendedor: (name: string) => void;
  onUpdateWhatsApp: (config: WhatsAppConfig) => void;
  onUpdateRequestStatus: (requestId: string, status: StockRequest['status']) => void;
  onClearRequests: () => void;
}

export const AdminPortal: React.FC<AdminPortalProps> = ({ 
  appState, 
  onUploadData, 
  onAddVendedor,
  onRemoveVendedor,
  onUpdateWhatsApp,
  onUpdateRequestStatus,
  onClearRequests
}) => {
  const [dragActive, setDragActive] = useState(false);
  const [uploadStatus, setUploadStatus] = useState<string | null>(null);
  const [newVendedor, setNewVendedor] = useState('');

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement> | React.DragEvent) => {
    let file: File | null = null;
    if ('files' in e.target && e.target.files) {
      file = e.target.files[0];
    } else if ('dataTransfer' in e && e.dataTransfer.files) {
      file = e.dataTransfer.files[0];
    }

    if (!file) return;

    setUploadStatus('Lendo arquivo...');
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target?.result as string;
        const rows = text.split('\n').filter(r => r.trim() !== '');
        const dataRows = rows.slice(1);

        const parsedProducts: Product[] = dataRows.map((row, index) => {
          const cols = row.split(/,|;/);
          return {
            id: `p-${index}`,
            fornecedor: cols[0]?.trim() || 'N/A',
            codigo: cols[2]?.trim() || '0',
            situacao: cols[3]?.trim() || '',
            comprador: cols[4]?.trim() || '',
            produto: cols[5]?.trim() || '',
            sabor: cols[6]?.trim() || '',
            embalagem: cols[7]?.trim() || '',
            estoqueMarsil: parseInt(cols[8]) || 0,
            estoqueBoraceia: parseInt(cols[9]) || 0,
          };
        });

        onUploadData(parsedProducts);
        setUploadStatus(`Sucesso! ${parsedProducts.length} itens.`);
        setTimeout(() => setUploadStatus(null), 3000);
      } catch (err) {
        setUploadStatus('Erro no arquivo.');
      }
    };
    reader.readAsText(file);
  };

  const handleAddVendedor = (e: React.FormEvent) => {
    e.preventDefault();
    if (newVendedor.trim()) {
      onAddVendedor(newVendedor.trim());
      setNewVendedor('');
    }
  };

  const exportToCSV = () => {
    if (appState.requests.length === 0) return;
    const headers = ['ID', 'Solicitante', 'Produto', 'Codigo', 'Quantidade', 'Unidade', 'Tipo', 'Data', 'Status'];
    const rows = appState.requests.map(req => [
      req.id, req.solicitante, req.productName, req.productCode, req.quantidade, req.unidade, req.tipo, new Date(req.dataSolicitacao).toLocaleString(), req.status
    ]);
    const csvContent = [headers.join(','), ...rows.map(row => row.map(val => `"${val}"`).join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `solicitacoes_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  return (
    <div className="space-y-8 max-w-6xl mx-auto">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <StatsCard label="Produtos" value={appState.products.length} icon={<Database />} color="bg-blue-600" />
        <StatsCard label="Solicitações" value={appState.requests.length} icon={<FileText />} color="bg-purple-600" />
        <StatsCard label="Pendentes" value={appState.requests.filter(r => r.status === 'Pendente').length} icon={<ListChecks />} color="bg-amber-600" />
        <StatsCard label="Vendedores" value={appState.vendedores.length} icon={<Users />} color="bg-emerald-600" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1 space-y-6">
          {/* WhatsApp Config */}
          <div className="bg-white dark:bg-slate-900 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800">
            <h3 className="text-lg font-bold mb-4 flex items-center gap-2 dark:text-white">
              <MessageSquare className="w-5 h-5 text-green-600 dark:text-green-400" />
              Notificações WhatsApp
            </h3>
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <span className="text-sm text-gray-600 dark:text-slate-400 font-medium">Ativar Notificações</span>
                <button
                  onClick={() => onUpdateWhatsApp({ ...appState.whatsappConfig, enabled: !appState.whatsappConfig.enabled })}
                  className={`w-12 h-6 rounded-full transition-colors relative ${appState.whatsappConfig.enabled ? 'bg-green-500' : 'bg-gray-300 dark:bg-slate-700'}`}
                >
                  <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-transform ${appState.whatsappConfig.enabled ? 'left-7' : 'left-1'}`} />
                </button>
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-gray-500 uppercase">Número do Admin</label>
                <div className="relative">
                  <Phone className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                  <input
                    type="text"
                    placeholder="Ex: 5511999999999"
                    value={appState.whatsappConfig.phoneNumber}
                    onChange={(e) => onUpdateWhatsApp({ ...appState.whatsappConfig, phoneNumber: e.target.value.replace(/\D/g, '') })}
                    className="w-full pl-9 pr-4 py-2 rounded-lg border border-gray-200 dark:border-slate-700 bg-white dark:bg-slate-800 focus:ring-2 focus:ring-green-500 outline-none text-sm dark:text-white"
                  />
                </div>
                <p className="text-[10px] text-gray-400">Inclua o 55 + DDD + Número (sem espaços ou traços).</p>
              </div>
            </div>
          </div>

          <div className="bg-white dark:bg-slate-900 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800">
            <h3 className="text-lg font-bold mb-4 flex items-center gap-2 dark:text-white">
              <Users className="w-5 h-5 text-emerald-600 dark:text-emerald-400" />
              Cadastro de Vendedores
            </h3>
            <form onSubmit={handleAddVendedor} className="mb-4 flex gap-2">
              <input
                type="text"
                placeholder="Nome..."
