import React, { useState, useMemo, useEffect } from 'react';
import { Search, Send, AlertCircle, CheckCircle2, UserCircle, Package, Truck, Filter, ChevronLeft, ChevronRight, Layers, MessageCircle } from 'lucide-react';
import { Product, StockRequest, RequestType, UnitType, WhatsAppConfig } from '../types';
import { calculateDiffPercent, isWithinLast7Days, formatCurrency } from '../utils';

interface UserPortalProps {
  products: Product[];
  requests: StockRequest[];
  vendedores: string[];
  whatsappConfig: WhatsAppConfig;
  onSubmitRequest: (req: Omit<StockRequest, 'id' | 'dataSolicitacao' | 'status'>) => void;
}

const ITEMS_PER_PAGE = 10;

export const UserPortal: React.FC<UserPortalProps> = ({ products, requests, vendedores, whatsappConfig, onSubmitRequest }) => {
  const [filterCodigo, setFilterCodigo] = useState('');
  const [filterFornecedor, setFilterFornecedor] = useState('');
  const [filterDescricao, setFilterDescricao] = useState('');
  const [currentPage, setCurrentPage] = useState(1);

  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [formData, setFormData] = useState({
    quantidade: 0,
    unidade: 'Unidade' as UnitType,
    tipo: 'Teste' as RequestType,
    solicitante: ''
  });
  const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  const hasSearch = useMemo(() => filterCodigo.length >= 2 || filterFornecedor.length >= 3 || filterDescricao.length >= 3, [filterCodigo, filterFornecedor, filterDescricao]);

  const filteredProducts = useMemo(() => {
    if (!hasSearch) return [];
    return products.filter(p => {
      const matchCodigo = filterCodigo === '' || p.codigo.toLowerCase().includes(filterCodigo.toLowerCase());
      const matchFornecedor = filterFornecedor === '' || p.fornecedor.toLowerCase().includes(filterFornecedor.toLowerCase());
      const matchDescricao = filterDescricao === '' || p.produto.toLowerCase().includes(filterDescricao.toLowerCase());
      return matchCodigo && matchFornecedor && matchDescricao;
    });
  }, [products, filterCodigo, filterFornecedor, filterDescricao, hasSearch]);

  useEffect(() => setCurrentPage(1), [filterCodigo, filterFornecedor, filterDescricao]);

  const currentItems = useMemo(() => filteredProducts.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE), [filteredProducts, currentPage]);

  const sendToWhatsApp = (req: Omit<StockRequest, 'id' | 'dataSolicitacao' | 'status'>) => {
    if (!whatsappConfig.enabled || !whatsappConfig.phoneNumber) return;

    const text = `📦 *NOVA SOLICITAÇÃO DE ESTOQUE*\n\n` +
                 `👤 *Vendedor:* ${req.solicitante}\n` +
                 `🏷️ *Produto:* ${req.productName}\n` +
                 `🔢 *Código:* ${req.productCode}\n` +
                 `📊 *Quantidade:* ${req.quantidade} ${req.unidade.toUpperCase()}(S)\n` +
                 `📝 *Tipo:* ${req.tipo}\n\n` +
                 `📅 *Data:* ${new Date().toLocaleDateString()}`;

    const url = `https://wa.me/${whatsappConfig.phoneNumber}?text=${encodeURIComponent(text)}`;
    window.open(url, '_blank');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedProduct || !formData.solicitante || formData.quantidade <= 0) {
      setMessage({ type: 'error', text: 'Preencha todos os campos.' });
      return;
    }

    const fullProductName = selectedProduct.sabor ? `${selectedProduct.produto} - ${selectedProduct.sabor}` : selectedProduct.produto;
    const requestData = {
      productId: selectedProduct.id,
      productName: fullProductName,
      productCode: selectedProduct.codigo,
      quantidade: formData.quantidade,
      unidade: formData.unidade,
      tipo: formData.tipo,
      solicitante: formData.solicitante
    };

    onSubmitRequest(requestData);

    // Trigger WhatsApp if enabled
    if (whatsappConfig.enabled) {
      sendToWhatsApp(requestData);
    }

    setMessage({ type: 'success', text: 'Solicitação enviada!' });
    setFormData({ ...formData, quantidade: 0, unidade: 'Unidade', tipo: 'Teste' });
    setSelectedProduct(null);
    setTimeout(() => setMessage(null), 3000);
  };

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      <div className="bg-white dark:bg-slate-900 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800">
        <h2 className="text-xl font-bold mb-6 flex items-center gap-2 dark:text-white">
          <Filter className="w-5 h-5 text-blue-600" /> Filtros de Consulta
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <input type="text" placeholder="Cód. Item" className="w-full px-4 py-2.5 rounded-xl border border-gray-200 dark:border-slate-700 bg-white dark:bg-slate-800 dark:text-white text-sm" value={filterCodigo} onChange={(e) => setFilterCodigo(e.target.value)} />
          <input type="text" placeholder="Fornecedor" className="w-full px-4 py-2.5 rounded-xl border border-gray-200 dark:border-slate-700 bg-white dark:bg-slate-800 dark:text-white text-sm" value={filterFornecedor} onChange={(e) => setFilterFornecedor(e.target.value)} />
          <input type="text" placeholder="Produto" className="w-full px-4 py-2.5 rounded-xl border border-gray-200 dark:border-slate-700 bg-white dark:bg-slate-800 dark:text-white text-sm" value={filterDescricao} onChange={(e) => setFilterDescricao(e.target.value)} />
        </div>

        {hasSearch && filteredProducts.length > 0 && !selectedProduct && (
          <div className="mt-6 border border-gray-100 dark:border-slate-800 rounded-xl overflow-hidden divide-y divide-gray-100 dark:divide-slate-800">
            {currentItems.map(p => (
              <button key={p.id} onClick={() => setSelectedProduct(p)} className="w-full text-left p-4 hover:bg-blue-50 dark:hover:bg-slate-800/80 transition-colors flex justify-between items-center">
                <div>
                  <p className="font-semibold dark:text-slate-200">{p.produto}{p.sabor ? ` - ${p.sabor}` : ''}</p>
                  <p className="text-xs text-blue-600">{p.fornecedor} | <span className="text-gray-400 font-mono">{p.codigo}</span></p>
                </div>
                <p className="font-bold text-blue-600">{formatCurrency(p.estoqueMarsil)}</p>
              </button>
            ))}
          </div>
        )}
      </div>

      {selectedProduct && (
        <div className="bg-white dark:bg-slate-900 rounded-2xl shadow-lg border border-blue-100 dark:border-slate-800 overflow-hidden">
          <div className="bg-blue-600 p-4 text-white flex justify-between items-center">
            <h3 className="font-bold">{selectedProduct.produto}</h3>
            <button onClick={() => setSelectedProduct(null)}>✕</button>
          </div>
          <form onSubmit={handleSubmit} className="p-6 space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
              <select required className="w-full px-4 py-2 rounded-lg border dark:border-slate-700 bg-white dark:bg-slate-800 dark:text-white" value={formData.solicitante} onChange={(e) => setFormData({...formData, solicitante: e.target.value})}>
                <option value="" disabled>Seu Nome</option>
                {vendedores.map(v => <option key={v} value={v}>{v}</option>)}
              </select>
              <input type="number" required min="1" className="w-full px-4 py-2 rounded-lg border dark:border-slate-700 bg-white dark:bg-slate-800 dark:text-white" placeholder="Qtd" value={formData.quantidade || ''} onChange={(e) => setFormData({...formData, quantidade: parseInt(e.target.value) || 0})} />
              <select className="w-full px-4 py-2 rounded-lg border dark:border-slate-700 bg-white dark:bg-slate-800 dark:text-white" value={formData.unidade} onChange={(e) => setFormData({...formData, unidade: e.target.value as UnitType})}>
                <option value="Unidade">Unidade</option>
                <option value="Caixa">Caixa</option>
              </select>
              <select className="w-full px-4 py-2 rounded-lg border dark:border-slate-700 bg-white dark:bg-slate-800 dark:text-white" value={formData.tipo} onChange={(e) => setFormData({...formData, tipo: e.target.value as RequestType})}>
                <option value="Teste">Teste</option>
                <option value="Venda Garantida">Venda Garantida</option>
              </select>
            </div>
            <button type="submit" className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 rounded-xl flex items-center justify-center gap-2">
              {whatsappConfig.enabled ? <MessageCircle className="w-5 h-5" /> : <Send className="w-5 h-5" />}
              Enviar {whatsappConfig.enabled ? 'via WhatsApp' : 'Solicitação'}
            </button>
          </form>
        </div>
      )}

      {message && (
        <div className={`fixed bottom-8 left-1/2 -translate-x-1/2 px-6 py-3 rounded-full text-white shadow-xl flex items-center gap-2 ${message.type === 'success' ? 'bg-green-600' : 'bg-red-600'}`}>
          {message.type === 'success' ? <CheckCircle2 className="w-5 h-5" /> : <AlertCircle className="w-5 h-5" />}
          {message.text}
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
