        text += `   *Emb:* ${item.product.embalagem} - *Est. Marsil:* ${formatCurrency(item.product.estoqueMarsil)}\n\n`;
      });

      text += `📅 _Gerado em: ${new Date().toLocaleDateString()} ${new Date().toLocaleTimeString().slice(0,5)}_`;

      const url = `https://wa.me/${whatsappConfig.phoneNumber}?text=${encodeURIComponent(text)}`;
      window.open(url, '_blank');
    }

    // 2. Local State Save (Optional/Legacy but good for history)
    draftItems.forEach(item => {
      const fullProductName = item.product.sabor ? `${item.product.produto} - ${item.product.sabor}` : item.product.produto;
      onSubmitRequest({
        productId: item.product.id,
        productName: fullProductName,
        productCode: item.product.codigo,
        quantidade: item.quantidade,
        unidade: item.unidade,
        tipo: item.tipo,
        solicitante: solicitante
      });
    });

    setDraftItems([]);
    setMessage({ type: 'success', text: 'Lista enviada com sucesso!' });
