                <input type="text" placeholder="Fornecedor" className="w-full px-4 py-2 rounded-xl border border-gray-200 dark:border-slate-700 bg-white dark:bg-slate-800 dark:text-white text-sm" value={filterFornecedor} onChange={(e) => setFilterFornecedor(e.target.value)} />
