              <input type="text" placeholder="Descrição do Produto" className="w-full px-4 py-2 rounded-xl border border-gray-200 dark:border-slate-700 bg-white dark:bg-slate-800 dark:text-white text-sm" value={filterDescricao} onChange={(e) => setFilterDescricao(e.target.value)} />
            </div>

            {hasSearch && filteredProducts.length > 0 && !selectedProduct && (
              <div className="mt-4 max-h-[400px] overflow-y-auto border border-gray-100 dark:border-slate-800 rounded-xl divide-y dark:divide-slate-800 custom-scrollbar">
                {currentItems.map(p => (
