            </div>

            {hasSearch && filteredProducts.length > 0 && !selectedProduct && (
              <div className="mt-4 max-h-[300px] overflow-y-auto border border-gray-100 dark:border-slate-800 rounded-xl divide-y dark:divide-slate-800 custom-scrollbar">
                {currentItems.map(p => (
                  <button key={p.id} onClick={() => setSelectedProduct(p)} className="w-full text-left p-4 hover:bg-blue-50 dark:hover:bg-slate-800/80 transition-colors flex justify-between items-center group">
                    <div>
                      <p className="font-semibold dark:text-slate-200 text-sm">{p.produto}</p>
                      <p className="text-[10px] text-blue-600 font-bold uppercase">{p.codigo}</p>
