    }

    setDraftItems([...draftItems, { product: selectedProduct, ...formData }]);
    setSelectedProduct(null);
    setFormData({ ...formData, quantidade: 0, unidade: 'Unidade', tipo: 'Teste' });
    setMessage({ type: 'success', text: 'Adicionado!' });
    setTimeout(() => setMessage(null), 2000);
  };

  const removeItem = (index: number) => {
    setDraftItems(draftItems.filter((_, i) => i !== index));
  };

  const generateMessageText = () => {
    if (!solicitante) return '';
    let text = `📦 *PEDIDO MARSIL*\n👤 *Vend:* ${solicitante}\n\n`;
    draftItems.forEach((item) => {
      text += `QTD: ${item.quantidade} - Cód: ${item.product.codigo}\n`;
    });
    text += `\nPedido Extra Boracéia`;
    return text;
  };

  const handleCopyToClipboard = async () => {
    if (!solicitante) {
      setMessage({ type: 'error', text: 'Selecione seu nome primeiro.' });
      return;
    }
    const text = generateMessageText();
    try {
      await navigator.clipboard.writeText(text);
      setIsCopied(true);
      setMessage({ type: 'success', text: 'Pedido copiado!' });
      setTimeout(() => {
        setIsCopied(false);
        setMessage(null);
      }, 2000);
    } catch (err) {
      setMessage({ type: 'error', text: 'Erro ao copiar.' });
    }
  };

  const handleFinalSubmit = () => {
    if (!solicitante) {
      setMessage({ type: 'error', text: 'Selecione seu nome primeiro.' });
      return;
    }
    if (draftItems.length === 0) return;

    // WhatsApp Message Generation
    if (whatsappConfig.enabled && whatsappConfig.phoneNumber) {
      const text = generateMessageText();
      const url = `https://wa.me/${whatsappConfig.phoneNumber}?text=${encodeURIComponent(text)}`;
      window.open(url, '_blank');
    }

    // Save to local history
    draftItems.forEach(item => {
      const fullProductName = item.product.sabor ? `${item.product.produto} - ${item.product.sabor}` : item.product.produto;
      onSubmitRequest({
        productId: item.product.id,
        productName: fullProductName,
        productCode: item.product.codigo,
        quantidade: item.quantidade,
        unidade: item.unidade,
        tipo: item.tipo,
        solicitante: solicitante
      });
    });

    setDraftItems([]);
    setMessage({ type: 'success', text: 'Enviado!' });
    setTimeout(() => setMessage(null), 3000);
  };

  return (
    <div className="max-w-4xl w-full mx-auto space-y-6">
      <div className="bg-white dark:bg-slate-900 p-4 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800 flex flex-col md:flex-row items-center gap-4">
        <div className="flex items-center gap-2 text-gray-500 dark:text-slate-400">
          <UserCircle className="w-5 h-5" />
          <span className="text-sm font-bold uppercase tracking-wider">Vendedor:</span>
        </div>
        <select 
          required 
          className="flex-grow md:max-w-xs px-4 py-2 rounded-xl border border-gray-200 dark:border-slate-700 bg-gray-50 dark:bg-slate-800 dark:text-white font-bold outline-none focus:ring-2 focus:ring-blue-500" 
          value={solicitante} 
          onChange={(e) => setSolicitante(e.target.value)}
        >
          <option value="">SELECIONE SEU NOME...</option>
          {vendedores.map(v => <option key={v} value={v}>{v}</option>)}
        </select>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-5 gap-6">
        <div className="lg:col-span-3 space-y-6">
          <div className="bg-white dark:bg-slate-900 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800">
            <h2 className="text-lg font-bold mb-4 flex items-center gap-2 dark:text-white">
              <Filter className="w-5 h-5 text-blue-600" /> Buscar Itens
            </h2>
            <div className="space-y-3">
              <div className="grid grid-cols-2 gap-3">
                <input type="text" placeholder="Cód. Item" className="w-full px-4 py-2 rounded-xl border border-gray-200 dark:border-slate-700 bg-white dark:bg-slate-800 dark:text-white text-sm" value={filterCodigo} onChange={(e) => setFilterCodigo(e.target.value)} />
                <input type="text" placeholder="Fornecedor" className="w-full px-4 py-2 rounded-xl border border-gray-200 dark:border-slate-700 bg-white dark:bg-slate-800 dark:text-white text-sm" value={filterFornecedor} onChange={(e) => setFilterFornecedor(e.target.value)} />
              </div>
              <input type="text" placeholder="Produto..." className="w-full px-4 py-2 rounded-xl border border-gray-200 dark:border-slate-700 bg-white dark:bg-slate-800 dark:text-white text-sm" value={filterDescricao} onChange={(e) => setFilterDescricao(e.target.value)} />
            </div>

            {hasSearch && filteredProducts.length > 0 && !selectedProduct && (
              <div className="mt-4 max-h-[300px] overflow-y-auto border border-gray-100 dark:border-slate-800 rounded-xl divide-y dark:divide-slate-800 custom-scrollbar">
                {currentItems.map(p => (
                  <button key={p.id} onClick={() => setSelectedProduct(p)} className="w-full text-left p-4 hover:bg-blue-50 dark:hover:bg-slate-800/80 transition-colors flex justify-between items-center group">
                    <div>
                      <p className="font-semibold dark:text-slate-200 text-sm">{p.produto}</p>
                      <p className="text-[10px] text-blue-600 font-bold uppercase">{p.codigo}</p>
                    </div>
                    <div className="text-right">
                      <p className="text-xs font-bold text-blue-600">{formatCurrency(p.estoqueMarsil)}</p>
                      <p className="text-[9px] text-gray-400 uppercase">Estoque</p>
                    </div>
                  </button>
                ))}
              </div>
            )}
          </div>

          {selectedProduct && (
            <div className="bg-white dark:bg-slate-900 rounded-2xl shadow-lg border-2 border-blue-500 overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-300">
              <div className="bg-blue-600 p-3 text-white flex justify-between items-center">
                <h3 className="text-sm font-bold truncate pr-4">{selectedProduct.produto}</h3>
                <button onClick={() => setSelectedProduct(null)} className="hover:bg-blue-700 p-1 rounded-md">✕</button>
              </div>
              <form onSubmit={addToDraft} className="p-4 space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-[10px] font-bold text-gray-400 uppercase ml-1">Quantidade</label>
                    <input type="number" required min="1" className="w-full px-3 py-2 rounded-lg border dark:border-slate-700 bg-white dark:bg-slate-800 dark:text-white" value={formData.quantidade || ''} onChange={(e) => setFormData({...formData, quantidade: parseInt(e.target.value) || 0})} />
                  </div>
                  <div>
                    <label className="text-[10px] font-bold text-gray-400 uppercase ml-1">Unidade</label>
                    <select className="w-full px-3 py-2 rounded-lg border dark:border-slate-700 bg-white dark:bg-slate-800 dark:text-white" value={formData.unidade} onChange={(e) => setFormData({...formData, unidade: e.target.value as UnitType})}>
                      <option value="Unidade">Unidade</option>
                      <option value="Caixa">Caixa</option>
                    </select>
                  </div>
                </div>
                <button type="submit" className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-2.5 rounded-xl flex items-center justify-center gap-2 text-sm shadow-md transition-all active:scale-95">
                  <ListPlus className="w-4 h-4" /> Adicionar à Lista
                </button>
              </form>
            </div>
          )}
        </div>

        <div className="lg:col-span-2 space-y-4">
          <div className="bg-white dark:bg-slate-900 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800 flex flex-col h-full min-h-[400px]">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-lg font-bold flex items-center gap-2 dark:text-white">
                <ShoppingCart className="w-5 h-5 text-emerald-600" /> Sua Lista
              </h2>
              <span className={`text-xs font-bold px-2.5 py-1 rounded-full ${draftItems.length >= 10 ? 'bg-red-100 text-red-600' : 'bg-emerald-100 text-emerald-600'}`}>
                {draftItems.length}/10
              </span>
            </div>

            <div className="flex-grow space-y-3 mb-6">
              {draftItems.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-12 text-gray-400 opacity-50">
                  <Package className="w-12 h-12 mb-2" />
                  <p className="text-sm font-medium">Lista vazia</p>
                </div>
              ) : (
                <div className="space-y-2">
                  {draftItems.map((item, idx) => (
                    <div key={idx} className="group relative bg-gray-50 dark:bg-slate-800/50 p-3 rounded-xl border border-gray-100 dark:border-slate-800 transition-all">
                      <div className="flex justify-between items-start pr-8">
                        <div>
                          <p className="text-xs font-bold dark:text-slate-200 line-clamp-1">{item.product.produto}</p>
                          <p className="text-[10px] text-blue-600 font-bold mt-1">
                            QTD: {item.quantidade} - Cód: {item.product.codigo}
                          </p>
                        </div>
                        <button onClick={() => removeItem(idx)} className="absolute right-3 top-3 p-1 text-gray-400 hover:text-red-500 transition-colors">
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            <div className="mt-auto space-y-3">
              <div className="grid grid-cols-1 gap-2">
                <button 
                  onClick={handleFinalSubmit}
                  disabled={draftItems.length === 0 || !solicitante}
                  className="w-full bg-emerald-600 hover:bg-emerald-700 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold py-4 rounded-xl flex items-center justify-center gap-2 shadow-lg shadow-emerald-200 dark:shadow-none transition-all transform active:scale-95"
                >
                  <MessageCircle className="w-5 h-5" />
                  Enviar WhatsApp ({draftItems.length})
                </button>

                <button 
                  onClick={handleCopyToClipboard}
                  disabled={draftItems.length === 0 || !solicitante}
                  className="w-full bg-gray-100 dark:bg-slate-800 hover:bg-gray-200 dark:hover:bg-slate-700 disabled:opacity-50 disabled:cursor-not-allowed text-gray-700 dark:text-slate-200 font-bold py-3 rounded-xl flex items-center justify-center gap-2 transition-all transform active:scale-95 text-sm"
                >
                  {isCopied ? <ClipboardCheck className="w-4 h-4 text-emerald-500" /> : <Copy className="w-4 h-4" />}
                  {isCopied ? 'Pedido Copiado!' : 'Copiar Pedido'}
                </button>
              </div>

              {!solicitante && draftItems.length > 0 && (
                <p className="text-[10px] text-red-500 text-center font-bold animate-pulse">⚠️ Selecione o Vendedor!</p>
              )}

              <div className="pt-2 border-t border-gray-50 dark:border-slate-800">
                 <p className="text-[10px] text-center text-gray-400 dark:text-slate-500 font-bold italic">Pedido Extra Boracéia</p>
              </div>
            </div>
          </div>
        </div>
      </div>

      {message && (
        <div className={`fixed bottom-8 left-1/2 -translate-x-1/2 px-6 py-3 rounded-full text-white shadow-2xl flex items-center gap-2 z-[100] animate-in fade-in slide-in-from-bottom-4 ${message.type === 'success' ? 'bg-green-600' : 'bg-red-600'}`}>
          {message.type === 'success' ? <CheckCircle2 className="w-5 h-5" /> : <AlertCircle className="w-5 h-5" />}
          <span className="font-bold text-sm">{message.text}</span>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { UserPortal } from './components/UserPortal';
import { AdminPortal } from './components/AdminPortal';
import { AppState, Product, StockRequest, WhatsAppConfig } from './types';
import { LayoutDashboard, Users, ShieldCheck, Sun, Moon, Lock, KeyRound, ArrowRight } from 'lucide-react';

const STORAGE_KEY = 'marsil_boraceia_db_v1';
const THEME_KEY = 'marsil_theme_pref';
const USER_PASSWORD = '@marsil2026';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'user' | 'admin'>('user');
  const [isUserAuthenticated, setIsUserAuthenticated] = useState(false);
  const [passwordInput, setPasswordInput] = useState('');
  const [loginError, setLoginError] = useState(false);

  const [isDarkMode, setIsDarkMode] = useState(() => {
    const savedTheme = localStorage.getItem(THEME_KEY);
    return savedTheme === 'dark';
  });

  const [appState, setAppState] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    const parsed = saved ? JSON.parse(saved) : { 
      products: [], 
      requests: [], 
      vendedores: [],
      whatsappConfig: { enabled: false, phoneNumber: '' }
    };
    if (!parsed.vendedores) parsed.vendedores = [];
    if (!parsed.whatsappConfig) parsed.whatsappConfig = { enabled: false, phoneNumber: '' };
    return parsed;
  });

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(appState));
  }, [appState]);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem(THEME_KEY, 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem(THEME_KEY, 'light');
    }
  }, [isDarkMode]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordInput === USER_PASSWORD) {
      setIsUserAuthenticated(true);
      setLoginError(false);
    } else {
      setLoginError(true);
      setTimeout(() => setLoginError(false), 3000);
    }
  };

  const handleUploadData = (newProducts: Product[]) => {
    setAppState(prev => ({ ...prev, products: newProducts }));
  };

  const handleAddVendedor = (name: string) => {
    if (!appState.vendedores.includes(name)) {
      setAppState(prev => ({ ...prev, vendedores: [...prev.vendedores, name].sort() }));
    }
  };

  const handleRemoveVendedor = (name: string) => {
    setAppState(prev => ({ ...prev, vendedores: prev.vendedores.filter(v => v !== name) }));
  };

  const handleUpdateWhatsApp = (config: WhatsAppConfig) => {
    setAppState(prev => ({ ...prev, whatsappConfig: config }));
  };

  const handleSubmitRequest = (req: Omit<StockRequest, 'id' | 'dataSolicitacao' | 'status'>) => {
    const newRequest: StockRequest = {
      ...req,
      id: `req-${Date.now()}`,
      dataSolicitacao: new Date().toISOString(),
      status: 'Pendente'
    };
    setAppState(prev => ({
      ...prev,
      requests: [newRequest, ...prev.requests]
    }));
  };

  const handleUpdateRequestStatus = (requestId: string, status: StockRequest['status']) => {
    setAppState(prev => ({
      ...prev,
      requests: prev.requests.map(r => r.id === requestId ? { ...r, status } : r)
    }));
  };

  const handleClearRequests = () => {
    if (window.confirm('Deseja realmente apagar todo o histórico de solicitações?')) {
      setAppState(prev => ({ ...prev, requests: [] }));
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-slate-950 text-gray-900 dark:text-slate-100 transition-colors duration-300">
      <header className="bg-white dark:bg-slate-900 border-b border-gray-200 dark:border-slate-800 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-2 sm:gap-3">
              <div className="bg-blue-600 p-1.5 sm:p-2 rounded-lg shrink-0">
                <LayoutDashboard className="w-5 h-5 sm:w-6 sm:h-6 text-white" />
              </div>
              <div className="flex flex-col">
                <h1 className="text-base sm:text-xl font-bold bg-gradient-to-r from-blue-700 to-blue-500 bg-clip-text text-transparent truncate max-w-[120px] sm:max-w-none">
                  Marsil & Boracéia
                </h1>
                <p className="text-[8px] sm:text-[10px] text-gray-400 dark:text-slate-500 font-bold tracking-widest uppercase">
                  Estoque
                </p>
              </div>
            </div>

            <div className="flex items-center gap-2 sm:gap-4">
              <button
                onClick={() => setIsDarkMode(!isDarkMode)}
                className="p-2 rounded-lg bg-gray-50 dark:bg-slate-800 text-gray-500 dark:text-slate-400"
              >
                {isDarkMode ? <Sun className="w-4 h-4 sm:w-5 sm:h-5" /> : <Moon className="w-4 h-4 sm:w-5 sm:h-5" />}
              </button>

              <nav className="flex bg-gray-100 dark:bg-slate-800 p-1 rounded-xl shadow-inner">
                <button
                  onClick={() => setActiveTab('user')}
                  className={`flex items-center gap-1.5 px-3 sm:px-4 py-1.5 text-xs sm:text-sm font-bold rounded-lg transition-all ${
                    activeTab === 'user' 
                      ? 'bg-white dark:bg-slate-700 text-blue-600 dark:text-blue-400 shadow-sm' 
                      : 'text-gray-400 dark:text-slate-500 hover:text-gray-600'
                  }`}
                >
                  <Users className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
                  <span className="hidden xs:inline">Vend</span><span className="xs:hidden">V</span>
                </button>
                <button
                  onClick={() => setActiveTab('admin')}
                  className={`flex items-center gap-1.5 px-3 sm:px-4 py-1.5 text-xs sm:text-sm font-bold rounded-lg transition-all ${
                    activeTab === 'admin' 
                      ? 'bg-white dark:bg-slate-700 text-blue-600 dark:text-blue-400 shadow-sm' 
                      : 'text-gray-400 dark:text-slate-500 hover:text-gray-600'
                  }`}
                >
                  <ShieldCheck className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
                  <span className="hidden xs:inline">Adm</span><span className="xs:hidden">A</span>
                </button>
              </nav>
            </div>
          </div>
        </div>
      </header>

      <main className="flex-grow p-4 sm:p-6 lg:p-8 flex flex-col items-center overflow-x-hidden">
        {activeTab === 'user' ? (
          !isUserAuthenticated ? (
            <div className="w-full max-w-sm mt-8 sm:mt-12 animate-in fade-in slide-in-from-bottom-8 duration-500 px-4">
              <div className="bg-white dark:bg-slate-900 p-6 sm:p-8 rounded-3xl shadow-xl border border-gray-100 dark:border-slate-800 text-center">
                <div className="w-12 h-12 sm:w-16 sm:h-16 bg-blue-50 dark:bg-blue-900/30 rounded-full flex items-center justify-center mx-auto mb-4 sm:mb-6">
                  <Lock className="w-6 h-6 sm:w-8 sm:h-8 text-blue-600 dark:text-blue-400" />
                </div>
                <h2 className="text-xl sm:text-2xl font-bold dark:text-white mb-2">Acesso Restrito</h2>
                <p className="text-xs sm:text-sm text-gray-500 dark:text-slate-400 mb-6 sm:mb-8">Digite a senha para acessar.</p>

                <form onSubmit={handleLogin} className="space-y-4">
                  <div className="relative">
                    <KeyRound className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                    <input
                      type="password"
                      placeholder="Senha"
                      value={passwordInput}
                      onChange={(e) => setPasswordInput(e.target.value)}
                      className={`w-full pl-12 pr-4 py-3.5 rounded-xl border text-base sm:text-sm ${
                        loginError ? 'border-red-500 bg-red-50' : 'border-gray-200 dark:border-slate-700'
                      } bg-white dark:bg-slate-800 outline-none transition-all dark:text-white`}
                    />
                  </div>
                  <button type="submit" className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-3.5 rounded-xl transition-all flex items-center justify-center gap-2 shadow-lg active:scale-95">
                    Entrar <ArrowRight className="w-5 h-5" />
                  </button>
                </form>
              </div>
            </div>
          ) : (
            <UserPortal 
              products={appState.products} 
              requests={appState.requests}
              vendedores={appState.vendedores}
              whatsappConfig={appState.whatsappConfig}
              onSubmitRequest={handleSubmitRequest}
            />
          )
        ) : (
          <AdminPortal 
            appState={appState}
            onUploadData={handleUploadData}
            onAddVendedor={handleAddVendedor}
            onRemoveVendedor={handleRemoveVendedor}
            onUpdateWhatsApp={handleUpdateWhatsApp}
            onUpdateRequestStatus={handleUpdateRequestStatus}
            onClearRequests={handleClearRequests}
          />
        )}
      </main>

      <footer className="bg-white dark:bg-slate-900 border-t border-gray-100 dark:border-slate-800 py-6 mt-auto">
        <div className="max-w-7xl mx-auto px-4 flex justify-between items-center text-gray-400 text-[10px] sm:text-xs">
          <p>© 2024 Marsil Logística.</p>
          <p className="hidden xs:block">Unidade Boracéia-SP</p>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { Search, Send, AlertCircle, CheckCircle2, UserCircle, Package, Truck, Filter, Layers, MessageCircle, Trash2, ListPlus, ShoppingCart, Copy, ClipboardCheck } from 'lucide-react';
import { Product, StockRequest, RequestType, UnitType, WhatsAppConfig } from '../types';
import { formatCurrency } from '../utils';

interface UserPortalProps {
  products: Product[];
  requests: StockRequest[];
  vendedores: string[];
  whatsappConfig: WhatsAppConfig;
  onSubmitRequest: (req: Omit<StockRequest, 'id' | 'dataSolicitacao' | 'status'>) => void;
}

interface DraftItem {
  product: Product;
  quantidade: number;
  unidade: UnitType;
  tipo: RequestType;
}

const ITEMS_PER_PAGE = 10;

export const UserPortal: React.FC<UserPortalProps> = ({ products, requests, vendedores, whatsappConfig, onSubmitRequest }) => {
  const [filterCodigo, setFilterCodigo] = useState('');
  const [filterFornecedor, setFilterFornecedor] = useState('');
  const [filterDescricao, setFilterDescricao] = useState('');
  const [currentPage, setCurrentPage] = useState(1);

  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [solicitante, setSolicitante] = useState('');
  const [formData, setFormData] = useState({
    quantidade: 0,
    unidade: 'Unidade' as UnitType,
    tipo: 'Teste' as RequestType
  });

  const [draftItems, setDraftItems] = useState<DraftItem[]>([]);
  const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);
  const [isCopied, setIsCopied] = useState(false);

  const hasSearch = useMemo(() => filterCodigo.length >= 2 || filterFornecedor.length >= 3 || filterDescricao.length >= 3, [filterCodigo, filterFornecedor, filterDescricao]);

  const filteredProducts = useMemo(() => {
    if (!hasSearch) return [];
    return products.filter(p => {
      const matchCodigo = filterCodigo === '' || p.codigo.toLowerCase().includes(filterCodigo.toLowerCase());
      const matchFornecedor = filterFornecedor === '' || p.fornecedor.toLowerCase().includes(filterFornecedor.toLowerCase());
      const matchDescricao = filterDescricao === '' || p.produto.toLowerCase().includes(filterDescricao.toLowerCase());
      return matchCodigo && matchFornecedor && matchDescricao;
    });
  }, [products, filterCodigo, filterFornecedor, filterDescricao, hasSearch]);

  useEffect(() => setCurrentPage(1), [filterCodigo, filterFornecedor, filterDescricao]);

  const currentItems = useMemo(() => filteredProducts.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE), [filteredProducts, currentPage]);

  const addToDraft = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedProduct || formData.quantidade <= 0) {
      setMessage({ type: 'error', text: 'Informe a quantidade.' });
      return;
    }

    if (draftItems.length >= 10) {
      setMessage({ type: 'error', text: 'Limite de 10 itens atingido.' });
      return;
    }

    setDraftItems([...draftItems, { product: selectedProduct, ...formData }]);
    setSelectedProduct(null);
    setFormData({ ...formData, quantidade: 0, unidade: 'Unidade', tipo: 'Teste' });
    setMessage({ type: 'success', text: 'Adicionado!' });
    setTimeout(() => setMessage(null), 2000);
  };

  const removeItem = (index: number) => {
    setDraftItems(draftItems.filter((_, i) => i !== index));
  };

  const generateMessageText = () => {
    if (!solicitante) return '';
    let text = `📦 *PEDIDO MARSIL*\n👤 *Vend:* ${solicitante}\n\n`;
    draftItems.forEach((item) => {
      text += `QTD: ${item.quantidade} - Cód: ${item.product.codigo}\n`;
    });
    text += `\nPedido Extra Boracéia`;
    return text;
  };

  const handleCopyToClipboard = async () => {
    if (!solicitante) {
      setMessage({ type: 'error', text: 'Selecione o vendedor.' });
      return;
    }
    const text = generateMessageText();
    try {
      await navigator.clipboard.writeText(text);
      setIsCopied(true);
      setMessage({ type: 'success', text: 'Pedido copiado!' });
      setTimeout(() => {
        setIsCopied(false);
        setMessage(null);
      }, 2000);
    } catch (err) {
      setMessage({ type: 'error', text: 'Erro ao copiar.' });
    }
  };

  const handleFinalSubmit = () => {
    if (!solicitante) {
      setMessage({ type: 'error', text: 'Selecione o vendedor.' });
      return;
    }
    if (draftItems.length === 0) return;

    if (whatsappConfig.enabled && whatsappConfig.phoneNumber) {
      const text = generateMessageText();
      const url = `https://wa.me/${whatsappConfig.phoneNumber}?text=${encodeURIComponent(text)}`;
      window.open(url, '_blank');
    }

    draftItems.forEach(item => {
      const fullProductName = item.product.sabor ? `${item.product.produto} - ${item.product.sabor}` : item.product.produto;
      onSubmitRequest({
        productId: item.product.id,
        productName: fullProductName,
        productCode: item.product.codigo,
        quantidade: item.quantidade,
        unidade: item.unidade,
        tipo: item.tipo,
        solicitante: solicitante
      });
    });

    setDraftItems([]);
    setMessage({ type: 'success', text: 'Enviado!' });
    setTimeout(() => setMessage(null), 3000);
  };

  return (
    <div className="max-w-4xl w-full mx-auto space-y-4 sm:space-y-6 px-2 sm:px-0">
      {/* Vendedor Selector */}
      <div className="bg-white dark:bg-slate-900 p-4 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800 flex flex-col sm:flex-row items-center gap-3">
        <div className="flex items-center gap-2 text-gray-400 dark:text-slate-500 shrink-0">
          <UserCircle className="w-5 h-5" />
          <span className="text-[10px] font-bold uppercase tracking-widest">Seu Nome:</span>
        </div>
        <select 
          required 
          className="w-full sm:flex-grow sm:max-w-xs px-4 py-3 rounded-xl border border-gray-100 dark:border-slate-800 bg-gray-50 dark:bg-slate-800 dark:text-white font-bold text-sm outline-none focus:ring-2 focus:ring-blue-500 appearance-none" 
          value={solicitante} 
          onChange={(e) => setSolicitante(e.target.value)}
        >
          <option value="">SELECIONE...</option>
          {vendedores.map(v => <option key={v} value={v}>{v}</option>)}
        </select>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-5 gap-4 sm:gap-6">
        {/* Left: Search and Results */}
        <div className="lg:col-span-3 space-y-4 sm:space-y-6 order-1 lg:order-1">
          <div className="bg-white dark:bg-slate-900 p-5 sm:p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800">
            <h2 className="text-base sm:text-lg font-bold mb-4 flex items-center gap-2 dark:text-white">
              <Filter className="w-5 h-5 text-blue-600" /> Adicionar Produto
            </h2>
            <div className="space-y-3">
              <div className="grid grid-cols-1 xs:grid-cols-2 gap-3">
                <input 
                  type="text" 
                  placeholder="Cód. Item" 
                  className="w-full px-4 py-3 rounded-xl border border-gray-100 dark:border-slate-800 bg-white dark:bg-slate-800 dark:text-white text-sm" 
                  value={filterCodigo} 
                  onChange={(e) => setFilterCodigo(e.target.value)} 
                />
                <input 
                  type="text" 
                  placeholder="Fornecedor" 
                  className="w-full px-4 py-3 rounded-xl border border-gray-100 dark:border-slate-800 bg-white dark:bg-slate-800 dark:text-white text-sm" 
                  value={filterFornecedor} 
                  onChange={(e) => setFilterFornecedor(e.target.value)} 
                />
              </div>
              <input 
                type="text" 
                placeholder="Nome do produto..." 
                className="w-full px-4 py-3 rounded-xl border border-gray-100 dark:border-slate-800 bg-white dark:bg-slate-800 dark:text-white text-sm" 
                value={filterDescricao} 
                onChange={(e) => setFilterDescricao(e.target.value)} 
              />
            </div>

            {hasSearch && filteredProducts.length > 0 && !selectedProduct && (
              <div className="mt-4 max-h-[350px] sm:max-h-[300px] overflow-y-auto border border-gray-50 dark:border-slate-800 rounded-xl divide-y dark:divide-slate-800 custom-scrollbar shadow-inner">
                {currentItems.map(p => (
                  <button key={p.id} onClick={() => setSelectedProduct(p)} className="w-full text-left p-4 hover:bg-blue-50 dark:hover:bg-slate-800/80 transition-colors flex justify-between items-center group active:bg-blue-100">
                    <div className="flex-grow pr-2">
                      <p className="font-semibold dark:text-slate-200 text-sm line-clamp-1">{p.produto}</p>
                      <p className="text-[10px] text-blue-600 font-bold uppercase">{p.codigo}</p>
                    </div>
                    <div className="text-right shrink-0">
                      <p className="text-xs font-bold text-blue-600">{formatCurrency(p.estoqueMarsil)}</p>
                      <p className="text-[8px] text-gray-400 uppercase font-bold">Estoque</p>
                    </div>
                  </button>
                ))}
              </div>
            )}

            {hasSearch && filteredProducts.length === 0 && (
              <div className="mt-4 p-8 text-center bg-gray-50 dark:bg-slate-800/50 rounded-xl border border-dashed border-gray-200 dark:border-slate-700">
                <Search className="w-8 h-8 text-gray-300 mx-auto mb-2" />
                <p className="text-sm text-gray-400">Nenhum item encontrado</p>
              </div>
            )}
          </div>

          {selectedProduct && (
            <div className="bg-white dark:bg-slate-900 rounded-3xl shadow-2xl border-2 border-blue-500 overflow-hidden animate-in fade-in zoom-in-95 duration-200 sticky bottom-4 z-40 lg:relative lg:bottom-0">
              <div className="bg-blue-600 p-4 text-white flex justify-between items-center">
                <div className="flex flex-col">
                  <span className="text-[8px] font-bold uppercase opacity-75">Selecionado:</span>
                  <h3 className="text-sm font-bold truncate pr-4">{selectedProduct.produto}</h3>
                </div>
                <button onClick={() => setSelectedProduct(null)} className="hover:bg-blue-700 p-2 rounded-xl transition-colors">
                  <X className="w-5 h-5" />
                </button>
              </div>
              <form onSubmit={addToDraft} className="p-5 space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-[10px] font-bold text-gray-400 dark:text-slate-500 uppercase ml-1 block mb-1">Qtd.</label>
                    <input 
                      type="number" 
                      required 
                      min="1" 
                      className="w-full px-4 py-3 rounded-xl border border-gray-100 dark:border-slate-800 bg-gray-50 dark:bg-slate-800 dark:text-white text-base sm:text-sm outline-none focus:ring-2 focus:ring-blue-500" 
                      value={formData.quantidade || ''} 
                      onChange={(e) => setFormData({...formData, quantidade: parseInt(e.target.value) || 0})} 
                    />
                  </div>
                  <div>
                    <label className="text-[10px] font-bold text-gray-400 dark:text-slate-500 uppercase ml-1 block mb-1">Unidade</label>
                    <select 
                      className="w-full px-4 py-3 rounded-xl border border-gray-100 dark:border-slate-800 bg-gray-50 dark:bg-slate-800 dark:text-white text-base sm:text-sm outline-none focus:ring-2 focus:ring-blue-500 appearance-none" 
                      value={formData.unidade} 
                      onChange={(e) => setFormData({...formData, unidade: e.target.value as UnitType})}
                    >
                      <option value="Unidade">Unidade</option>
                      <option value="Caixa">Caixa</option>
                    </select>
                  </div>
                </div>
                <button type="submit" className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-2 text-sm shadow-xl active:scale-95 transition-all">
                  <ListPlus className="w-5 h-5" /> Adicionar à Lista
                </button>
              </form>
            </div>
          )}
        </div>

        {/* Right: Cart/List Review */}
        <div className="lg:col-span-2 space-y-4 order-2 lg:order-2">
          <div className="bg-white dark:bg-slate-900 p-5 sm:p-6 rounded-3xl shadow-sm border border-gray-100 dark:border-slate-800 flex flex-col min-h-[400px]">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-base sm:text-lg font-bold flex items-center gap-2 dark:text-white">
                <ShoppingCart className="w-5 h-5 text-emerald-600" /> Sua Lista
              </h2>
              <span className={`text-[10px] font-bold px-3 py-1.5 rounded-full ${draftItems.length >= 10 ? 'bg-red-100 text-red-600' : 'bg-emerald-100 text-emerald-600'}`}>
                {draftItems.length}/10 Itens
              </span>
            </div>

            <div className="flex-grow space-y-3 mb-6">
              {draftItems.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-12 text-gray-300 dark:text-slate-700 opacity-50">
                  <Package className="w-16 h-16 mb-2" />
                  <p className="text-xs font-bold uppercase tracking-widest">Lista Vazia</p>
                </div>
              ) : (
                <div className="space-y-3">
                  {draftItems.map((item, idx) => (
                    <div key={idx} className="group relative bg-gray-50 dark:bg-slate-800/40 p-4 rounded-2xl border border-gray-100 dark:border-slate-800 transition-all active:scale-[0.98]">
                      <div className="flex justify-between items-start pr-8">
                        <div>
                          <p className="text-xs font-bold dark:text-slate-200 line-clamp-1">{item.product.produto}</p>
                          <p className="text-[10px] text-blue-600 font-bold mt-1.5 flex items-center gap-2">
                            <span className="bg-blue-100 dark:bg-blue-900/40 px-2 py-0.5 rounded uppercase">QTD: {item.quantidade}</span>
                            <span className="opacity-50">•</span>
                            <span>Cód: {item.product.codigo}</span>
                          </p>
                        </div>
                        <button 
                          onClick={() => removeItem(idx)} 
                          className="absolute right-2 top-2 p-2 text-gray-400 hover:text-red-500 transition-colors"
                          aria-label="Remover item"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            <div className="mt-auto space-y-3 pt-6 border-t border-gray-50 dark:border-slate-800">
              <div className="grid grid-cols-1 gap-2.5">
                <button 
                  onClick={handleFinalSubmit}
                  disabled={draftItems.length === 0 || !solicitante}
                  className="w-full bg-emerald-600 hover:bg-emerald-700 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold py-4.5 rounded-2xl flex items-center justify-center gap-2 shadow-lg shadow-emerald-200 dark:shadow-none transition-all active:scale-95"
                >
                  <MessageCircle className="w-5 h-5" />
                  <span className="text-sm">Enviar WhatsApp</span>
                </button>

                <button 
                  onClick={handleCopyToClipboard}
                  disabled={draftItems.length === 0 || !solicitante}
                  className="w-full bg-gray-100 dark:bg-slate-800 hover:bg-gray-200 dark:hover:bg-slate-700 disabled:opacity-50 disabled:cursor-not-allowed text-gray-700 dark:text-slate-200 font-bold py-3.5 rounded-2xl flex items-center justify-center gap-2 transition-all active:scale-95 text-xs"
                >
                  {isCopied ? <ClipboardCheck className="w-4 h-4 text-emerald-500" /> : <Copy className="w-4 h-4" />}
                  {isCopied ? 'Copiado!' : 'Copiar Pedido'}
                </button>
              </div>

              {!solicitante && draftItems.length > 0 && (
                <p className="text-[10px] text-red-500 text-center font-bold animate-pulse uppercase tracking-tight">⚠️ Por favor, selecione seu nome acima!</p>
              )}

              <div className="pt-2">
                 <p className="text-[9px] text-center text-gray-400 dark:text-slate-500 font-bold italic uppercase tracking-widest">Pedido Extra Boracéia</p>
              </div>
            </div>
          </div>
        </div>
      </div>

      {message && (
        <div className={`fixed bottom-6 left-4 right-4 sm:left-1/2 sm:right-auto sm:-translate-x-1/2 px-6 py-4 rounded-2xl text-white shadow-2xl flex items-center justify-center gap-3 z-[100] animate-in fade-in slide-in-from-bottom-8 ${message.type === 'success' ? 'bg-emerald-600' : 'bg-red-600'}`}>
          {message.type === 'success' ? <CheckCircle2 className="w-5 h-5" /> : <AlertCircle className="w-5 h-5" />}
          <span className="font-bold text-sm tracking-tight">{message.text}</span>
        </div>
      )}
    </div>
  );
};

const X = ({ className }: { className?: string }) => (
  <svg className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" />
  </svg>
);

import React, { useState } from 'react';
import { Upload, ListChecks, Database, FileText, CheckCircle, XCircle, Trash2, Users, Download, UserPlus, X, MessageSquare, Phone } from 'lucide-react';
import { Product, StockRequest, AppState, WhatsAppConfig } from '../types';
import { StatsCard } from './StatsCard';

interface AdminPortalProps {
  appState: AppState;
  onUploadData: (newProducts: Product[]) => void;
  onAddVendedor: (name: string) => void;
  onRemoveVendedor: (name: string) => void;
  onUpdateWhatsApp: (config: WhatsAppConfig) => void;
  onUpdateRequestStatus: (requestId: string, status: StockRequest['status']) => void;
  onClearRequests: () => void;
}

export const AdminPortal: React.FC<AdminPortalProps> = ({ 
  appState, 
  onUploadData, 
  onAddVendedor,
  onRemoveVendedor,
  onUpdateWhatsApp,
  onUpdateRequestStatus,
  onClearRequests
}) => {
  const [uploadStatus, setUploadStatus] = useState<string | null>(null);
  const [newVendedor, setNewVendedor] = useState('');

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setUploadStatus('Processando...');
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target?.result as string;
        const rows = text.split('\n').filter(r => r.trim() !== '');
        const dataRows = rows.slice(1);

        const parsedProducts: Product[] = dataRows.map((row, index) => {
          const cols = row.split(/,|;/);
          return {
            id: `p-${index}-${Date.now()}`,
            fornecedor: cols[0]?.trim() || 'N/A',
            codigo: cols[2]?.trim() || '0',
            situacao: cols[3]?.trim() || '',
            comprador: cols[4]?.trim() || '',
            produto: cols[5]?.trim() || '',
            sabor: cols[6]?.trim() || '',
            embalagem: cols[7]?.trim() || '',
            estoqueMarsil: parseInt(cols[8]) || 0,
            estoqueBoraceia: parseInt(cols[9]) || 0,
          };
        });

        onUploadData(parsedProducts);
        setUploadStatus(`OK: ${parsedProducts.length} itens.`);
        setTimeout(() => setUploadStatus(null), 3000);
      } catch (err) {
        setUploadStatus('Erro no arquivo.');
      }
    };
    reader.readAsText(file);
  };

  const handleAddVendedor = (e: React.FormEvent) => {
    e.preventDefault();
    if (newVendedor.trim()) {
      onAddVendedor(newVendedor.trim());
      setNewVendedor('');
    }
  };

  const exportToCSV = () => {
    if (appState.requests.length === 0) return;
    const headers = ['ID', 'Solicitante', 'Produto', 'Codigo', 'Quantidade', 'Unidade', 'Tipo', 'Data', 'Status'];
    const rows = appState.requests.map(req => [
      req.id, req.solicitante, req.productName, req.productCode, req.quantidade, req.unidade, req.tipo, new Date(req.dataSolicitacao).toLocaleString(), req.status
    ]);
    const csvContent = [headers.join(','), ...rows.map(row => row.map(val => `"${val}"`).join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `pedidos_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  return (
    <div className="space-y-6 sm:space-y-8 max-w-6xl w-full mx-auto px-2 sm:px-0">
      {/* Dashboard Stats - Responsive Grid */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
        <StatsCard label="Produtos" value={appState.products.length} icon={<Database className="w-4 h-4 sm:w-5 sm:h-5" />} color="bg-blue-600" />
        <StatsCard label="Vendedores" value={appState.vendedores.length} icon={<Users className="w-4 h-4 sm:w-5 sm:h-5" />} color="bg-emerald-600" />
        <StatsCard label="Pendentes" value={appState.requests.filter(r => r.status === 'Pendente').length} icon={<ListChecks className="w-4 h-4 sm:w-5 sm:h-5" />} color="bg-amber-600" />
        <StatsCard label="Total Hist." value={appState.requests.length} icon={<FileText className="w-4 h-4 sm:w-5 sm:h-5" />} color="bg-purple-600" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 sm:gap-8">
        {/* Left Column: Configs */}
        <div className="lg:col-span-1 space-y-6">
          {/* WhatsApp Config */}
          <div className="bg-white dark:bg-slate-900 p-5 sm:p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800">
            <h3 className="text-base sm:text-lg font-bold mb-5 flex items-center gap-2 dark:text-white">
              <MessageSquare className="w-5 h-5 text-green-600" />
              WhatsApp Admin
            </h3>
            <div className="space-y-5">
              <div className="flex items-center justify-between bg-gray-50 dark:bg-slate-800/50 p-3 rounded-xl">
                <span className="text-xs text-gray-600 dark:text-slate-400 font-bold uppercase tracking-wider">Habilitado</span>
                <button
                  onClick={() => onUpdateWhatsApp({ ...appState.whatsappConfig, enabled: !appState.whatsappConfig.enabled })}
                  className={`w-12 h-6 rounded-full transition-colors relative ${appState.whatsappConfig.enabled ? 'bg-green-500' : 'bg-gray-200 dark:bg-slate-700'}`}
                >
                  <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-transform ${appState.whatsappConfig.enabled ? 'left-7' : 'left-1'}`} />
                </button>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-bold text-gray-500 uppercase tracking-widest ml-1">Número Destino</label>
                <div className="relative">
                  <Phone className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                  <input
                    type="tel"
                    placeholder="5511999999999"
                    value={appState.whatsappConfig.phoneNumber}
                    onChange={(e) => onUpdateWhatsApp({ ...appState.whatsappConfig, phoneNumber: e.target.value.replace(/\D/g, '') })}
                    className="w-full pl-9 pr-4 py-3 rounded-xl border border-gray-100 dark:border-slate-800 bg-white dark:bg-slate-800 focus:ring-2 focus:ring-green-500 outline-none text-base sm:text-sm dark:text-white"
                  />
                </div>
                <p className="text-[9px] text-gray-400 font-medium px-1">Ex: 55 + DDD + Número sem espaços.</p>
              </div>
            </div>
          </div>

          {/* Vendors Management */}
          <div className="bg-white dark:bg-slate-900 p-5 sm:p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800">
            <h3 className="text-base sm:text-lg font-bold mb-5 flex items-center gap-2 dark:text-white">
              <Users className="w-5 h-5 text-emerald-600" />
              Equipe de Vendas
            </h3>
            <form onSubmit={handleAddVendedor} className="mb-4 flex gap-2">
              <input
                type="text"
                placeholder="Nome..."
                value={newVendedor}
                onChange={(e) => setNewVendedor(e.target.value)}
                className="flex-grow px-4 py-2.5 rounded-xl border border-gray-100 dark:border-slate-800 bg-white dark:bg-slate-800 outline-none dark:text-white text-base sm:text-sm"
              />
              <button type="submit" className="p-2.5 bg-emerald-600 text-white rounded-xl hover:bg-emerald-700 shadow-lg shadow-emerald-100 dark:shadow-none active:scale-95 transition-all">
                <UserPlus className="w-5 h-5" />
              </button>
            </form>
            <div className="space-y-2 max-h-48 overflow-y-auto pr-1 custom-scrollbar">
              {appState.vendedores.length === 0 ? (
                <p className="text-center py-4 text-xs text-gray-400 font-bold italic">Nenhum vendedor cadastrado</p>
              ) : (
                appState.vendedores.map(v => (
                  <div key={v} className="flex items-center justify-between p-3 rounded-xl bg-gray-50 dark:bg-slate-800/50 group border border-gray-100 dark:border-slate-800/50">
                    <span className="text-sm font-semibold dark:text-slate-200">{v}</span>
                    <button onClick={() => onRemoveVendedor(v)} className="p-1.5 text-gray-400 hover:text-red-500 transition-colors">
                      <X className="w-4 h-4" />
                    </button>
                  </div>
                ))
              )}
            </div>
          </div>

          {/* CSV Upload */}
          <div className="bg-white dark:bg-slate-900 p-5 sm:p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800">
            <h3 className="text-base sm:text-lg font-bold mb-4 flex items-center gap-2 dark:text-white"><Upload className="w-5 h-5 text-blue-600" /> Atualizar Planilha</h3>
            <label className="border-2 border-dashed rounded-2xl p-6 sm:p-8 flex flex-col items-center justify-center cursor-pointer border-gray-100 dark:border-slate-800 hover:border-blue-400 transition-all bg-gray-50/50 dark:bg-slate-800/30">
              <Upload className="w-8 h-8 text-gray-300 mb-2" />
              <p className="text-[10px] sm:text-xs text-gray-400 font-bold uppercase tracking-widest text-center">Selecionar CSV</p>
              <input type="file" className="hidden" accept=".csv" onChange={handleFileUpload} />
            </label>
            {uploadStatus && (
              <div className="mt-4 p-3 bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 text-xs rounded-xl text-center font-bold animate-pulse">
                {uploadStatus}
              </div>
            )}
          </div>
        </div>

        {/* Right Column: Requests Table */}
        <div className="lg:col-span-2">
          <div className="bg-white dark:bg-slate-900 rounded-3xl shadow-sm border border-gray-100 dark:border-slate-800 overflow-hidden flex flex-col h-full">
            <div className="p-5 sm:p-6 border-b border-gray-50 dark:border-slate-800 flex justify-between items-center bg-white dark:bg-slate-900 sticky top-0 z-20">
              <h3 className="text-base sm:text-lg font-bold dark:text-white">Pedidos Recebidos</h3>
              <div className="flex gap-2">
                <button 
                  onClick={exportToCSV} 
                  disabled={appState.requests.length === 0} 
                  className="px-3 py-2 text-[10px] font-bold bg-gray-50 dark:bg-slate-800 text-gray-600 dark:text-slate-300 rounded-xl hover:bg-gray-100 transition-all disabled:opacity-50"
                >
                  Exportar
                </button>
                {appState.requests.length > 0 && (
                  <button onClick={onClearRequests} className="px-3 py-2 text-[10px] font-bold text-red-500 bg-red-50 dark:bg-red-900/20 rounded-xl">Limpar</button>
                )}
              </div>
            </div>

            <div className="overflow-x-auto custom-scrollbar">
              <table className="w-full min-w-[600px]">
                <thead className="bg-gray-50 dark:bg-slate-800/80 text-left border-b border-gray-100 dark:border-slate-800">
                  <tr>
                    <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Origem</th>
                    <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Itens</th>
                    <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest text-center">Qtd</th>
                    <th className="px-6 py-4 text-right text-[10px] font-bold text-gray-400 uppercase tracking-widest">Ação</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50 dark:divide-slate-800">
                  {appState.requests.length === 0 ? (
                    <tr>
                      <td colSpan={4} className="px-6 py-12 text-center">
                        <FileText className="w-12 h-12 text-gray-100 dark:text-slate-800 mx-auto mb-2" />
                        <p className="text-sm text-gray-300 dark:text-slate-600 font-bold uppercase">Nenhum pedido histórico</p>
                      </td>
                    </tr>
                  ) : (
                    appState.requests.map(req => (
                      <tr key={req.id} className="hover:bg-gray-50 dark:hover:bg-slate-800/30 transition-colors">
                        <td className="px-6 py-4">
                          <p className="text-sm font-bold dark:text-slate-200">{req.solicitante}</p>
                          <p className="text-[9px] text-gray-400 font-bold uppercase mt-1">{new Date(req.dataSolicitacao).toLocaleDateString()} {new Date(req.dataSolicitacao).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
                        </td>
                        <td className="px-6 py-4">
                          <p className="text-sm font-semibold dark:text-slate-300 line-clamp-1">{req.productName}</p>
                          <p className="text-[10px] text-blue-500 font-mono font-bold mt-0.5">{req.productCode}</p>
                        </td>
                        <td className="px-6 py-4 text-center">
                          <span className="text-sm font-extrabold dark:text-slate-100">{req.quantidade}</span>
                          <span className="text-[9px] text-gray-400 block font-bold uppercase">{req.unidade}</span>
                        </td>
                        <td className="px-6 py-4 text-right">
                          {req.status === 'Pendente' ? (
                            <div className="flex justify-end gap-1">
                              <button onClick={() => onUpdateRequestStatus(req.id, 'Aprovado')} className="p-2 text-emerald-500 hover:bg-emerald-50 dark:hover:bg-emerald-900/20 rounded-xl transition-all" title="Aprovar"><CheckCircle className="w-5 h-5" /></button>
                              <button onClick={() => onUpdateRequestStatus(req.id, 'Recusado')} className="p-2 text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-xl transition-all" title="Recusar"><XCircle className="w-5 h-5" /></button>
                            </div>
                          ) : (
                            <span className={`text-[10px] font-black uppercase px-2.5 py-1 rounded-lg ${req.status === 'Aprovado' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400' : 'bg-red-100 text-red-600 dark:bg-red-900/20 dark:text-red-400'}`}>
                              {req.status}
                            </span>
                          )}
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React from 'react';

