import React, { useState } from 'react';
import { Upload, ListChecks, Database, FileText, CheckCircle, XCircle, Trash2, Users, Download, UserPlus, X, MessageSquare, Phone, Link2, Copy, Check, AlertCircle } from 'lucide-react';
import { Product, StockRequest, AppState, WhatsAppConfig } from '../types';
import { StatsCard } from './StatsCard';

interface AdminPortalProps {
  appState: AppState;
  onUploadData: (newProducts: Product[]) => void;
  onAddVendedor: (name: string) => void;
  onRemoveVendedor: (name: string) => void;
  onUpdateWhatsApp: (config: WhatsAppConfig) => void;
  onUpdateRequestStatus: (requestId: string, status: StockRequest['status']) => void;
  onClearRequests: () => void;
}

export const AdminPortal: React.FC<AdminPortalProps> = ({ 
  appState, 
  onUploadData, 
  onAddVendedor,
  onRemoveVendedor,
  onUpdateWhatsApp,
  onUpdateRequestStatus,
  onClearRequests
}) => {
  const [uploadStatus, setUploadStatus] = useState<{message: string, type: 'success' | 'error' | 'info'} | null>(null);
  const [newVendedor, setNewVendedor] = useState('');
  const [copiedLink, setCopiedLink] = useState<'admin' | 'vendedor' | null>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setUploadStatus({ message: 'Processando planilha...', type: 'info' });
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target?.result as string;
        // Tenta identificar o separador (vírgula ou ponto e vírgula)
        const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
        if (lines.length < 2) throw new Error("Arquivo vazio ou sem dados.");

        const header = lines[0].toLowerCase();
        const separator = header.includes(';') ? ';' : ',';
        const columns = lines[0].split(separator).map(c => c.trim().toLowerCase());

        // Mapeamento dinâmico de colunas
        const idx = {
          fornecedor: columns.findIndex(c => c.includes('fornecedor')),
          codigo: columns.findIndex(c => c.includes('código') || c.includes('codigo')),
          situacao: columns.findIndex(c => c.includes('situação') || c.includes('situacao')),
          comprador: columns.findIndex(c => c.includes('comprador')),
          produto: columns.findIndex(c => c.includes('produto') || c.includes('descrição') || c.includes('item')),
          marsil: columns.findIndex(c => c.includes('marsil') || c.includes('estoque sp')),
          boraceia: columns.findIndex(c => c.includes('boraceia') || c.includes('estoque bor')),
        };

        const parsedProducts: Product[] = lines.slice(1).map((row, i) => {
          const cols = row.split(separator).map(c => c.trim().replace(/"/g, ''));
          return {
            id: `p-${i}-${Date.now()}`,
            fornecedor: cols[idx.fornecedor] || 'N/D',
            codigo: cols[idx.codigo] || '0',
            situacao: cols[idx.situacao] || '',
            comprador: cols[idx.comprador] || '',
            produto: cols[idx.produto] || 'Produto sem nome',
            sabor: '', // Campo opcional
            embalagem: '', // Campo opcional
            estoqueMarsil: parseInt(cols[idx.marsil]) || 0,
            estoqueBoraceia: parseInt(cols[idx.boraceia]) || 0,
          };
        });

        onUploadData(parsedProducts);
        setUploadStatus({ 
          message: `Sucesso! ${parsedProducts.length} itens carregados e prontos para pesquisa.`, 
          type: 'success' 
        });
        setTimeout(() => setUploadStatus(null), 5000);
      } catch (err) {
        setUploadStatus({ message: 'Erro ao ler CSV. Verifique o formato.', type: 'error' });
      }
    };
    reader.readAsText(file, 'UTF-8');
  };

  const handleAddVendedor = (e: React.FormEvent) => {
    e.preventDefault();
    if (newVendedor.trim()) {
      onAddVendedor(newVendedor.trim());
      setNewVendedor('');
    }
  };

  const copyLink = (type: 'admin' | 'vendedor') => {
    const baseUrl = window.location.origin + window.location.pathname;
    const url = `${baseUrl}?portal=${type}`;
    navigator.clipboard.writeText(url).then(() => {
      setCopiedLink(type);
      setTimeout(() => setCopiedLink(null), 2000);
    });
  };

  const exportToCSV = () => {
    if (appState.requests.length === 0) return;
    const headers = ['ID', 'Solicitante', 'Produto', 'Codigo', 'Quantidade', 'Unidade', 'Tipo', 'Data', 'Status'];
    const rows = appState.requests.map(req => [
      req.id, req.solicitante, req.productName, req.productCode, req.quantidade, req.unidade, req.tipo, new Date(req.dataSolicitacao).toLocaleString(), req.status
    ]);
    const csvContent = [headers.join(','), ...rows.map(row => row.map(val => `"${val}"`).join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `pedidos_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  return (
    <div className="space-y-6 sm:space-y-8 max-w-6xl w-full mx-auto px-2 sm:px-0">
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
        <StatsCard label="Produtos Ativos" value={appState.products.length} icon={<Database className="w-4 h-4 sm:w-5 sm:h-5" />} color="bg-blue-600" />
        <StatsCard label="Vendedores" value={appState.vendedores.length} icon={<Users className="w-4 h-4 sm:w-5 sm:h-5" />} color="bg-emerald-600" />
        <StatsCard label="Pedidos Pendentes" value={appState.requests.filter(r => r.status === 'Pendente').length} icon={<ListChecks className="w-4 h-4 sm:w-5 sm:h-5" />} color="bg-amber-600" />
        <StatsCard label="Total Histórico" value={appState.requests.length} icon={<FileText className="w-4 h-4 sm:w-5 sm:h-5" />} color="bg-purple-600" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 sm:gap-8">
        <div className="lg:col-span-1 space-y-6">
          {/* CSV Upload - Prominent */}
          <div className="bg-white dark:bg-slate-900 p-5 sm:p-6 rounded-2xl shadow-md border-2 border-blue-100 dark:border-blue-900/30">
            <h3 className="text-base sm:text-lg font-bold mb-4 flex items-center gap-2 dark:text-white">
              <Upload className="w-5 h-5 text-blue-600" /> Atualizar Estoque
            </h3>
            <p className="text-[10px] text-gray-400 font-bold uppercase mb-4 leading-tight">
              Suba a planilha diária para atualizar os dados de pesquisa para os vendedores.
            </p>
            <label className="border-2 border-dashed rounded-2xl p-6 sm:p-8 flex flex-col items-center justify-center cursor-pointer border-blue-200 dark:border-slate-800 hover:border-blue-500 hover:bg-blue-50 dark:hover:bg-slate-800/30 transition-all bg-gray-50/50 dark:bg-slate-800/30 group">
              <Upload className="w-10 h-10 text-blue-300 group-hover:text-blue-500 mb-3 transition-colors" />
              <p className="text-xs text-blue-600 dark:text-blue-400 font-black uppercase tracking-widest text-center">Selecionar Planilha (CSV)</p>
              <input type="file" className="hidden" accept=".csv" onChange={handleFileUpload} />
            </label>

            {uploadStatus && (
              <div className={`mt-4 p-4 rounded-xl flex items-center gap-3 animate-in fade-in slide-in-from-top-2 ${
                uploadStatus.type === 'success' ? 'bg-emerald-50 text-emerald-700 border border-emerald-100' : 
                uploadStatus.type === 'error' ? 'bg-red-50 text-red-700 border border-red-100' : 
                'bg-blue-50 text-blue-700 border border-blue-100'
              }`}>
                {uploadStatus.type === 'success' ? <CheckCircle className="w-5 h-5 shrink-0" /> : <AlertCircle className="w-5 h-5 shrink-0" />}
                <p className="text-[11px] font-bold leading-tight">{uploadStatus.message}</p>
              </div>
            )}
          </div>

          <div className="bg-white dark:bg-slate-900 p-5 sm:p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800">
            <h3 className="text-base sm:text-lg font-bold mb-5 flex items-center gap-2 dark:text-white">
              <Link2 className="w-5 h-5 text-blue-500" /> Links de Acesso
            </h3>
            <div className="space-y-3">
              <button onClick={() => copyLink('vendedor')} className="w-full flex items-center justify-between p-3 bg-gray-50 dark:bg-slate-800/50 rounded-xl hover:bg-gray-100 dark:hover:bg-slate-800 transition-all group">
                <div className="text-left">
                  <p className="text-xs font-bold dark:text-white">Link Vendedor</p>
                  <p className="text-[9px] text-gray-400 uppercase font-black">Enviar para a equipe</p>
                </div>
                {copiedLink === 'vendedor' ? <Check className="w-4 h-4 text-emerald-500" /> : <Copy className="w-4 h-4 text-gray-400 group-hover:text-blue-500" />}
              </button>
              <button onClick={() => copyLink('admin')} className="w-full flex items-center justify-between p-3 bg-gray-50 dark:bg-slate-800/50 rounded-xl hover:bg-gray-100 dark:hover:bg-slate-800 transition-all group">
                <div className="text-left">
                  <p className="text-xs font-bold dark:text-white">Link Administrativo</p>
                  <p className="text-[9px] text-gray-400 uppercase font-black">Acesso restrito</p>
                </div>
                {copiedLink === 'admin' ? <Check className="w-4 h-4 text-emerald-500" /> : <Copy className="w-4 h-4 text-gray-400 group-hover:text-blue-500" />}
              </button>
            </div>
          </div>

          <div className="bg-white dark:bg-slate-900 p-5 sm:p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800">
            <h3 className="text-base sm:text-lg font-bold mb-5 flex items-center gap-2 dark:text-white">
              <Users className="w-5 h-5 text-emerald-600" /> Equipe de Vendas
            </h3>
            <form onSubmit={handleAddVendedor} className="mb-4 flex gap-2">
              <input type="text" placeholder="Nome..." value={newVendedor} onChange={(e) => setNewVendedor(e.target.value)} className="flex-grow px-4 py-2.5 rounded-xl border border-gray-100 dark:border-slate-800 bg-white dark:bg-slate-800 outline-none dark:text-white text-base sm:text-sm" />
              <button type="submit" className="p-2.5 bg-emerald-600 text-white rounded-xl hover:bg-emerald-700 shadow-lg active:scale-95 transition-all"><UserPlus className="w-5 h-5" /></button>
            </form>
            <div className="space-y-2 max-h-48 overflow-y-auto pr-1 custom-scrollbar">
              {appState.vendedores.length === 0 ? <p className="text-center py-4 text-xs text-gray-400 font-bold italic">Nenhum vendedor cadastrado</p> : appState.vendedores.map(v => (
                <div key={v} className="flex items-center justify-between p-3 rounded-xl bg-gray-50 dark:bg-slate-800/50 group border border-gray-100 dark:border-slate-800/50">
                  <span className="text-sm font-semibold dark:text-slate-200">{v}</span>
                  <button onClick={() => onRemoveVendedor(v)} className="p-1.5 text-gray-400 hover:text-red-500 transition-colors"><X className="w-4 h-4" /></button>
                </div>
              ))}
            </div>
          </div>
        </div>

        <div className="lg:col-span-2">
          <div className="bg-white dark:bg-slate-900 rounded-3xl shadow-sm border border-gray-100 dark:border-slate-800 overflow-hidden flex flex-col h-full">
            <div className="p-5 sm:p-6 border-b border-gray-50 dark:border-slate-800 flex justify-between items-center bg-white dark:bg-slate-900 sticky top-0 z-20">
              <h3 className="text-base sm:text-lg font-bold dark:text-white">Pedidos Recebidos</h3>
              <div className="flex gap-2">
                <button onClick={exportToCSV} disabled={appState.requests.length === 0} className="px-3 py-2 text-[10px] font-bold bg-gray-50 dark:bg-slate-800 text-gray-600 dark:text-slate-300 rounded-xl hover:bg-gray-100 transition-all disabled:opacity-50">Exportar</button>
                {appState.requests.length > 0 && <button onClick={onClearRequests} className="px-3 py-2 text-[10px] font-bold text-red-500 bg-red-50 dark:bg-red-900/20 rounded-xl">Limpar</button>}
              </div>
            </div>

            <div className="overflow-x-auto custom-scrollbar">
              <table className="w-full min-w-[600px]">
                <thead className="bg-gray-50 dark:bg-slate-800/80 text-left border-b border-gray-100 dark:border-slate-800">
                  <tr>
                    <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Origem</th>
                    <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Itens</th>
                    <th className="px-6 py-4 text-center text-[10px] font-bold text-gray-400 uppercase tracking-widest">Qtd</th>
                    <th className="px-6 py-4 text-right text-[10px] font-bold text-gray-400 uppercase tracking-widest">Ação</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50 dark:divide-slate-800">
                  {appState.requests.length === 0 ? (
                    <tr>
                      <td colSpan={4} className="px-6 py-12 text-center">
                        <FileText className="w-12 h-12 text-gray-100 dark:text-slate-800 mx-auto mb-2" />
                        <p className="text-sm text-gray-300 dark:text-slate-600 font-bold uppercase">Nenhum pedido histórico</p>
                      </td>
                    </tr>
                  ) : (
                    appState.requests.map(req => (
                      <tr key={req.id} className="hover:bg-gray-50 dark:hover:bg-slate-800/30 transition-colors">
                        <td className="px-6 py-4">
                          <p className="text-sm font-bold dark:text-slate-200">{req.solicitante}</p>
                          <p className="text-[9px] text-gray-400 font-bold uppercase mt-1">{new Date(req.dataSolicitacao).toLocaleDateString()} {new Date(req.dataSolicitacao).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
                        </td>
                        <td className="px-6 py-4">
                          <p className="text-sm font-semibold dark:text-slate-300 line-clamp-1">{req.productName}</p>
                          <p className="text-[10px] text-blue-500 font-mono font-bold mt-0.5">{req.productCode}</p>
                        </td>
                        <td className="px-6 py-4 text-center">
                          <span className="text-sm font-extrabold dark:text-slate-100">{req.quantidade}</span>
                          <span className="text-[9px] text-gray-400 block font-bold uppercase">{req.unidade}</span>
                        </td>
                        <td className="px-6 py-4 text-right">
                          {req.status === 'Pendente' ? (
                            <div className="flex justify-end gap-1">
                              <button onClick={() => onUpdateRequestStatus(req.id, 'Aprovado')} className="p-2 text-emerald-500 hover:bg-emerald-50 dark:hover:bg-emerald-900/20 rounded-xl transition-all" title="Aprovar"><CheckCircle className="w-5 h-5" /></button>
                              <button onClick={() => onUpdateRequestStatus(req.id, 'Recusado')} className="p-2 text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-xl transition-all" title="Recusar"><XCircle className="w-5 h-5" /></button>
                            </div>
                          ) : (
                            <span className={`text-[10px] font-black uppercase px-2.5 py-1 rounded-lg ${req.status === 'Aprovado' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400' : 'bg-red-100 text-red-600 dark:bg-red-900/20 dark:text-red-400'}`}>
                              {req.status}
                            </span>
                          )}
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

{
  "name": "marsil-estoque-boraceia",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "tsc && vite build",
    "preview": "vite preview"
  },
  "dependencies": {
    "react": "^19.0.0",
    "react-dom": "^19.0.0",
    "lucide-react": "^0.474.0",
    "@google/genai": "latest",
    "@supabase/supabase-js": "^2.48.1"
  },
  "devDependencies": {
    "@types/react": "^19.0.0",
    "@types/react-dom": "^19.0.0",
    "@vitejs/plugin-react": "^4.3.4",
    "typescript": "^5.7.2",
    "vite": "^6.0.3"
  }
}

import { createClient } from '@supabase/supabase-js';

// Essas variáveis devem ser configuradas no seu ambiente (Vercel/Vite .env)
const supabaseUrl = (import.meta as any).env.VITE_SUPABASE_URL || '';
const supabaseAnonKey = (import.meta as any).env.VITE_SUPABASE_ANON_KEY || '';

export const supabase = createClient(supabaseUrl, supabaseAnonKey);

import React, { useState, useEffect } from 'react';
import { UserPortal } from './components/UserPortal';
import { AdminPortal } from './components/AdminPortal';
import { AppState, Product, StockRequest, WhatsAppConfig } from './types';
import { LayoutDashboard, Users, ShieldCheck, Sun, Moon, Lock, KeyRound, ArrowRight, LogOut, ChevronRight, Store, X, Loader2 } from 'lucide-react';
import { supabase } from './supabaseClient';

const THEME_KEY = 'marsil_theme_pref';
const AUTH_KEY = 'marsil_auth_role';

const PASSWORDS = {
  VENDOR: '@marsil2026',
  ADMIN: '@adminMarsil2026'
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'user' | 'admin'>('user');
  const [authRole, setAuthRole] = useState<'none' | 'vendor' | 'admin'>(() => {
    return (localStorage.getItem(AUTH_KEY) as any) || 'none';
  });

  const [loginTarget, setLoginTarget] = useState<'vendedor' | 'admin' | null>(null);
  const [passwordInput, setPasswordInput] = useState('');
  const [loginError, setLoginError] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  const [isDarkMode, setIsDarkMode] = useState(() => {
    const savedTheme = localStorage.getItem(THEME_KEY);
    return savedTheme === 'dark';
  });

  const [appState, setAppState] = useState<AppState>({ 
    products: [], 
    requests: [], 
    vendedores: [],
    whatsappConfig: { enabled: false, phoneNumber: '' }
  });

  // Carregar dados iniciais do Supabase
  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      try {
        const { data: products } = await supabase.from('products').select('*');
        const { data: requests } = await supabase.from('requests').select('*').order('dataSolicitacao', { ascending: false });
        const { data: vendedores } = await supabase.from('vendedores').select('name');
        const { data: config } = await supabase.from('config').select('*').single();

        setAppState({
          products: products || [],
          requests: requests || [],
          vendedores: vendedores?.map(v => v.name) || [],
          whatsappConfig: config?.value || { enabled: false, phoneNumber: '' }
        });
      } catch (error) {
        console.error("Erro ao carregar dados do Supabase:", error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, []);

  useEffect(() => {
    localStorage.setItem(AUTH_KEY, authRole);
  }, [authRole]);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem(THEME_KEY, 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem(THEME_KEY, 'light');
    }
  }, [isDarkMode]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const isTargetAdmin = loginTarget === 'admin';
    const requiredPass = isTargetAdmin ? PASSWORDS.ADMIN : PASSWORDS.VENDOR;

    if (passwordInput === requiredPass) {
      const role = isTargetAdmin ? 'admin' : 'vendor';
      setAuthRole(role);
      setActiveTab(isTargetAdmin ? 'admin' : 'user');
      setLoginError(false);
      setLoginTarget(null);
      window.history.replaceState({}, '', window.location.pathname);
    } else {
      setLoginError(true);
      setTimeout(() => setLoginError(false), 3000);
    }
    setPasswordInput('');
  };

  const handleLogout = () => {
    window.history.replaceState({}, '', window.location.pathname);
    setAuthRole('none');
    setLoginTarget(null);
    setPasswordInput('');
    setActiveTab('user');
    localStorage.removeItem(AUTH_KEY);
  };

  const handleUploadData = async (newProducts: Product[]) => {
    // No Supabase, geralmente deletamos os antigos e inserimos os novos para manter a planilha sincronizada
    setIsLoading(true);
    try {
      await supabase.from('products').delete().neq('id', '0'); // Limpa tabela
      const { error } = await supabase.from('products').insert(newProducts);
      if (!error) {
        setAppState(prev => ({ ...prev, products: newProducts }));
      }
    } catch (err) {
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleAddVendedor = async (name: string) => {
    if (!appState.vendedores.includes(name)) {
      const { error } = await supabase.from('vendedores').insert([{ name }]);
      if (!error) {
        setAppState(prev => ({ ...prev, vendedores: [...prev.vendedores, name].sort() }));
      }
    }
  };

  const handleRemoveVendedor = async (name: string) => {
    const { error } = await supabase.from('vendedores').delete().eq('name', name);
    if (!error) {
      setAppState(prev => ({ ...prev, vendedores: prev.vendedores.filter(v => v !== name) }));
    }
  };

  const handleUpdateWhatsApp = async (config: WhatsAppConfig) => {
    const { error } = await supabase.from('config').upsert({ key: 'whatsapp', value: config });
    if (!error) {
      setAppState(prev => ({ ...prev, whatsappConfig: config }));
    }
  };

  const handleSubmitRequest = async (req: Omit<StockRequest, 'id' | 'dataSolicitacao' | 'status'>) => {
    const newRequestData = {
      ...req,
      dataSolicitacao: new Date().toISOString(),
      status: 'Pendente'
    };

    const { data, error } = await supabase.from('requests').insert([newRequestData]).select().single();
    if (!error && data) {
      setAppState(prev => ({
        ...prev,
        requests: [data, ...prev.requests]
      }));
    }
  };

  const handleUpdateRequestStatus = async (requestId: string, status: StockRequest['status']) => {
    const { error } = await supabase.from('requests').update({ status }).eq('id', requestId);
    if (!error) {
      setAppState(prev => ({
        ...prev,
        requests: prev.requests.map(r => r.id === requestId ? { ...r, status } : r)
      }));
    }
  };

  const handleClearRequests = async () => {
    if (window.confirm('Deseja realmente apagar todo o histórico de solicitações?')) {
      const { error } = await supabase.from('requests').delete().neq('id', '0');
      if (!error) {
        setAppState(prev => ({ ...prev, requests: [] }));
      }
    }
  };

  if (isLoading && authRole !== 'none') {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-slate-950">
        <div className="flex flex-col items-center gap-4">
          <Loader2 className="w-10 h-10 text-blue-600 animate-spin" />
          <p className="text-sm font-bold text-gray-500 uppercase tracking-widest">Sincronizando com Nuvem...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-slate-950 text-gray-900 dark:text-slate-100 transition-colors duration-300">
      <header className="bg-white dark:bg-slate-900 border-b border-gray-200 dark:border-slate-800 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-2 sm:gap-3">
              <div className="bg-blue-600 p-1.5 sm:p-2 rounded-lg shrink-0">
                <LayoutDashboard className="w-5 h-5 sm:w-6 sm:h-6 text-white" />
              </div>
              <div className="flex flex-col">
                <h1 className="text-base sm:text-xl font-bold bg-gradient-to-r from-blue-700 to-blue-500 bg-clip-text text-transparent truncate max-w-[120px] sm:max-w-none">
                  Marsil & Boracéia
                </h1>
                {authRole !== 'none' && (
                  <p className="text-[8px] sm:text-[10px] text-gray-400 dark:text-slate-500 font-bold tracking-widest uppercase">
                    {authRole === 'admin' ? 'Painel Gestão' : 'Portal Vendas'}
                  </p>
                )}
              </div>
            </div>

            <div className="flex items-center gap-2 sm:gap-4">
              <button
                onClick={() => setIsDarkMode(!isDarkMode)}
                className="p-2 rounded-lg bg-gray-50 dark:bg-slate-800 text-gray-500 dark:text-slate-400 hover:bg-gray-100 dark:hover:bg-slate-700 transition-colors"
                title="Alternar Tema"
              >
                {isDarkMode ? <Sun className="w-4 h-4 sm:w-5 sm:h-5" /> : <Moon className="w-4 h-4 sm:w-5 sm:h-5" />}
              </button>

              {authRole !== 'none' && (
                <div className="flex items-center gap-2">
                  <nav className="flex bg-gray-100 dark:bg-slate-800 p-1 rounded-xl shadow-inner">
                    <button
                      onClick={() => setActiveTab('user')}
                      className={`flex items-center gap-1.5 px-3 sm:px-4 py-1.5 text-xs sm:text-sm font-bold rounded-lg transition-all ${
                        activeTab === 'user' 
                          ? 'bg-white dark:bg-slate-700 text-blue-600 dark:text-blue-400 shadow-sm' 
                          : 'text-gray-400 dark:text-slate-500 hover:text-gray-600'
                      }`}
                    >
                      <Users className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
                      <span className="hidden xs:inline">Vendedor</span><span className="xs:hidden">Vend</span>
                    </button>

                    {authRole === 'admin' && (
                      <button
                        onClick={() => setActiveTab('admin')}
                        className={`flex items-center gap-1.5 px-3 sm:px-4 py-1.5 text-xs sm:text-sm font-bold rounded-lg transition-all ${
                          activeTab === 'admin' 
                            ? 'bg-white dark:bg-slate-700 text-blue-600 dark:text-blue-400 shadow-sm' 
                            : 'text-gray-400 dark:text-slate-500 hover:text-gray-600'
                        }`}
                      >
                        <ShieldCheck className="w-3.5 h-3.5 sm:w-4 sm:h-4" />
                        <span className="hidden xs:inline">Admin</span><span className="xs:hidden">Adm</span>
                      </button>
                    )}
                  </nav>

                  <button
                    onClick={handleLogout}
                    className="p-2 rounded-lg bg-red-50 dark:bg-red-900/20 text-red-500 hover:bg-red-100 dark:hover:bg-red-900/40 transition-colors"
                    title="Sair do Sistema"
                  >
                    <LogOut className="w-4 h-4 sm:w-5 sm:h-5" />
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      </header>

      <main className="flex-grow p-4 sm:p-6 lg:p-8 flex flex-col items-center overflow-x-hidden">
        {authRole === 'none' ? (
          !loginTarget ? (
            <div className="w-full max-w-2xl mt-8 sm:mt-16 animate-in fade-in zoom-in-95 duration-500 space-y-8">
              <div className="text-center space-y-2">
                <h2 className="text-3xl sm:text-4xl font-black dark:text-white tracking-tight">Bem-vindo!</h2>
                <p className="text-gray-500 dark:text-slate-400 text-sm sm:text-base">Escolha o portal de acesso para continuar.</p>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                <button 
                  onClick={() => setLoginTarget('vendedor')}
                  className="group bg-white dark:bg-slate-900 p-8 rounded-3xl shadow-xl hover:shadow-2xl border-2 border-transparent hover:border-emerald-500 transition-all flex flex-col items-center text-center space-y-4 active:scale-[0.98]"
                >
                  <div className="w-20 h-20 bg-emerald-50 dark:bg-emerald-900/30 rounded-2xl flex items-center justify-center group-hover:bg-emerald-500 group-hover:text-white transition-all">
                    <Store className="w-10 h-10 text-emerald-600 group-hover:text-white" />
                  </div>
                  <div>
                    <h3 className="text-xl font-bold dark:text-white">Portal Vendedor</h3>
                    <p className="text-xs text-gray-400 dark:text-slate-500 font-medium mt-1">Consultar estoque e fazer pedidos.</p>
                  </div>
                  <div className="flex items-center gap-1 text-emerald-600 font-bold text-xs uppercase tracking-widest pt-2">
                    Acessar <ChevronRight className="w-4 h-4" />
                  </div>
                </button>

                <button 
                  onClick={() => setLoginTarget('admin')}
                  className="group bg-white dark:bg-slate-900 p-8 rounded-3xl shadow-xl hover:shadow-2xl border-2 border-transparent hover:border-blue-500 transition-all flex flex-col items-center text-center space-y-4 active:scale-[0.98]"
                >
                  <div className="w-20 h-20 bg-blue-50 dark:bg-blue-900/30 rounded-2xl flex items-center justify-center group-hover:bg-blue-600 group-hover:text-white transition-all">
                    <ShieldCheck className="w-10 h-10 text-blue-600 group-hover:text-white" />
                  </div>
                  <div>
                    <h3 className="text-xl font-bold dark:text-white">Área Admin</h3>
                    <p className="text-xs text-gray-400 dark:text-slate-500 font-medium mt-1">Gestão de estoque, pedidos e equipe.</p>
                  </div>
                  <div className="flex items-center gap-1 text-blue-600 font-bold text-xs uppercase tracking-widest pt-2">
                    Gerenciar <ChevronRight className="w-4 h-4" />
                  </div>
                </button>
              </div>
            </div>
          ) : (
            <div className="w-full max-w-sm mt-8 sm:mt-12 animate-in fade-in slide-in-from-bottom-8 duration-500 px-4">
              <div className="bg-white dark:bg-slate-900 p-6 sm:p-8 rounded-3xl shadow-xl border border-gray-100 dark:border-slate-800 text-center relative">
                <button 
                  onClick={() => setLoginTarget(null)} 
                  className="absolute left-4 top-4 p-2 text-gray-400 hover:text-gray-600 transition-colors"
                >
                  <X className="w-4 h-4" />
                </button>

                <div className={`w-12 h-12 sm:w-16 sm:h-16 rounded-full flex items-center justify-center mx-auto mb-4 sm:mb-6 ${
                  loginTarget === 'admin' ? 'bg-blue-50 dark:bg-blue-900/30' : 'bg-emerald-50 dark:bg-emerald-900/30'
                }`}>
                  {loginTarget === 'admin' ? 
                    <ShieldCheck className="w-6 h-6 sm:w-8 sm:h-8 text-blue-600 dark:text-blue-400" /> : 
                    <Store className="w-6 h-6 sm:w-8 sm:h-8 text-emerald-600 dark:text-emerald-400" />
                  }
                </div>
                <h2 className="text-xl sm:text-2xl font-bold dark:text-white mb-2">
                  Acesso {loginTarget === 'admin' ? 'Administrador' : 'Vendedor'}
                </h2>
                <form onSubmit={handleLogin} className="space-y-4">
                  <div className="relative">
                    <KeyRound className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                    <input
                      autoFocus
                      type="password"
                      placeholder="Senha"
                      value={passwordInput}
                      onChange={(e) => setPasswordInput(e.target.value)}
                      className="w-full pl-12 pr-4 py-3.5 rounded-xl border border-gray-200 dark:border-slate-700 bg-white dark:bg-slate-800 outline-none transition-all dark:text-white"
                    />
                  </div>
                  {loginError && <p className="text-[10px] text-red-500 font-bold uppercase">Senha incorreta!</p>}
                  <button type="submit" className="w-full bg-blue-600 text-white font-bold py-3.5 rounded-xl transition-all flex items-center justify-center gap-2">
                    Entrar <ArrowRight className="w-5 h-5" />
                  </button>
                </form>
              </div>
            </div>
          )
        ) : (
          activeTab === 'user' ? (
            <UserPortal 
              products={appState.products} 
              requests={appState.requests}
              vendedores={appState.vendedores}
              whatsappConfig={appState.whatsappConfig}
              onSubmitRequest={handleSubmitRequest}
            />
          ) : (
            <AdminPortal 
              appState={appState}
              onUploadData={handleUploadData}
              onAddVendedor={handleAddVendedor}
              onRemoveVendedor={handleRemoveVendedor}
              onUpdateWhatsApp={handleUpdateWhatsApp}
              onUpdateRequestStatus={handleUpdateRequestStatus}
              onClearRequests={handleClearRequests}
            />
          )
        )}
      </main>
    </div>
  );
};

