import React, { useState, useEffect } from 'react';
import { Upload, ListChecks, Database, FileText, CheckCircle, XCircle, Trash2, Users, Download, UserPlus, X, Link2, Copy, Check, AlertCircle, RefreshCw, Globe } from 'lucide-react';
import { Product, StockRequest, AppState, WhatsAppConfig } from '../types';
import { StatsCard } from './StatsCard';

interface AdminPortalProps {
  appState: AppState;
  onUploadData: (newProducts: Product[]) => void;
  onAddVendedor: (name: string) => void;
  onRemoveVendedor: (name: string) => void;
  onUpdateWhatsApp: (config: WhatsAppConfig) => void;
  onUpdateRequestStatus: (requestId: string, status: StockRequest['status']) => void;
  onClearRequests: () => void;
}

export const AdminPortal: React.FC<AdminPortalProps> = ({ 
  appState, 
  onUploadData, 
  onAddVendedor,
  onRemoveVendedor,
  onUpdateWhatsApp,
  onUpdateRequestStatus,
  onClearRequests
}) => {
  const [uploadStatus, setUploadStatus] = useState<{message: string, type: 'success' | 'error' | 'info'} | null>(null);
  const [newVendedor, setNewVendedor] = useState('');
  const [copiedLink, setCopiedLink] = useState<'admin' | 'vendedor' | null>(null);
  const [syncUrl, setSyncUrl] = useState(() => localStorage.getItem('marsil_sync_url') || '');
  const [isSyncing, setIsSyncing] = useState(false);

  const processCSVText = (text: string) => {
    const lines = text.split(/\r?\n/).filter(line => line.trim() !== '');
    if (lines.length < 2) throw new Error("Arquivo vazio ou sem dados.");

    const header = lines[0].toLowerCase();
    const separator = header.includes(';') ? ';' : ',';
    const columns = lines[0].split(separator).map(c => c.trim().toLowerCase());

    const idx = {
      fornecedor: columns.findIndex(c => c.includes('fornecedor')),
      codigo: columns.findIndex(c => c.includes('código') || c.includes('codigo')),
      situacao: columns.findIndex(c => c.includes('situação') || c.includes('situacao')),
      comprador: columns.findIndex(c => c.includes('comprador')),
      produto: columns.findIndex(c => c.includes('produto') || c.includes('descrição') || c.includes('item')),
      marsil: columns.findIndex(c => c.includes('marsil') || c.includes('estoque sp')),
      boraceia: columns.findIndex(c => c.includes('boraceia') || c.includes('estoque bor')),
    };

    return lines.slice(1).map((row, i) => {
      const cols = row.split(separator).map(c => c.trim().replace(/"/g, ''));
      return {
        id: `p-${i}-${Date.now()}`,
        fornecedor: cols[idx.fornecedor] || 'N/D',
        codigo: cols[idx.codigo] || '0',
        situacao: cols[idx.situacao] || '',
        comprador: cols[idx.comprador] || '',
        produto: cols[idx.produto] || 'Produto sem nome',
        sabor: '',
        embalagem: '',
        estoqueMarsil: parseInt(cols[idx.marsil]) || 0,
        estoqueBoraceia: parseInt(cols[idx.boraceia]) || 0,
      };
    });
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setUploadStatus({ message: 'Processando planilha...', type: 'info' });
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const products = processCSVText(event.target?.result as string);
        onUploadData(products);
        setUploadStatus({ message: `Sucesso! ${products.length} itens carregados.`, type: 'success' });
        setTimeout(() => setUploadStatus(null), 5000);
      } catch (err) {
        setUploadStatus({ message: 'Erro ao ler CSV.', type: 'error' });
      }
    };
    reader.readAsText(file, 'UTF-8');
  };

  const handleSyncFromUrl = async () => {
    if (!syncUrl) return;
    setIsSyncing(true);
    setUploadStatus({ message: 'Sincronizando com a nuvem...', type: 'info' });

    try {
      localStorage.setItem('marsil_sync_url', syncUrl);
      const response = await fetch(syncUrl);
      if (!response.ok) throw new Error("Não foi possível acessar a URL");
      const text = await response.text();
      const products = processCSVText(text);
      onUploadData(products);
      setUploadStatus({ message: `Sincronizado! ${products.length} itens atualizados via link.`, type: 'success' });
    } catch (err) {
      setUploadStatus({ message: 'Erro na sincronização. Verifique se o link é um CSV público.', type: 'error' });
    } finally {
      setIsSyncing(false);
      setTimeout(() => setUploadStatus(null), 5000);
    }
  };

  const handleAddVendedor = (e: React.FormEvent) => {
    e.preventDefault();
    if (newVendedor.trim()) {
      onAddVendedor(newVendedor.trim());
      setNewVendedor('');
    }
  };

  const copyLink = (type: 'admin' | 'vendedor') => {
    const baseUrl = window.location.origin + window.location.pathname;
    const url = `${baseUrl}?portal=${type}`;
    navigator.clipboard.writeText(url).then(() => {
      setCopiedLink(type);
      setTimeout(() => setCopiedLink(null), 2000);
    });
  };

  return (
    <div className="space-y-6 sm:space-y-8 max-w-6xl w-full mx-auto px-2 sm:px-0 pb-12">
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
        <StatsCard label="Produtos Ativos" value={appState.products.length} icon={<Database className="w-4 h-4 sm:w-5 sm:h-5" />} color="bg-blue-600" />
        <StatsCard label="Vendedores" value={appState.vendedores.length} icon={<Users className="w-4 h-4 sm:w-5 sm:h-5" />} color="bg-emerald-600" />
        <StatsCard label="Pedidos Pendentes" value={appState.requests.filter(r => r.status === 'Pendente').length} icon={<ListChecks className="w-4 h-4 sm:w-5 sm:h-5" />} color="bg-amber-600" />
        <StatsCard label="Total Histórico" value={appState.requests.length} icon={<FileText className="w-4 h-4 sm:w-5 sm:h-5" />} color="bg-purple-600" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 sm:gap-8">
        <div className="lg:col-span-1 space-y-6">

          {/* Nova Seção de Sincronização por Link */}
          <div className="bg-white dark:bg-slate-900 p-5 sm:p-6 rounded-2xl shadow-md border-2 border-emerald-100 dark:border-emerald-900/30">
            <h3 className="text-base sm:text-lg font-bold mb-4 flex items-center gap-2 dark:text-white">
              <Globe className="w-5 h-5 text-emerald-600" /> Sincronizar Google/OneDrive
            </h3>
            <p className="text-[10px] text-gray-400 font-bold uppercase mb-4 leading-tight">
              Cole o link de "Publicar na Web" (formato CSV) da sua planilha para atualizar remotamente.
            </p>
            <div className="space-y-3">
              <input 
                type="url" 
                placeholder="https://docs.google.com/spreadsheets/..." 
                className="w-full px-4 py-3 rounded-xl border border-gray-100 dark:border-slate-800 bg-gray-50 dark:bg-slate-800 dark:text-white text-xs outline-none focus:ring-2 focus:ring-emerald-500"
                value={syncUrl}
                onChange={(e) => setSyncUrl(e.target.value)}
              />
              <button 
                onClick={handleSyncFromUrl}
                disabled={isSyncing || !syncUrl}
                className="w-full bg-emerald-600 hover:bg-emerald-700 disabled:opacity-50 text-white font-bold py-3 rounded-xl flex items-center justify-center gap-2 transition-all active:scale-95 shadow-lg shadow-emerald-100 dark:shadow-none"
              >
                {isSyncing ? <RefreshCw className="w-4 h-4 animate-spin" /> : <RefreshCw className="w-4 h-4" />}
                <span className="text-xs uppercase">Sincronizar Agora</span>
              </button>
            </div>
          </div>

          <div className="bg-white dark:bg-slate-900 p-5 sm:p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800">
            <h3 className="text-base sm:text-lg font-bold mb-4 flex items-center gap-2 dark:text-white">
              <Upload className="w-5 h-5 text-blue-600" /> Upload Manual
            </h3>
            <label className="border-2 border-dashed rounded-2xl p-6 flex flex-col items-center justify-center cursor-pointer border-blue-200 dark:border-slate-800 hover:border-blue-500 hover:bg-blue-50 dark:hover:bg-slate-800/30 transition-all bg-gray-50/50 dark:bg-slate-800/30 group">
              <Upload className="w-8 h-8 text-blue-300 group-hover:text-blue-500 mb-2 transition-colors" />
              <p className="text-[10px] text-blue-600 dark:text-blue-400 font-black uppercase tracking-widest text-center">Selecionar CSV Local</p>
              <input type="file" className="hidden" accept=".csv" onChange={handleFileUpload} />
            </label>

            {uploadStatus && (
              <div className={`mt-4 p-3 rounded-xl flex items-center gap-3 animate-in fade-in slide-in-from-top-2 ${
                uploadStatus.type === 'success' ? 'bg-emerald-50 text-emerald-700 border border-emerald-100' : 
                uploadStatus.type === 'error' ? 'bg-red-50 text-red-700 border border-red-100' : 
                'bg-blue-50 text-blue-700 border border-blue-100'
              }`}>
                {uploadStatus.type === 'success' ? <CheckCircle className="w-4 h-4 shrink-0" /> : <AlertCircle className="w-4 h-4 shrink-0" />}
                <p className="text-[10px] font-bold leading-tight">{uploadStatus.message}</p>
              </div>
            )}
          </div>

          <div className="bg-white dark:bg-slate-900 p-5 sm:p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800">
            <h3 className="text-base sm:text-lg font-bold mb-5 flex items-center gap-2 dark:text-white">
              <Link2 className="w-5 h-5 text-blue-500" /> Links de Acesso
            </h3>
            <div className="space-y-3">
              <button onClick={() => copyLink('vendedor')} className="w-full flex items-center justify-between p-3 bg-gray-50 dark:bg-slate-800/50 rounded-xl hover:bg-gray-100 dark:hover:bg-slate-800 transition-all group">
                <div className="text-left">
                  <p className="text-xs font-bold dark:text-white">Link Vendedor</p>
                  <p className="text-[9px] text-gray-400 uppercase font-black">Enviar para a equipe</p>
                </div>
                {copiedLink === 'vendedor' ? <Check className="w-4 h-4 text-emerald-500" /> : <Copy className="w-4 h-4 text-gray-400 group-hover:text-blue-500" />}
              </button>
            </div>
          </div>
        </div>

        <div className="lg:col-span-2">
          <div className="bg-white dark:bg-slate-900 rounded-3xl shadow-sm border border-gray-100 dark:border-slate-800 overflow-hidden flex flex-col h-full">
            <div className="p-5 border-b border-gray-50 dark:border-slate-800 flex justify-between items-center sticky top-0 bg-white dark:bg-slate-900 z-10">
              <h3 className="text-base font-bold dark:text-white">Pedidos Recebidos</h3>
              {appState.requests.length > 0 && <button onClick={onClearRequests} className="px-3 py-1.5 text-[9px] font-black text-red-500 bg-red-50 dark:bg-red-900/20 rounded-lg uppercase">Limpar Histórico</button>}
            </div>

            <div className="overflow-x-auto custom-scrollbar">
              <table className="w-full min-w-[500px]">
                <thead className="bg-gray-50 dark:bg-slate-800/80 text-left border-b border-gray-100 dark:border-slate-800">
                  <tr>
                    <th className="px-6 py-4 text-[9px] font-black text-gray-400 uppercase tracking-widest">Vendedor</th>
                    <th className="px-6 py-4 text-[9px] font-black text-gray-400 uppercase tracking-widest">Item</th>
                    <th className="px-6 py-4 text-center text-[9px] font-black text-gray-400 uppercase tracking-widest">Qtd</th>
                    <th className="px-6 py-4 text-right text-[9px] font-black text-gray-400 uppercase tracking-widest">Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50 dark:divide-slate-800">
                  {appState.requests.length === 0 ? (
                    <tr>
                      <td colSpan={4} className="px-6 py-12 text-center">
                        <p className="text-xs text-gray-300 dark:text-slate-600 font-bold uppercase">Nenhum pedido recente</p>
                      </td>
                    </tr>
                  ) : (
                    appState.requests.map(req => (
                      <tr key={req.id} className="hover:bg-gray-50 dark:hover:bg-slate-800/30 transition-colors">
                        <td className="px-6 py-4">
                          <p className="text-xs font-bold dark:text-slate-200">{req.solicitante}</p>
                          <p className="text-[8px] text-gray-400 font-bold mt-1 uppercase">{new Date(req.dataSolicitacao).toLocaleDateString()}</p>
                        </td>
                        <td className="px-6 py-4">
                          <p className="text-xs font-semibold dark:text-slate-300 line-clamp-1">{req.productName}</p>
                          <p className="text-[9px] text-blue-500 font-bold mt-0.5">{req.productCode}</p>
                        </td>
                        <td className="px-6 py-4 text-center">
                          <span className="text-xs font-black dark:text-slate-100">{req.quantidade}</span>
                          <span className="text-[8px] text-gray-400 block font-bold uppercase">{req.unidade}</span>
                        </td>
                        <td className="px-6 py-4 text-right">
                          <div className="flex justify-end gap-1">
                            {req.status === 'Pendente' ? (
                              <>
                                <button onClick={() => onUpdateRequestStatus(req.id, 'Aprovado')} className="p-1.5 text-emerald-500 hover:bg-emerald-50 dark:hover:bg-emerald-900/20 rounded-lg"><CheckCircle className="w-4 h-4" /></button>
                                <button onClick={() => onUpdateRequestStatus(req.id, 'Recusado')} className="p-1.5 text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg"><XCircle className="w-4 h-4" /></button>
                              </>
                            ) : (
                              <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded ${req.status === 'Aprovado' ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-600'}`}>
                                {req.status}
                              </span>
                            )}
                          </div>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

