import { LayoutDashboard, ShieldCheck, Sun, Moon, KeyRound, LogOut, ChevronRight, Store, X, Loader2 } from 'lucide-react';

const THEME_KEY = 'marsil_theme_pref';
const AUTH_KEY = 'marsil_auth_role';
const PRODUCTS_KEY = 'marsil_local_products';
const VENDEDORES_KEY = 'marsil_vendedores_list';
const REQUESTS_KEY = 'marsil_requests_history';

const PASSWORDS = {
  VENDOR: '@marsil2026',
  ADMIN: '@adminMarsil2026'
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'user' | 'admin'>('user');
  const [authRole, setAuthRole] = useState<'none' | 'vendor' | 'admin'>(() => {
    return (localStorage.getItem(AUTH_KEY) as any) || 'none';
  });

  const [loginTarget, setLoginTarget] = useState<'vendedor' | 'admin' | null>(null);
  const [passwordInput, setPasswordInput] = useState('');
  const [loginError, setLoginError] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  const [isDarkMode, setIsDarkMode] = useState(() => {
    const savedTheme = localStorage.getItem(THEME_KEY);
    return savedTheme === 'dark';
  });

  const [appState, setAppState] = useState<AppState>(() => {
    const savedProducts = localStorage.getItem(PRODUCTS_KEY);
    const savedVendedores = localStorage.getItem(VENDEDORES_KEY);
    const savedRequests = localStorage.getItem(REQUESTS_KEY);

    return { 
      products: savedProducts ? JSON.parse(savedProducts) : [], 
      requests: savedRequests ? JSON.parse(savedRequests) : [], 
      vendedores: savedVendedores ? JSON.parse(savedVendedores) : [],
      whatsappConfig: { enabled: true, phoneNumber: '5511999999999' } // Altere para seu número
    };
  });

  useEffect(() => {
    // Simula um carregamento inicial para UX
    const timer = setTimeout(() => setIsLoading(false), 800);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    localStorage.setItem(AUTH_KEY, authRole);
  }, [authRole]);

  useEffect(() => {
    localStorage.setItem(PRODUCTS_KEY, JSON.stringify(appState.products));
    localStorage.setItem(VENDEDORES_KEY, JSON.stringify(appState.vendedores));
    localStorage.setItem(REQUESTS_KEY, JSON.stringify(appState.requests));
  }, [appState]);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem(THEME_KEY, 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem(THEME_KEY, 'light');
    }
  }, [isDarkMode]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const requiredPass = loginTarget === 'admin' ? PASSWORDS.ADMIN : PASSWORDS.VENDOR;

    if (passwordInput === requiredPass) {
      const role = loginTarget === 'admin' ? 'admin' : 'vendor';
      setAuthRole(role);
      setActiveTab(loginTarget === 'admin' ? 'admin' : 'user');
      setLoginError(false);
      setLoginTarget(null);
    } else {
      setLoginError(true);
      setTimeout(() => setLoginError(false), 3000);
    }
    setPasswordInput('');
  };

  const handleLogout = () => {
    setAuthRole('none');
    setLoginTarget(null);
    setPasswordInput('');
    setActiveTab('user');
    localStorage.removeItem(AUTH_KEY);
  };

  const handleUploadData = (newProducts: Product[]) => {
    setAppState(prev => ({ ...prev, products: newProducts }));
  };

  const handleAddVendedor = (name: string) => {
    if (!appState.vendedores.includes(name)) {
      setAppState(prev => ({ ...prev, vendedores: [...prev.vendedores, name].sort() }));
    }
  };

  const handleRemoveVendedor = (name: string) => {
    setAppState(prev => ({ ...prev, vendedores: prev.vendedores.filter(v => v !== name) }));
  };

  const handleUpdateWhatsApp = (config: WhatsAppConfig) => {
    setAppState(prev => ({ ...prev, whatsappConfig: config }));
  };

  const handleSubmitRequest = (req: Omit<StockRequest, 'id' | 'dataSolicitacao' | 'status'>) => {
    const newRequest: StockRequest = {
      ...req,
      id: Math.random().toString(36).substr(2, 9),
      dataSolicitacao: new Date().toISOString(),
      status: 'Pendente'
    };

    setAppState(prev => ({
      ...prev,
      requests: [newRequest, ...prev.requests].slice(0, 50) // Mantém apenas os últimos 50 locais
    }));
  };

  const handleUpdateRequestStatus = (requestId: string, status: StockRequest['status']) => {
    setAppState(prev => ({
      ...prev,
      requests: prev.requests.map(r => r.id === requestId ? { ...r, status } : r)
    }));
  };

  const handleClearRequests = () => {
    if (window.confirm('Limpar histórico local de pedidos?')) {
      setAppState(prev => ({ ...prev, requests: [] }));
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-slate-950">
        <div className="flex flex-col items-center gap-4">
          <Loader2 className="w-8 h-8 text-blue-600 animate-spin" />
          <p className="text-[10px] font-black uppercase tracking-widest text-gray-400">Marsil Boracéia</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-slate-950 text-gray-900 dark:text-slate-100 transition-colors duration-300">
      <header className="bg-white dark:bg-slate-900 border-b border-gray-200 dark:border-slate-800 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-3">
              <div className="bg-blue-600 p-2 rounded-xl shrink-0">
                <LayoutDashboard className="w-5 h-5 text-white" />
              </div>
              <div className="flex flex-col">
                <h1 className="text-lg font-black tracking-tight dark:text-white">Marsil & Boracéia</h1>
                <p className="text-[9px] text-gray-400 font-bold uppercase tracking-tighter">Estoque Local</p>
              </div>
            </div>

            <div className="flex items-center gap-4">
              <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 text-gray-400 hover:text-blue-500 transition-colors">
                {isDarkMode ? <Sun className="w-4 h-4" /> : <Moon className="w-4 h-4" />}
              </button>

              {authRole !== 'none' && (
                <div className="flex items-center gap-2">
                  <div className="bg-gray-100 dark:bg-slate-800 p-1 rounded-xl flex">
                    <button onClick={() => setActiveTab('user')} className={`px-3 py-1.5 text-[10px] font-black rounded-lg uppercase ${activeTab === 'user' ? 'bg-white dark:bg-slate-700 text-blue-600 shadow-sm' : 'text-gray-400'}`}>Consulta</button>
                    {authRole === 'admin' && (
                      <button onClick={() => setActiveTab('admin')} className={`px-3 py-1.5 text-[10px] font-black rounded-lg uppercase ${activeTab === 'admin' ? 'bg-white dark:bg-slate-700 text-blue-600 shadow-sm' : 'text-gray-400'}`}>Admin</button>
                    )}
                  </div>
                  <button onClick={handleLogout} className="p-2 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-xl transition-colors"><LogOut className="w-4 h-4" /></button>
                </div>
              )}
            </div>
          </div>
        </div>
      </header>

      <main className="flex-grow p-4 sm:p-8 flex flex-col items-center">
        {authRole === 'none' ? (
          !loginTarget ? (
            <div className="w-full max-w-2xl mt-12 animate-in fade-in zoom-in-95 duration-500 space-y-8">
              <div className="text-center space-y-2">
                <h2 className="text-4xl font-black dark:text-white tracking-tight">Painel de Estoque</h2>
                <p className="text-gray-500 dark:text-slate-400 text-sm">Acesse para consultar itens disponíveis.</p>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                <button onClick={() => setLoginTarget('vendedor')} className="group bg-white dark:bg-slate-900 p-8 rounded-3xl shadow-xl hover:shadow-2xl border-2 border-transparent hover:border-emerald-500 transition-all flex flex-col items-center space-y-4">
                  <div className="w-16 h-16 bg-emerald-50 dark:bg-emerald-900/30 rounded-2xl flex items-center justify-center group-hover:bg-emerald-600 group-hover:text-white transition-all">
                    <Store className="w-8 h-8 text-emerald-600 group-hover:text-white" />
                  </div>
                  <h3 className="text-xl font-bold dark:text-white">Equipe Vendas</h3>
                  <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Entrar <ChevronRight className="w-4 h-4 inline" /></p>
                </button>

                <button onClick={() => setLoginTarget('admin')} className="group bg-white dark:bg-slate-900 p-8 rounded-3xl shadow-xl hover:shadow-2xl border-2 border-transparent hover:border-blue-500 transition-all flex flex-col items-center space-y-4">
                  <div className="w-16 h-16 bg-blue-50 dark:bg-blue-900/30 rounded-2xl flex items-center justify-center group-hover:bg-blue-600 group-hover:text-white transition-all">
                    <ShieldCheck className="w-8 h-8 text-blue-600 group-hover:text-white" />
                  </div>
                  <h3 className="text-xl font-bold dark:text-white">Gestão / TI</h3>
                  <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest">Configurações <ChevronRight className="w-4 h-4 inline" /></p>
                </button>
              </div>
            </div>
          ) : (
            <div className="w-full max-w-sm mt-12 animate-in slide-in-from-bottom-8 duration-500 px-4">
              <div className="bg-white dark:bg-slate-900 p-8 rounded-3xl shadow-2xl border border-gray-100 dark:border-slate-800 text-center relative">
                <button onClick={() => setLoginTarget(null)} className="absolute left-4 top-4 p-2 text-gray-400 hover:text-gray-600 transition-colors"><X className="w-4 h-4" /></button>
                <div className={`w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-6 ${loginTarget === 'admin' ? 'bg-blue-50 dark:bg-blue-900/30' : 'bg-emerald-50 dark:bg-emerald-900/30'}`}>
                  {loginTarget === 'admin' ? <ShieldCheck className="w-8 h-8 text-blue-600" /> : <Store className="w-8 h-8 text-emerald-600" />}
                </div>
                <h2 className="text-2xl font-black dark:text-white mb-6">Acesso</h2>
                <form onSubmit={handleLogin} className="space-y-4">
                  <div className="relative">
                    <KeyRound className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                    <input autoFocus type="password" placeholder="Senha de Acesso" value={passwordInput} onChange={(e) => setPasswordInput(e.target.value)} className="w-full pl-12 pr-4 py-4 rounded-2xl border border-gray-200 dark:border-slate-700 bg-white dark:bg-slate-800 outline-none transition-all dark:text-white font-bold" />
                  </div>
                  {loginError && <p className="text-[10px] text-red-500 font-bold uppercase">Senha incorreta!</p>}
                  <button type="submit" className="w-full bg-blue-600 text-white font-black py-4 rounded-2xl shadow-lg active:scale-95 transition-all uppercase tracking-widest text-xs">Entrar</button>
                </form>
              </div>
            </div>
          )
        ) : (
          activeTab === 'user' ? (
            <UserPortal products={appState.products} requests={appState.requests} vendedores={appState.vendedores} whatsappConfig={appState.whatsappConfig} onSubmitRequest={handleSubmitRequest} />
          ) : (
            <AdminPortal appState={appState} onUploadData={handleUploadData} onAddVendedor={handleAddVendedor} onRemoveVendedor={handleRemoveVendedor} onUpdateWhatsApp={handleUpdateWhatsApp} onUpdateRequestStatus={handleUpdateRequestStatus} onClearRequests={handleClearRequests} />
          )
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Upload, Database, FileText, CheckCircle, XCircle, Users, UserPlus, X, Globe, ArrowDownToLine, RefreshCw, AlertCircle, Phone } from 'lucide-react';
import { Product, StockRequest, AppState, WhatsAppConfig } from '../types';
import { StatsCard } from './StatsCard';
import Papa from 'papaparse';

interface AdminPortalProps {
  appState: AppState;
  onUploadData: (newProducts: Product[]) => void;
  onAddVendedor: (name: string) => void;
  onRemoveVendedor: (name: string) => void;
  onUpdateWhatsApp: (config: WhatsAppConfig) => void;
  onUpdateRequestStatus: (requestId: string, status: StockRequest['status']) => void;
  onClearRequests: () => void;
}

export const AdminPortal: React.FC<AdminPortalProps> = ({ 
  appState, 
  onUploadData, 
  onAddVendedor,
  onRemoveVendedor,
  onUpdateWhatsApp,
  onUpdateRequestStatus,
  onClearRequests
}) => {
  const [uploadStatus, setUploadStatus] = useState<{message: string, type: 'success' | 'error' | 'info'} | null>(null);
  const [newVendedor, setNewVendedor] = useState('');
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncUrl, setSyncUrl] = useState(() => localStorage.getItem('marsil_sync_url') || '');
  const [waNumber, setWaNumber] = useState(appState.whatsappConfig.phoneNumber);

  const processData = (results: any) => {
    const data = results.data;
    if (data.length < 1) throw new Error("Arquivo sem dados.");

    const findCol = (terms: string[]) => {
      return Object.keys(data[0]).find(key => 
        terms.some(term => key.toLowerCase().includes(term))
      );
    };

    const colFornecedor = findCol(['fornecedor']);
    const colCodigo = findCol(['código', 'codigo']);
    const colProduto = findCol(['produto', 'descrição', 'item']);
    const colMarsil = findCol(['marsil', 'estoque sp', 'estoque_sp']);
    const colBoraceia = findCol(['boraceia', 'boracéia', 'estoque_bor']);

    if (!colCodigo || !colProduto) {
      throw new Error("Colunas 'Código' ou 'Produto' não encontradas.");
    }

    const products: Product[] = data.map((row: any, i: number) => ({
      id: `p-${i}-${Date.now()}`,
      fornecedor: colFornecedor ? row[colFornecedor] : 'N/D',
      codigo: String(row[colCodigo] || '0'),
      situacao: row['Situação'] || row['situacao'] || '',
      comprador: row['Comprador'] || row['comprador'] || '',
      produto: row[colProduto] || 'Sem nome',
      sabor: '',
      embalagem: '',
      estoqueMarsil: parseInt(row[colMarsil]) || 0,
      estoqueBoraceia: parseInt(row[colBoraceia]) || 0,
    })).filter((p: any) => p.produto !== 'Sem nome');

    onUploadData(products);
    return products.length;
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploadStatus({ message: 'Processando CSV...', type: 'info' });
    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        try {
          const count = processData(results);
          setUploadStatus({ message: `Sucesso! ${count} itens carregados localmente.`, type: 'success' });
          setTimeout(() => setUploadStatus(null), 5000);
        } catch (err: any) {
          setUploadStatus({ message: err.message, type: 'error' });
        }
      }
    });
  };

  const handleSyncFromUrl = async () => {
    if (!syncUrl) return;
    setIsSyncing(true);
    setUploadStatus({ message: 'Sincronizando com a nuvem...', type: 'info' });
    localStorage.setItem('marsil_sync_url', syncUrl);

    Papa.parse(syncUrl, {
      download: true,
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        try {
          const count = processData(results);
          setUploadStatus({ message: `Sincronizado! ${count} itens atualizados via link.`, type: 'success' });
          setIsSyncing(false);
          setTimeout(() => setUploadStatus(null), 5000);
        } catch (err: any) {
          setUploadStatus({ message: 'Erro: Verifique se o link CSV está correto e público.', type: 'error' });
          setIsSyncing(false);
        }
      },
      error: () => {
        setUploadStatus({ message: 'Erro de conexão com o link informado.', type: 'error' });
        setIsSyncing(false);
      }
    });
  };

  const updateWhatsApp = () => {
    onUpdateWhatsApp({ enabled: true, phoneNumber: waNumber });
    setUploadStatus({ message: 'Configuração salva!', type: 'success' });
    setTimeout(() => setUploadStatus(null), 3000);
  };

  return (
    <div className="space-y-6 sm:space-y-8 max-w-6xl w-full mx-auto px-2 sm:px-0 pb-12 animate-in fade-in">
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
        <StatsCard label="Itens Carregados" value={appState.products.length} icon={<Database className="w-4 h-4" />} color="bg-blue-600" />
        <StatsCard label="Equipe" value={appState.vendedores.length} icon={<Users className="w-4 h-4" />} color="bg-emerald-600" />
        <StatsCard label="Pendentes (Local)" value={appState.requests.filter(r => r.status === 'Pendente').length} icon={<RefreshCw className="w-4 h-4" />} color="bg-amber-600" />
        <StatsCard label="Histórico Local" value={appState.requests.length} icon={<FileText className="w-4 h-4" />} color="bg-purple-600" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 sm:gap-8">
        <div className="lg:col-span-1 space-y-6">

          <div className="bg-white dark:bg-slate-900 p-5 rounded-3xl shadow-xl border-2 border-emerald-50 dark:border-emerald-900/20">
            <h3 className="text-sm font-black mb-4 flex items-center gap-2 dark:text-white uppercase tracking-wider">
              <Globe className="w-4 h-4 text-emerald-600" /> Sincronizar Google Sheets
            </h3>
            <p className="text-[10px] text-gray-400 font-bold uppercase mb-4 leading-tight">
              Publique sua planilha como CSV e cole o link aqui.
            </p>
            <div className="space-y-3">
              <input 
                type="url" 
                placeholder="Link do CSV Público..." 
                className="w-full px-4 py-3 rounded-xl border border-gray-100 dark:border-slate-800 bg-gray-50 dark:bg-slate-800 dark:text-white text-xs outline-none focus:ring-2 focus:ring-emerald-500"
                value={syncUrl}
                onChange={(e) => setSyncUrl(e.target.value)}
              />
              <button 
                onClick={handleSyncFromUrl}
                disabled={isSyncing || !syncUrl}
                className="w-full bg-emerald-600 hover:bg-emerald-700 disabled:opacity-50 text-white font-bold py-3.5 rounded-xl flex items-center justify-center gap-2 transition-all"
              >
                {isSyncing ? <RefreshCw className="w-4 h-4 animate-spin" /> : <RefreshCw className="w-4 h-4" />}
                <span className="text-[10px] uppercase font-black">Sincronizar Dados</span>
              </button>
            </div>
          </div>

          <div className="bg-white dark:bg-slate-900 p-5 rounded-3xl shadow-sm border border-gray-100 dark:border-slate-800">
            <h3 className="text-sm font-black mb-4 flex items-center gap-2 dark:text-white uppercase tracking-wider">
              <ArrowDownToLine className="w-4 h-4 text-blue-600" /> Upload CSV Local
            </h3>
            <label className="border-2 border-dashed rounded-2xl p-6 flex flex-col items-center justify-center cursor-pointer border-blue-100 dark:border-slate-800 hover:border-blue-500 hover:bg-blue-50 dark:hover:bg-slate-800/20 group">
              <Upload className="w-6 h-6 text-blue-300 group-hover:text-blue-500 mb-2 transition-colors" />
              <p className="text-[9px] text-blue-600 font-black uppercase tracking-widest text-center">Selecionar do PC</p>
              <input type="file" className="hidden" accept=".csv" onChange={handleFileUpload} />
            </label>

            {uploadStatus && (
              <div className={`mt-4 p-3 rounded-xl flex items-center gap-3 ${
                uploadStatus.type === 'success' ? 'bg-emerald-50 text-emerald-700' : 
                uploadStatus.type === 'error' ? 'bg-red-50 text-red-700' : 'bg-blue-50 text-blue-700'
              }`}>
                {uploadStatus.type === 'success' ? <CheckCircle className="w-4 h-4" /> : <AlertCircle className="w-4 h-4" />}
                <p className="text-[10px] font-bold">{uploadStatus.message}</p>
              </div>
            )}
          </div>

          <div className="bg-white dark:bg-slate-900 p-5 rounded-3xl shadow-sm border border-gray-100 dark:border-slate-800">
            <h3 className="text-sm font-black mb-4 flex items-center gap-2 dark:text-white uppercase tracking-wider">
              <Phone className="w-4 h-4 text-blue-500" /> WhatsApp Destino
            </h3>
            <div className="space-y-3">
              <input 
                type="text" 
                placeholder="Ex: 5511999999999" 
                className="w-full px-4 py-3 rounded-xl border border-gray-100 dark:border-slate-800 bg-gray-50 dark:bg-slate-800 dark:text-white text-xs outline-none"
                value={waNumber}
                onChange={(e) => setWaNumber(e.target.value)}
              />
              <button onClick={updateWhatsApp} className="w-full bg-blue-600 text-white font-bold py-2.5 rounded-xl text-[10px] uppercase">Salvar Número</button>
            </div>
          </div>
        </div>

        <div className="lg:col-span-2">
          <div className="bg-white dark:bg-slate-900 rounded-3xl shadow-xl border border-gray-100 dark:border-slate-800 overflow-hidden">
            <div className="p-5 border-b border-gray-50 dark:border-slate-800 flex justify-between items-center">
              <h3 className="text-sm font-black dark:text-white uppercase tracking-wider">Vendedores Ativos</h3>
            </div>
            <div className="p-5 space-y-4">
              <form onSubmit={(e) => { e.preventDefault(); if (newVendedor) { onAddVendedor(newVendedor); setNewVendedor(''); } }} className="flex gap-2">
                <input type="text" placeholder="Nome do Vendedor" value={newVendedor} onChange={e => setNewVendedor(e.target.value)} className="flex-grow px-4 py-3 text-xs rounded-xl bg-gray-50 dark:bg-slate-800 border-none outline-none dark:text-white" />
                <button type="submit" className="px-4 bg-emerald-600 text-white rounded-xl"><UserPlus className="w-4 h-4" /></button>
              </form>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 max-h-64 overflow-y-auto custom-scrollbar">
                {appState.vendedores.map(v => (
                  <div key={v} className="flex items-center justify-between p-3 bg-gray-50 dark:bg-slate-800/40 rounded-xl group border border-transparent hover:border-blue-100">
                    <span className="text-xs font-bold dark:text-slate-300 uppercase tracking-tighter">{v}</span>
                    <button onClick={() => onRemoveVendedor(v)} className="text-gray-400 hover:text-red-500"><X className="w-4 h-4" /></button>
                  </div>
                ))}
              </div>
            </div>
          </div>

          <div className="mt-6 bg-white dark:bg-slate-900 rounded-3xl shadow-xl border border-gray-100 dark:border-slate-800 overflow-hidden">
            <div className="p-5 border-b border-gray-50 dark:border-slate-800 flex justify-between items-center">
              <h3 className="text-sm font-black dark:text-white uppercase tracking-wider">Histórico de Pedidos (Neste Navegador)</h3>
              {appState.requests.length > 0 && <button onClick={onClearRequests} className="text-[9px] font-black text-red-500 uppercase">Limpar</button>}
            </div>
            <div className="p-4 text-center">
              <p className="text-[10px] text-gray-400 font-bold uppercase py-10">
                {appState.requests.length === 0 ? "Nenhum pedido realizado localmente." : `${appState.requests.length} pedidos registrados.`}
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { UserPortal } from './components/UserPortal';
import { AdminPortal } from './components/AdminPortal';
import { AppState, Product, StockRequest, WhatsAppConfig } from './types';
import { LayoutDashboard, ShieldCheck, Sun, Moon, KeyRound, LogOut, ChevronRight, Store, X, Loader2, RefreshCw } from 'lucide-react';
import Papa from 'papaparse';

const THEME_KEY = 'marsil_theme_pref';
const AUTH_KEY = 'marsil_auth_role';
const PRODUCTS_KEY = 'marsil_local_products';
const VENDEDORES_KEY = 'marsil_vendedores_list';
const REQUESTS_KEY = 'marsil_requests_history';
const SYNC_URL_KEY = 'marsil_sync_url';

const PASSWORDS = {
  VENDOR: '@marsil2026',
  ADMIN: '@adminMarsil2026'
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'user' | 'admin'>('user');
  const [authRole, setAuthRole] = useState<'none' | 'vendor' | 'admin'>(() => {
    return (localStorage.getItem(AUTH_KEY) as any) || 'none';
  });

  const [loginTarget, setLoginTarget] = useState<'vendedor' | 'admin' | null>(null);
  const [passwordInput, setPasswordInput] = useState('');
  const [loginError, setLoginError] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [syncMessage, setSyncMessage] = useState('');

  const [isDarkMode, setIsDarkMode] = useState(() => {
    const savedTheme = localStorage.getItem(THEME_KEY);
    return savedTheme === 'dark';
  });

  const [appState, setAppState] = useState<AppState>(() => {
    const savedProducts = localStorage.getItem(PRODUCTS_KEY);
    const savedVendedores = localStorage.getItem(VENDEDORES_KEY);
    const savedRequests = localStorage.getItem(REQUESTS_KEY);

    return { 
      products: savedProducts ? JSON.parse(savedProducts) : [], 
      requests: savedRequests ? JSON.parse(savedRequests) : [], 
      vendedores: savedVendedores ? JSON.parse(savedVendedores) : ['Vendedor 1', 'Vendedor 2'],
      whatsappConfig: { enabled: true, phoneNumber: '5511999999999' }
    };
  });

  // Efeito de Inicialização e Auto-Sync
  useEffect(() => {
    const initApp = async () => {
      // 1. Verificar se há link de sincronização na URL (?s=...)
      const params = new URLSearchParams(window.location.search);
      const urlSync = params.get('s');

      if (urlSync) {
        localStorage.setItem(SYNC_URL_KEY, urlSync);
        setSyncMessage('Configurando nova fonte de dados...');
      }

      const activeSyncUrl = localStorage.getItem(SYNC_URL_KEY);

      if (activeSyncUrl) {
        setSyncMessage('Sincronizando estoque...');
        Papa.parse(activeSyncUrl, {
          download: true,
          header: true,
          skipEmptyLines: true,
          complete: (results) => {
            if (results.data && results.data.length > 0) {
              const mapped = mapCSVToProducts(results.data);
              setAppState(prev => ({ ...prev, products: mapped }));
              localStorage.setItem(PRODUCTS_KEY, JSON.stringify(mapped));
              setSyncMessage('');
            }
            setIsLoading(false);
          },
          error: () => {
            console.error("Erro no auto-sync");
            setIsLoading(false);
          }
        });
      } else {
        setTimeout(() => setIsLoading(false), 800);
      }
    };

    initApp();
  }, []);

  const mapCSVToProducts = (data: any[]): Product[] => {
    return data.map((row: any, i: number) => {
      // Busca flexível de colunas
      const findValue = (keys: string[]) => {
        const foundKey = Object.keys(row).find(k => keys.some(s => k.toLowerCase().includes(s.toLowerCase())));
        return foundKey ? row[foundKey] : '';
      };

      return {
        id: `p-${i}-${Date.now()}`,
        fornecedor: findValue(['fornecedor', 'forn']),
        codigo: String(findValue(['código', 'codigo', 'cod'])),
        situacao: findValue(['situação', 'situacao', 'status']),
        comprador: findValue(['comprador']),
        produto: findValue(['produto', 'descrição', 'desc']),
        sabor: '',
        embalagem: '',
        estoqueMarsil: parseInt(findValue(['marsil', 'sp', 'estoque_sp'])) || 0,
        estoqueBoraceia: parseInt(findValue(['boraceia', 'boracéia', 'unidade_bor'])) || 0,
      };
    }).filter(p => p.produto && p.produto !== '');
  };

  useEffect(() => {
    localStorage.setItem(AUTH_KEY, authRole);
  }, [authRole]);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem(THEME_KEY, 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem(THEME_KEY, 'light');
    }
  }, [isDarkMode]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const requiredPass = loginTarget === 'admin' ? PASSWORDS.ADMIN : PASSWORDS.VENDOR;
    if (passwordInput === requiredPass) {
      setAuthRole(loginTarget === 'admin' ? 'admin' : 'vendor');
      setActiveTab(loginTarget === 'admin' ? 'admin' : 'user');
      setLoginError(false);
      setLoginTarget(null);
    } else {
      setLoginError(true);
      setTimeout(() => setLoginError(false), 3000);
    }
    setPasswordInput('');
  };

  const handleLogout = () => {
    setAuthRole('none');
    setLoginTarget(null);
    setActiveTab('user');
    localStorage.removeItem(AUTH_KEY);
  };

  return (
    <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-slate-950 text-gray-900 dark:text-slate-100 transition-colors duration-300">
      <header className="bg-white dark:bg-slate-900 border-b border-gray-200 dark:border-slate-800 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 flex justify-between items-center h-16">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-xl shrink-0">
              <LayoutDashboard className="w-5 h-5 text-white" />
            </div>
            <div className="flex flex-col">
              <h1 className="text-lg font-black tracking-tight">Marsil & Boracéia</h1>
              <p className="text-[9px] text-gray-400 font-bold uppercase">Sincronização Direta</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
            <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 text-gray-400 hover:text-blue-500">
              {isDarkMode ? <Sun className="w-4 h-4" /> : <Moon className="w-4 h-4" />}
            </button>
            {authRole !== 'none' && (
              <div className="flex items-center gap-2">
                <div className="bg-gray-100 dark:bg-slate-800 p-1 rounded-xl flex">
                  <button onClick={() => setActiveTab('user')} className={`px-3 py-1.5 text-[10px] font-black rounded-lg ${activeTab === 'user' ? 'bg-white dark:bg-slate-700 text-blue-600 shadow-sm' : 'text-gray-400'}`}>Estoque</button>
                  {authRole === 'admin' && <button onClick={() => setActiveTab('admin')} className={`px-3 py-1.5 text-[10px] font-black rounded-lg ${activeTab === 'admin' ? 'bg-white dark:bg-slate-700 text-blue-600 shadow-sm' : 'text-gray-400'}`}>Gestão</button>}
                </div>
                <button onClick={handleLogout} className="p-2 text-red-500 hover:bg-red-50 rounded-xl"><LogOut className="w-4 h-4" /></button>
              </div>
            )}
          </div>
        </div>
      </header>

      <main className="flex-grow p-4 sm:p-8">
        {isLoading ? (
          <div className="h-full flex flex-col items-center justify-center mt-20 gap-4">
            <Loader2 className="w-8 h-8 text-blue-600 animate-spin" />
            <p className="text-[10px] font-black uppercase tracking-widest text-gray-400">{syncMessage || 'Carregando Sistema...'}</p>
          </div>
        ) : authRole === 'none' ? (
          !loginTarget ? (
            <div className="max-w-2xl mx-auto mt-12 grid grid-cols-1 sm:grid-cols-2 gap-6">
              <button onClick={() => setLoginTarget('vendedor')} className="bg-white dark:bg-slate-900 p-8 rounded-3xl shadow-xl hover:shadow-2xl border-2 border-transparent hover:border-emerald-500 transition-all flex flex-col items-center space-y-4">
                <Store className="w-12 h-12 text-emerald-600" />
                <h3 className="text-xl font-bold">Vendedor</h3>
                <p className="text-[10px] font-black text-emerald-600 uppercase">Consultar Estoque <ChevronRight className="w-4 h-4 inline" /></p>
              </button>
              <button onClick={() => setLoginTarget('admin')} className="bg-white dark:bg-slate-900 p-8 rounded-3xl shadow-xl hover:shadow-2xl border-2 border-transparent hover:border-blue-500 transition-all flex flex-col items-center space-y-4">
                <ShieldCheck className="w-12 h-12 text-blue-600" />
                <h3 className="text-xl font-bold">Admin</h3>
                <p className="text-[10px] font-black text-blue-600 uppercase">Gestão da Planilha <ChevronRight className="w-4 h-4 inline" /></p>
              </button>
            </div>
          ) : (
            <div className="max-w-sm mx-auto mt-12 bg-white dark:bg-slate-900 p-8 rounded-3xl shadow-2xl relative">
              <button onClick={() => setLoginTarget(null)} className="absolute left-4 top-4 text-gray-400"><X className="w-4 h-4" /></button>
              <h2 className="text-2xl font-black text-center mb-6">Acesso</h2>
              <form onSubmit={handleLogin} className="space-y-4">
                <input autoFocus type="password" placeholder="Senha" value={passwordInput} onChange={(e) => setPasswordInput(e.target.value)} className="w-full px-4 py-4 rounded-2xl border bg-gray-50 dark:bg-slate-800 outline-none text-center font-bold" />
                {loginError && <p className="text-[9px] text-red-500 text-center font-bold uppercase">Senha Inválida</p>}
                <button className="w-full bg-blue-600 text-white font-black py-4 rounded-2xl uppercase text-xs">Entrar</button>
              </form>
            </div>
          )
        ) : (
          activeTab === 'user' ? (
            <UserPortal products={appState.products} requests={appState.requests} vendedores={appState.vendedores} whatsappConfig={appState.whatsappConfig} onSubmitRequest={(r) => {}} />
          ) : (
            <AdminPortal appState={appState} onUploadData={(p) => setAppState({...appState, products: p})} onAddVendedor={(v) => {}} onRemoveVendedor={(v) => {}} onUpdateWhatsApp={(w) => {}} onUpdateRequestStatus={(id, s) => {}} onClearRequests={() => {}} />
          )
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
