          <p className="text-[10px] font-black uppercase tracking-widest text-gray-400">Consulta de Estoque Online</p>
        </div>
        <div className="text-right">
          <p className="text-[9px] text-gray-400 font-bold uppercase tracking-tighter">Última Sincronização</p>
          <p className="text-xs font-black dark:text-white">Hoje, {new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
        </div>
      </div>

      <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl shadow-xl border border-gray-100 dark:border-slate-800">
        <h2 className="text-base font-black mb-4 flex items-center gap-2 uppercase tracking-widest dark:text-white">
          <Search className="w-5 h-5 text-blue-600" /> Consultar Itens
        </h2>
