          <input 
            type="text" 
            placeholder="Digite nome ou código (ex: 123)..." 
            className="w-full pl-12 pr-5 py-4 rounded-2xl border border-gray-100 dark:border-slate-800 bg-gray-50 dark:bg-slate-800 outline-none text-sm font-bold dark:text-white focus:ring-2 focus:ring-blue-500/20 transition-all"
            value={filter}
            onChange={(e) => setFilter(e.target.value)}
          />
        </div>

        {filter.length > 0 && filter.length < 3 && (
          <p className="mt-3 text-[10px] text-blue-500 font-bold text-center uppercase animate-pulse">Digite pelo menos 3 caracteres para buscar...</p>
        )}

        <div className="mt-6 space-y-3 max-h-[500px] overflow-y-auto custom-scrollbar pr-1">
          {filtered.map(p => (
            <button 
              key={p.id} 
              onClick={() => setSelected(p)}
              className={`w-full p-5 rounded-3xl border flex flex-col sm:flex-row sm:items-center justify-between gap-4 transition-all ${selected?.id === p.id ? 'border-blue-500 bg-blue-50 dark:bg-blue-900/20 ring-2 ring-blue-500/20' : 'border-gray-50 dark:border-slate-800 hover:bg-gray-50 dark:hover:bg-slate-800/60'}`}
