  "CARLOS ROSEIRO",
  "DOUGLAS PITELLI",
  "EDMILSON LEAL",
  "FERNANDO APARECIDO",
  "GUSTAVO PAULINO",
  "JOAO JOSE",
  "JOAO MANUEL",
  "LEONARDO APARECIDO",
  "LUIS ALEXANDRE",
  "MARCELO SANTOS",
  "MARCO AURELIO",
  "NIVALDO NEVES",
  "ROSIMAR FREITAS",
  "ROZIMARA SOUZA",
