      if (urlSync) {
        localStorage.setItem(SYNC_URL_KEY, urlSync);
        Papa.parse(urlSync, {
          download: true,
          header: true,
          skipEmptyLines: true,
          complete: (results) => {
            const mapped = mapCSVData(results.data);
